window.EXAMS = [{"id":"his-2026","subj":"his","titulo":"Exame de Fundamento de História","inst":"Comissão de Exames de Admissão","ano":2026,"tempo":120,"q":[{"n":1,"tema":"Historiografia","p":"Na Bíblia (Antigo Testamento), está expressa a historiografia Judaica. Esta contém várias temáticas. Qual é o carácter dos textos bíblicos?","o":["Proféticos, religiosos e mitológicos","Religiosos, mitológicos e ecuménicos","Cosmogónicos, ecuménicos e proféticos","Religiosos, cosmogónicos e mitológicos"],"c":3,"e":"Os textos bíblicos têm carácter religioso, mitológico e cosmogónico (narrativas da criação do mundo). Há também textos proféticos, pelo que a formulação é ambígua; melhor leitura: D.","d":1},{"n":2,"tema":"Historiografia","p":"Tácito foi um dos historiadores romanos mais controversos e destacados. A quem dedicava os seus escritos?","o":["Reinado de Nero e vitórias dos imperadores","Reinado dos Flávios e vitórias dos imperadores","Reinado dos imperadores Plutarco e Éforo","A vida cotidiana dos imperadores"],"c":1,"e":"Tácito escreveu as <i>Histórias</i> (dinastia flaviana) e os <i>Anais</i> (de Tibério a Nero), centrados nos imperadores. Plutarco e Éforo não foram imperadores. A e B são ambas defensáveis; melhor leitura: B (Flávios).","d":1},{"n":3,"tema":"Historiografia","p":"A historiografia cristã procurava revelar a fé cristã. Por que é que a historiografia cristã antiga é considerada providencialista?","o":["Prioriza a intervenção de Deus perante os feitos do Homem.","Prioriza a intervenção de Jesus Cristo em todas as acções.","Prioriza a intervenção de Deus e dos Homens na humanidade.","Era feita pelos sacerdotes para registar os feitos dos reis."],"c":0,"e":"Providencialismo é a ideia de que a história é conduzida pela vontade divina, que se sobrepõe às acções humanas."},{"n":4,"tema":"Historiografia","p":"A historiografia cristã medieval surge com a queda do império romano do ocidente no século IV. Identifique os géneros literários predominantes.","o":["Anais e crónicas","Anais Gentílicos","Anuários e diários","Crónicas gentílicas"],"c":0,"e":"Os géneros típicos da historiografia medieval foram os anais (registo ano a ano) e as crónicas."},{"n":5,"tema":"Historiografia","p":"A historiografia do renascimento foi registada por vários autores, com destaque para um representante. Identifique-o.","o":["Francis Bacon","Nicolau Maquiavel","Jean Bodin","Fernão Lopes"],"c":1,"e":"Maquiavel (<i>História de Florença</i>, <i>O Príncipe</i>) é o grande representante da historiografia renascentista, que seculariza a explicação histórica."},{"n":6,"tema":"Historiografia","p":"O historiador deve ser independente perante as autoridades e ser responsável perante o povo. Identifica o defensor desta razão.","o":["Francis Bacon","Nicolau Maquiavel","Jean Bodin","Fernão Lopes"],"c":3,"e":"Fernão Lopes, cronista português do século XV, é apontado como modelo de historiador que procura a verdade com independência e dá voz ao povo. Questão pouco clara; melhor leitura: D.","d":1},{"n":7,"tema":"Historiografia","p":"O processo histórico é determinado pela intervenção divina e por factores naturais. Quem defende esta ideia?","o":["René Descartes","John Locke","Bossuet","Voltaire"],"c":2,"e":"Bossuet (<i>Discurso sobre a História Universal</i>) defendia a história guiada pela Providência divina; Voltaire e Locke são racionalistas/iluministas."},{"n":8,"tema":"Historiografia","p":"A história estuda as condições materiais da existência dos homens. Quem defendia este pensamento?","o":["Annales","Romancistas","Positivistas","Marxistas"],"c":3,"e":"O materialismo histórico marxista explica a história pelas condições materiais e modos de produção."},{"n":9,"tema":"Historiografia","p":"O século XX é marcado por uma crise da história. Identifica uma das causas do colapso.","o":["Aparecimento da escola dos Annales.","Aparecimento de outras ciências sociais.","O desenvolvimento do pensamento positivista.","O desenvolvimento do pensamento Marxista."],"c":1,"e":"Sociologia, economia, antropologia e outras ciências sociais disputaram à história o estudo do homem em sociedade, originando a crise."},{"n":10,"tema":"Historiografia","p":"A história não se deve limitar a descrever os acontecimentos, mas procurar pôr problemas. Identifique os defensores desta ideia.","o":["Annales","Romancistas","Positivistas","Marxistas"],"c":0,"e":"A escola dos Annales (Bloch, Febvre) propôs a história-problema, em oposição à história meramente narrativa positivista."},{"n":11,"tema":"Historiografia","p":"Não existe história antes da escrita, por isso, não existe história de África antes da chegada dos europeus. Identifica um dos autores deste pensamento.","o":["Vasco da Gama","Philip Curtin","Teófilo Obenga","A. P. Newton"],"c":3,"e":"A. P. Newton integra a corrente eurocentrista que negava história a África sem escrita. Curtin e Obenga defenderam a história africana."},{"n":12,"tema":"História Geral","p":"A escrita serve para comunicar. Identifique o povo que desenvolveu a escrita cuneiforme.","o":["Egípcios","Hititas","Sumérios","Persas"],"c":2,"e":"Os Sumérios da Mesopotâmia inventaram a escrita cuneiforme por volta de 3300-3000 a.C."},{"n":13,"tema":"História Geral","p":"Qual é a principal fonte para o estudo da História de África?","o":["Oral","Arqueológica","Escrita","Ambas"],"c":0,"e":"Pela escassez de fontes escritas antigas, a tradição oral é considerada a principal fonte (Vansina). Contudo, \"Ambas\" (oral e arqueológica) é tentadora; melhor leitura: A.","d":1},{"n":14,"tema":"História Geral","p":"De que conhecimento se vale o historiador para estudar a qualidade de vida de um povo no tempo e espaço?","o":["Geografia económica","Economia","Antropologia económica","Arqueologia"],"c":2,"e":"A antropologia económica estuda a organização económica e o modo de vida das sociedades. Questão pouco precisa; melhor leitura: C.","d":1},{"n":15,"tema":"História Geral","p":"Identifique as manifestações artísticas do paleolítico em Moçambique.","o":["Rupestre e estátuas","Parietal e móvel","Estatuetas e móvel","Escultura móvel"],"c":1,"e":"A arte paleolítica divide-se em arte parietal (em paredes de rocha) e arte móvel (objectos transportáveis)."},{"n":16,"tema":"História Geral","p":"A prática da agricultura constitui a primeira parte da revolução Neolítica. Onde foi desenvolvida a agricultura pela primeira vez?","o":["Vale do rio Nilo","No Egipto Antigo","Na Mesopotâmia","No crescente Fértil"],"c":3,"e":"A agricultura surgiu no Crescente Fértil (Médio Oriente), por volta de 10 000 a.C.; a Mesopotâmia é apenas parte dessa região."},{"n":17,"tema":"História Geral","p":"A crença na imortalidade da alma levou os egípcios a desenvolver a técnica da mumificação dos corpos. Onde eram depositadas as múmias dos faraós?","o":["Nas pirâmides","Nas mastabas","Nos sarcófagos","Nos Hipogeus"],"c":0,"e":"Nas pirâmides, túmulos monumentais dos faraós (sobretudo no Império Antigo). Os hipogeus (Vale dos Reis) são defensáveis para o Império Novo; melhor leitura: A.","d":1},{"n":18,"tema":"História Geral","p":"A pintura e escultura egípcia obedeciam leis. Identifique-as:","o":["Decoração em Marfim, pedra, ouro e vidro.","Direitos Humanos e escalas diferentes.","Frontalidade, omissão e hierarquia.","Cabeça em perfil, tronco de frente e hierarquia."],"c":2,"e":"As convenções da arte egípcia incluem frontalidade, hierarquia (escala conforme a importância) e omissão de pormenores. D descreve a posição da figura, não as leis; resposta incerta.","d":1},{"n":19,"tema":"História Geral","p":"Os Sumérios eram politeístas. Identifica as suas principais divindades.","o":["Ur, Inna-Ishtar, Uruk e Lagash","Anu, Enlil, Enki e Inna-Ishtar","Anu, Enlil, Uruk e Lagash","Enki, Inna-Ishtar, Anu, Enlil, Uruk e Lagash"],"c":1,"e":"Anu (céu), Enlil (ar), Enki (águas) e Inanna-Ishtar (amor/guerra). Ur, Uruk e Lagash são cidades-estado."},{"n":20,"tema":"História Geral","p":"Os primeiros jogos Olímpicos decorreram na cidade de Olímpia, na Grécia. Quando foram realizados?","o":["776 d.C.","776 a.C.","777 d.C.","777 a.C."],"c":1,"e":"Datam tradicionalmente de 776 a.C."},{"n":21,"tema":"História Geral","p":"A Grécia contava com muitas cidades-estado como Mileto, Tebas, Atenas, Corinto, Éfeso e Esparta. Qual destas era poderosa económica e militarmente?","o":["Esparta","Mileto","Tebas","Atenas"],"c":3,"e":"Atenas reunia poder naval, comércio e riqueza (Liga de Delos). Esparta era sobretudo militar."},{"n":22,"tema":"História Geral","p":"O Renascimento foi um movimento intelectual e de renovação cultural que se desenvolveu na Itália nos séculos XIV e XV. Identifique a principal característica deste movimento.","o":["Imitação da cultura e da arte da Antiguidade Grega e Persa.","Valorização da cultura e da arte da Antiguidade Egípcia e Grega.","Imitação da cultura e da arte da Antiguidade Greco-romana.","Redescoberta da cultura e da arte da Antiguidade Indo-Europeia."],"c":2,"e":"O Renascimento retomou o modelo clássico greco-romano."},{"n":23,"tema":"História Geral","p":"A reforma religiosa dividiu a Europa Cristã em dois blocos, que são:","o":["Norte Protestante e o Sul Católico.","Oriente Protestante e o ocidente Católico.","Nordeste Protestante e o sudeste Católico.","Norte Católico e o Sul Protestante."],"c":0,"e":"A Reforma fixou o Norte protestante (Alemanha do Norte, Escandinávia, Inglaterra) e o Sul católico (Itália, Espanha, Portugal)."},{"n":24,"tema":"História Geral","p":"\"O Estado sou eu\". A quem pertence esta frase?","o":["Filipe Nhussi","Luís XIV","Vladmir Putin","Luís XVI"],"c":1,"e":"Frase atribuída a Luís XIV, o Rei-Sol, símbolo do absolutismo."},{"n":25,"tema":"História Geral","p":"O Homem deve ter a mente iluminada para se libertar da ignorância. Qual a corrente defensora deste pensamento?","o":["Racionalismo","Fisiocratismo","Iluminismo","Pombalismo"],"c":2,"e":"O Iluminismo (século das Luzes) defendia a razão como caminho para vencer a ignorância."},{"n":26,"tema":"História Geral","p":"O estado de ditadura fascista surgiu em 1926 e se consolidou em 1930. Identifique a figura importante no regime.","o":["António Salazar","Salazar Caetano","Mouzinho de Albuquerque","António Enes"],"c":0,"e":"António de Oliveira Salazar, ministro das Finanças em 1928 e chefe do Estado Novo português. Os restantes não correspondem."},{"n":27,"tema":"História Geral","p":"A maior revolta de escravos da história romana foi liderada por um gladiador de origem trácia chamado:","o":["Alarico","Teodorico","Ataúlfo","Espártaco"],"c":3,"e":"Espártaco liderou a Terceira Guerra Servil (73-71 a.C.)."},{"n":28,"tema":"História Geral","p":"Em termos de perda territorial da Alemanha após a Primeira Guerra Mundial, foram tirados os territórios da:","o":["Renânia","Bavária","Alsácia e Lorena","Munich"],"c":2,"e":"O Tratado de Versalhes devolveu a Alsácia e Lorena à França. A Renânia foi apenas desmilitarizada e ocupada."},{"n":29,"tema":"História Geral","p":"Qual evento foi responsável pela ascensão de Benito Mussolini ao poder na Itália na década de 1920?","o":["Revolução de Roma","Tratado de Latrão","Marcha sobre Roma","Noite dos Longos Punhais"],"c":2,"e":"Em Outubro de 1922, a Marcha sobre Roma levou o rei a nomear Mussolini chefe do governo."},{"n":30,"tema":"História de África","p":"Em 1859, inicia a construção do canal de Suez que liga o Mar Mediterrâneo e o Mar Vermelho. Em que ano foi aberto o canal?","o":["1869","1890","1769","1790"],"c":0,"e":"O canal de Suez foi inaugurado em Novembro de 1869."},{"n":31,"tema":"História de África","p":"Arabi Paxá foi um destacado líder de resistência em África. Em que país defendeu a soberania e independência?","o":["Argélia","Líbia","Marrocos","Egipto"],"c":3,"e":"Ahmed Urabi (Arabi Paxá) liderou a revolta nacionalista egípcia de 1881-82, esmagada pelos britânicos."},{"n":32,"tema":"História de África","p":"A guerra contra ocupação colonial na Argélia foi encabeçada por um líder religioso. Identifica-o.","o":["Muhamad Ali","Meemet Ali","Arabi Paxá","Abd al-Qadir"],"c":3,"e":"O emir Abd al-Qadir resistiu à conquista francesa da Argélia (1832-1847)."},{"n":33,"tema":"História de África","p":"Em 1804, os escravos do Haiti revoltaram-se contra o governo francês e constituíram o primeiro governo negro. Que resultado teve esta revolta?","o":["Início do movimento nacionalista","Início do movimento pan-africano","Início do movimento pan-africano e nacionalista","Início da Luta pela independência dos países colonizados"],"c":1,"e":"A revolução haitiana inspirou o pan-africanismo, nascido entre a diáspora negra das Américas. Opções sobrepostas; melhor leitura: B.","d":1},{"n":34,"tema":"História de África","p":"No congresso Pan-africano realizado em Manchester, em 1945, participou uma figura moçambicana incontornável na História do nosso País. Identifique-a.","o":["Joaquim Chissano","Samora Machel","Marcelino dos Santos","Eduardo Mondlane"],"c":3,"e":"Nenhuma das figuras é historicamente confirmada em Manchester 1945; a melhor leitura (provável intenção do exame) é Eduardo Mondlane, figura central do pan-africanismo moçambicano.","d":1},{"n":35,"tema":"História de África","p":"Em 1947, no Gana, Danquah fundou a Convenção Unida da Costa do Ouro (UGCC). Qual era o slogan do partido?","o":["Discussão para autonomia e independência via pacífica","Discussão para autonomia o mais breve possível","Alcançar a independência imediata via luta armada","Desencadear a luta armada o mais rápido possível"],"c":1,"e":"O lema da UGCC era \"autogoverno no mais curto prazo possível\" (self-government in the shortest possible time); Nkrumah queria \"já\"."},{"n":36,"tema":"História de África","p":"Depois da independência de Congo (1960) foi marcado por várias crises, uma das quais foi a declaração de independência da província de Katanga. Localize, no tempo, o acontecimento.","o":["30 de Junho de 1960","03 de Fevereiro de 1960","17 de Janeiro de 1961","17 de Julho de 1960"],"c":3,"e":"Katanga (Tshombe) proclamou a secessão a 11 de Julho de 1960; nenhuma opção é exacta. A mais próxima (Julho de 1960) é D; 30 de Junho é a independência do Congo.","d":1},{"n":37,"tema":"História de África","p":"A OUA foi criada em 25 de Maio de 1963 em Addis Abeba. Que objectivos almejava esta organização?","o":["Promover a unidade e solidariedade dos estados africanos; erradicar o colonialismo","Democratizar o continente africano e criar condições para uma boa solidariedade","Promover a unidade entre os estados africanos; e apoiar a descolonização dos países africanos","Organizar e supervisionar a realização de eleições livres e justas nos países africanos"],"c":0,"e":"A Carta da OUA previa unidade e solidariedade e a erradicação de todas as formas de colonialismo."},{"n":38,"tema":"História de África","p":"A 09 de Julho de 2002, na África do Sul, foi lançada oficialmente a União Africana. Identifique os princípios desta organização.","o":["Respeito das fronteiras; não ingerência nos assuntos de outros estados","Respeito pelos tratados bilaterais; resolução de conflitos entre estados","Consolidação dos comités regionais; criação de gabinetes regionais para resolver conflitos","Solidariedade dos estados; não interferir na soberania de outros estados"],"c":0,"e":"O Acto Constitutivo da UA consagra o respeito das fronteiras herdadas e a não ingerência nos assuntos internos. D é parecida, mas A é mais fiel ao texto."},{"n":39,"tema":"História de África","p":"O Tratado de Naivasha, assinado em 9 de Janeiro de 2005 no Quénia, abriu espaço para o reconhecimento do último estado independente em África. De que Estado se trata?","o":["Sudão do Sul em 9 de Julho de 2011","República da Libéria em 9 de Janeiro de 2005","Sudão do Norte em 11 de Agosto de 2011","Nova Zimbabwe em 13 de Maio de 2012"],"c":0,"e":"O Acordo de Naivasha levou ao referendo e à independência do Sudão do Sul a 9 de Julho de 2011."},{"n":40,"tema":"História de Moçambique","p":"A fixação portuguesa em Moçambique data do século XVI. Qual fortificação construíram em 1505, sendo a primeira estrutura permanente europeia na costa de Moçambique?","o":["Fortaleza de São Sebastião","Forte de Jesus","Feitoria de Sofala","Fortim de Quelimane"],"c":2,"e":"Em 1505 Pêro de Anaia fundou a feitoria-fortaleza de Sofala. São Sebastião (Ilha de Moçambique) é de 1558 e o Forte de Jesus fica em Mombaça."},{"n":41,"tema":"História de Moçambique","p":"Durante o século XIX, a administração colonial portuguesa em Moçambique foi marcada pelo uso de Companhias Majestáticas. Qual era a principal característica desse sistema de administração?","o":["O investimento directo e exclusivo do Estado português na exploração dos recursos.","A concessão de vastos territórios a empresas privadas, que tinham direitos quase soberanos de administração e exploração.","A partilha equitativa dos lucros do comércio com as populações locais.","A proibição de qualquer envolvimento britânico ou francês na economia moçambicana."],"c":1,"e":"As companhias majestáticas (Moçambique, Niassa, Zambézia) receberam territórios com poderes de administração, tributação e exploração."},{"n":42,"tema":"História de Moçambique","p":"Moçambique alcançou a independência em 1975. Que ideologia política foi adoptada pela FRELIMO após a independência?","o":["Capitalismo liberal","Socialismo","Fascismo","Monarquia constitucional"],"c":1,"e":"Em 1977 (III Congresso) a FRELIMO adoptou o marxismo-leninismo e o socialismo."},{"n":43,"tema":"História de Moçambique","p":"A Guerra Civil Moçambicana opôs o governo da Frelimo e a guerrilha da Renamo. Que países apoiaram a Renamo militar e logisticamente durante o conflito?","o":["União Soviética e Cuba","Tanzânia e Zâmbia","África do Sul e Rodésia","Brasil e Angola"],"c":2,"e":"A Renamo foi criada pela Rodésia de Ian Smith e depois apoiada pela África do Sul do apartheid."},{"n":44,"tema":"História de Moçambique","p":"Moçambique e África do Sul assinaram o Acordo de Nkomati em 1984. Qual era o objectivo do acordo?","o":["Formalizar uma aliança militar contra a Rodésia.","Acabar com o apoio mútuo aos movimentos rebeldes","Estabelecer uma zona de comércio livre entre os dois países.","Implementar sanções económicas contra a Rodésia."],"c":1,"e":"Nkomati (16 de Março de 1984): Moçambique deixava de apoiar o ANC e a África do Sul de apoiar a Renamo."},{"n":45,"tema":"História de Moçambique","p":"Em 1992 foi assinado o Acordo Geral de Paz de Roma que pôs fim à guerra civil em Moçambique. Qual foi o principal mediador deste acordo?","o":["A Organização das Nações Unidas","A Igreja Católica, através da Comunidade de Santo Egídio","A Organização da Unidade Africana (OUA)","Os Estados Unidos da América"],"c":1,"e":"A mediação foi conduzida pela Comunidade de Santo Egídio, com a Igreja Católica, o Governo italiano e outros observadores."},{"n":46,"tema":"História de Moçambique","p":"A Constituição de 1990 foi um marco importante na transição política do país. O que introduziu no sistema de governo?","o":["O sistema de partido único.","O multipartidarismo e a economia de mercado.","A independência total do poder judicial em relação ao executivo.","O retorno ao sistema de Companhias Majestáticas."],"c":1,"e":"A Constituição de 1990 instituiu o multipartidarismo, as liberdades fundamentais e a economia de mercado."},{"n":47,"tema":"História de Moçambique","p":"Qual dos seguintes eventos não ocorreu durante a luta armada de libertação nacional?","o":["A criação do Destacamento Feminino da FRELIMO.","O assassinato de Filipe Samuel Magaia, vice-presidente da FRELIMO.","A assinatura do Acordo Geral de Paz de Roma","O II Congresso da FRELIMO."],"c":2,"e":"O Acordo de Roma é de 1992, posterior à luta de libertação (1964-1974). As outras ocorreram nesse período (DF em 1967, Magaia em 1966, II Congresso em 1968)."},{"n":48,"tema":"História de Moçambique","p":"Nos finais do séc. XVIII, Moçambique foi marcado pelo tráfico de escravos. Qual foi o principal porto utilizado para o transporte de escravos durante o auge do tráfico negreiro?","o":["Porto da Beira","Porto de Quelimane","Porto de Maputo","Porto de Nacala"],"c":1,"e":"Quelimane, na foz do sistema do Zambeze, foi um dos principais portos de exportação de escravos; Beira e Nacala só surgiram depois. Ilha de Moçambique também foi importante, mas não consta das opções."},{"n":49,"tema":"História de Moçambique","p":"O Plano Marshall para Moçambique foi uma expressão utilizada após a guerra civil e as cheias de 2000 para descrever:","o":["A intervenção militar da ONU para manter a paz.","O grande esforço internacional de ajuda humanitária e reconstrução do país.","O plano do governo para desenvolver a indústria pesada.","O acordo de partilha de poder entre FRELIMO e RENAMO."],"c":1,"e":"A expressão designa a vasta ajuda internacional de reconstrução, por analogia com o Plano Marshall europeu."},{"n":50,"tema":"História de Moçambique","p":"Os bantu não são autóctones de Moçambique. Identifica as causas da expansão bantu.","o":["A difusão da tecnologia do ferro e lutas internas.","A difusão da tecnologia do ferro, aumento da população e falta de terras férteis.","A difusão da tecnologia do ferro e falta de terras férteis e lutas internas.","Desenvolvimento tecnológico, mineração e criação do gado."],"c":1,"e":"Ferro, crescimento demográfico e esgotamento das terras férteis são as causas clássicas apontadas. C é parcialmente defensável."},{"n":51,"tema":"História de Moçambique","p":"A emergência de conflitos no seio da linhagem dominante Marave culminaram com a formação de outros estados. Identifica-os.","o":["Torwa, Banda, Undi e Yao","Sedanda, Quissanga, Quiteve e Maungwe","Undi, Kapwiti, Biwi e Lundu","Banda, Torwa, Sedanda e Quiteve"],"c":2,"e":"Da fragmentação Maravi resultaram os estados Undi, Kalonga/Kapwiti, Biwi e Lundu. Torwa, Sedanda e Quiteve pertencem ao mundo shona."},{"n":52,"tema":"História de Moçambique","p":"A presença árabe levou ao surgimento de novas línguas. Que línguas resultaram da fusão entre africanas e árabes?","o":["Mwali, sena e ndau","Mwani, nahara e coti","Mwani, wahara e coti","Chewa, Makwa e shona"],"c":1,"e":"Mwani, nahara e coti são línguas/dialectos da costa norte resultantes do contacto bantu-árabe (swahili)."},{"n":53,"tema":"História de Moçambique","p":"A delimitação de fronteiras de Moçambique data do séc. XIX. Em que ano foi delimitada a fronteira norte?","o":["1869","1891","1886","1876"],"c":2,"e":"A fronteira norte (rio Rovuma) foi fixada pelo acordo luso-alemão de 1886. 1891 é o tratado luso-britânico (fronteiras oeste/sul). Alguns manuais divergem.","d":1},{"n":54,"tema":"História de Moçambique","p":"A companhia do Niassa foi formada em Março de 1893. Quando foi introduzido o imposto nesta companhia?","o":["1897","1898","1896","1894"],"c":0,"e":"Não consegui confirmar a data em fontes online; a melhor leitura, segundo manuais de História de Moçambique, é 1897.","d":1},{"n":55,"tema":"História de Moçambique","p":"O período de concessão da Companhia de Moçambique, durante o qual administrou os territórios com direitos majestáticos, ocorreu entre que anos?","o":["1885 e 1930","1892 e 1942","1900 e 1950","1920 e 1960"],"c":1,"e":"Carta de 1891 e administração efectiva de 1892 a 1942 (Manica e Sofala)."},{"n":56,"tema":"História de Moçambique","p":"Após o término da concessão em 1942, o que aconteceu aos territórios administrados pela Companhia de Moçambique?","o":["Tornaram-se imediatamente independentes.","Foram vendidos a outra potência colonial, como a Inglaterra.","Foram incorporados na administração directa do Estado português.","Continuaram a ser geridos pela Companhia, mas apenas como empresa comercial."],"c":2,"e":"Em 1942 Manica e Sofala passaram à administração directa do Estado português."},{"n":57,"tema":"História de Moçambique","p":"Que tipo de acordos foram estabelecidos entre as autoridades portuguesas e a Chamber of Mines da África do Sul para gerir o fluxo de trabalhadores migratórios?","o":["Acordos informais e não oficiais.","Acordos e convenções formais, como o Modus Vivendi de 1901 e a Convenção de 1928, que regulavam o recrutamento e as condições.","Tratados de livre circulação de pessoas e bens.","Acordos de partilha de lucros das minas."],"c":1,"e":"O Modus Vivendi (1901) e as convenções de 1909 e 1928 regularam o recrutamento de mineiros moçambicanos."},{"n":58,"tema":"História de Moçambique","p":"O Acto Colonial (1930) foi um pilar jurídico do Estado Novo que reforçou o nacionalismo económico no contexto ultramarino. Qual era o seu propósito em relação às colónias?","o":["Promover a autonomia económica das colónias portuguesas.","Integrar as economias coloniais na economia global de forma independente.","Garantir as \"garantias económicas e financeiras\" da metrópole sobre as colónias, reforçando o exclusivo colonial.","Permitir que as colónias estabelecessem as suas próprias políticas comerciais com outras nações."],"c":2,"e":"O Acto Colonial subordinou as economias coloniais aos interesses da metrópole (exclusivo colonial)."},{"n":59,"tema":"História de Moçambique","p":"Após a independência de Moçambique em 1975, que medidas o novo governo (FRELIMO) tentou implementar em relação à cultura do algodão?","o":["Abolição imediata de todo o cultivo de algodão.","Manutenção do sistema colonial de cultura obrigatória.","Transformação da cultura do algodão, de base coerciva para uma cultura virada para o desenvolvimento dos camponeses, através de machambas estatais e cooperativas.","Venda de todas as plantações de algodão a empresas multinacionais."],"c":2,"e":"Fim do cultivo forçado e opção por empresas estatais e cooperativas, alinhadas com a política socialista."},{"n":60,"tema":"História de Moçambique","p":"Em 1957 surge a Sociedade Algodoeira Africana Voluntária de Moçambique. Identifique os seus dirigentes.","o":["Lázaro Kavandane, Raimundo Pachinuapa, João Namimba e Cornélio Mandanda","Alberto Chipande, Raimundo Pachinuapa, João Namimba e Cornélio Mandanda.","Alberto Chissano, Lázaro Kavandane, Armando Guebuza e Raimundo Pachinuapa","Marcelino dos Santos, Samora Machel, Eduardo Mondlane"],"c":0,"e":"A SAAVM, de Cabo Delgado, foi dirigida por Lázaro Kavandame e companheiros como Pachinuapa, Namimba e Mandanda, depois ligados à FRELIMO."}]},{"id":"his-up-2024","subj":"his","titulo":"Exame de História","inst":"Universidade Pedagógica (UP)","ano":2024,"tempo":120,"q":[{"n":1,"tema":"Historiografia","p":"As primeiras literaturas de carácter histórico foram:","o":["Os antigos escritos hieróglifos egípcios.","As cosmogonias e mitografias.","O código de Hamurabi.","Os antigos escritos cuneiformes sobre a Mesopotâmia."],"c":1,"e":"As primeiras formas de literatura com carácter histórico foram as cosmogonias e mitografias, narrativas míticas sobre a origem do mundo e dos povos, anteriores à historiografia propriamente dita."},{"n":2,"tema":"Historiografia","p":"A Ciência que tem relação com a História e que estuda as moedas e as medalhas, consideradas sob o ponto de vista morfológico e interpretativo, chama-se:","o":["Paleografia.","Onomástica.","Linguística.","Numismática."],"c":3,"e":"A Numismática é a ciência auxiliar que estuda moedas e medalhas. A Paleografia estuda escritas antigas e a Onomástica os nomes."},{"n":3,"tema":"Historiografia","p":"As fontes escritas epigráficas são aquelas que se:","o":["Encontram gravadas em materiais como pergaminho, cerâmica e bronze.","Encontram gravadas em materiais como bronze, mármore e cerâmica.","Encontram gravadas em materiais como Bíblia, mármore e papiro.","Encontram gravadas em materiais como pergaminho, diplomas e actas."],"c":1,"e":"A epigrafia estuda inscrições gravadas em materiais duros (pedra, mármore, metal, cerâmica). Pergaminho e papiro são suportes de outra natureza (paleografia)."},{"n":4,"tema":"Historiografia","p":"Das Historiografias que se seguem as antigas são:","o":["Historiografia Judaica, Historiografia Grega, Historiografia Romana e Historiografia Cristã.","Cosmogonias, Historiografia Judaica, Historiografia Grega, Historiografia Romana, Historiografia Cristã e Historiografia Marxista.","Historiografia Judaica, Historiografia Grega, Historiografia Romana e Historiografia Cristã Antiga.","Historiografia Judaica, Historiografia Grega, Historiografia Romana e Historiografia Cristã Antiga e Medieval e Historiografia Marxista."],"c":2,"e":"As historiografias da Antiguidade são a judaica, a grega, a romana e a cristã antiga. A marxista é do século XIX e a medieval pertence ao período seguinte."},{"n":5,"tema":"Historiografia","p":"Para além dos anais, as fontes da historiografia medieval incluem as <i>Hagiografias</i> que eram constituídas por:","o":["Biografias dos santos","Diplomas de origem papal","Manuais de confessores","Actas de concílios e sínodos"],"c":0,"e":"Hagiografia (do grego <i>hagios</i>, santo) é a escrita das vidas dos santos."},{"n":6,"tema":"Historiografia","p":"Na impossibilidade de encontrar fontes fidedignas acerca das origens de Roma, qual dos seguintes historiadores não hesitava em recorrer à tradição lendária?","o":["Tito Lívio","Tácito","Políbio","Heródoto"],"c":0,"e":"Tito Lívio, na obra <i>Ab Urbe Condita</i>, relatou as origens de Roma recorrendo às lendas (Eneias, Rómulo e Remo). Políbio era mais crítico."},{"n":7,"tema":"Historiografia","p":"Apesar dos grandes contributos dados pela historiografia positivista, ela recebeu algumas críticas pelo facto de:","o":["Defender a relatividade do conhecimento em oposição ao conhecimento absoluto.","Reconhecer apenas três estágios da evolução da sociedade: Teológico, Metafísico e Positivo.","Reduzir o papel do historiador e tentar formular leis para explicar os factos históricos.","Não se ter enquadrado nos debates entre os idealistas e os materialistas."],"c":2,"e":"O positivismo foi criticado por reduzir o historiador a um mero coligidor de factos objectivos e por procurar leis gerais (como nas ciências naturais). A opção A descreve o contrário do que defendia. Melhor leitura: C.","d":1},{"n":8,"tema":"Historiografia","p":"A divisão geral da história da humanidade, adoptando, como critério, a evolução dos modos de produção, no século XIX, foi obra de:","o":["Augusto Comte, no contexto do positivismo.","Hegel, no contexto do historicismo.","Ki-Zerbo, no contexto da evolução dos hominídeos.","Karl Marx, no contexto do materialismo histórico."],"c":3,"e":"Karl Marx, no materialismo histórico, periodizou a história pelos modos de produção: comunidade primitiva, escravatura, feudalismo, capitalismo e socialismo."},{"n":9,"tema":"Historiografia","p":"A historiografia palaciana caracteriza-se por:","o":["Ser de iniciativa eclesiástica, produzida por cronistas.","Ser produzida pelos monges nos palácios.","Preocupar-se em transmitir uma imagem fiel e objectiva da instituição servida pelo cronista.","Preocupar-se em transmitir uma imagem mais conveniente à instituição servida pelo cronista."],"c":3,"e":"A historiografia palaciana era feita por cronistas ao serviço da corte, que davam a imagem mais favorável da instituição que serviam, e não uma imagem objectiva."},{"n":10,"tema":"Historiografia","p":"Na historiografia moçambicana a obra “Lutar por Moçambique” pertence a:","o":["Newitt (nome parcialmente ilegível no original)","Allen Isaacman.","Noémia de Sousa.","Eduardo Mondlane."],"c":3,"e":"<i>Lutar por Moçambique</i> (<i>The Struggle for Mozambique</i>) é de Eduardo Mondlane, primeiro presidente da FRELIMO."},{"n":11,"tema":"Historiografia","p":"O Método Crítico em História compreende duas principais operações que são:","o":["A hermenêutica e a síntese.","Heurística e hermenêutica","Análise e síntese.","A Crítica Externa ou de Autenticidade e a crítica Interna ou de Credibilidade."],"c":3,"e":"O método crítico abrange a crítica externa (autenticidade e proveniência do documento) e a crítica interna (credibilidade do conteúdo)."},{"n":12,"tema":"História Geral","p":"As primeiras sociedades de classes foram:","o":["Grega e Romana","Egípcia e Mesopotâmica","Egípcia e Indiana","Americana e Europeia"],"c":1,"e":"As primeiras sociedades divididas em classes surgiram no Egipto e na Mesopotâmia (Oriente Antigo), por volta do IV milénio a.C."},{"n":13,"tema":"História Geral","p":"Na periodização da História considera-se que a queda do Império Romano do Ocidente marca o início da Idade Média. Esta ocorreu no ano de:","o":["1543.","1914.","476.","1505."],"c":2,"e":"Em 476 d.C., Odoacro depôs Rómulo Augústulo, último imperador romano do Ocidente."},{"n":14,"tema":"História Geral","p":"Dos três movimentos que configuraram a reforma religiosa, o Calvinismo defendia:","o":["A salvação pela e não pelos seus actos","A teoria da predestinação","Igrejas sem imagens","Salvação pela fé e pelas boas acções"],"c":1,"e":"A doutrina distintiva de Calvino é a predestinação: Deus escolheu de antemão os salvos. A salvação pela fé é também luterana."},{"n":15,"tema":"História Geral","p":"A primeira Constituição que contemplava a separação de poderes foi:","o":["Americana de 1777.","Francesa de 1789.","Americana de 1787.","Inglesa de 1642"],"c":2,"e":"A Constituição dos Estados Unidos de 1787 consagrou a separação entre legislativo, executivo e judicial, inspirada em Montesquieu."},{"n":16,"tema":"História Geral","p":"No contexto das fases da Primeira Guerra Mundial, a 1ª fase consistiu em:","o":["Guerra relâmpago, destacando-se a batalha de Marne e a conquista da Polónia.","Guerra relâmpago, destacando-se a batalha de Verdun e a conquista da Roménia.","Guerra relâmpago, destacando-se a batalha de Jutlândia e a conquista da Polónia.","Guerra relâmpago, destacando-se a batalha de Normandia e a conquista dos Balcãs."],"c":0,"e":"A 1ª fase (1914-1915) foi de guerra de movimento ou relâmpago, com a batalha do Marne (1914). Verdun (1916) e Jutlândia (1916) são posteriores e a Normandia é de 1944."},{"n":17,"tema":"História Geral","p":"Com o fim da 1ª Guerra Mundial, desenha-se um novo mapa político da europa, como resultado do desmembramento de alguns Impérios e surgimento de novos estados independentes, sendo exemplos:","o":["O desmembramento do império Bizantino, a independência da Normandia.","O desmembramento do império austro-húngaro, a independência da Bruxelas.","O desmembramento do império Britânico, a independência da Bélgica.","O desmembramento do império austro-húngaro, a independência da Checoslováquia."],"c":3,"e":"O Império Austro-Húngaro desmembrou-se em 1918, surgindo a Checoslováquia, a Áustria, a Hungria e outros Estados."},{"n":18,"tema":"História Geral","p":"A Conferência de Belgrado, que deu origem ao movimento dos não-alinhados, teve lugar na Jugoslávia sob iniciativa dos seguintes líderes:","o":["Nehru da Índia, Nasser do Egipto e Tito da Jugoslávia.","Mahatma Gandhi da Índia, Haile Selassie da Etiópia e Tito da Jugoslávia.","Índira Gandhi da Índia, Nkrumah do Gana e Tito da Jugoslávia.","Indira Gandhi da Índia, Nkrumah do Gana e Hugo Chaves da Jugoslávia."],"c":0,"e":"A Conferência de Belgrado (1961) foi promovida por Nehru, Nasser e Tito (com Sukarno e Nkrumah). Gandhi e Indira Gandhi não eram os líderes envolvidos."},{"n":19,"tema":"História Geral","p":"O período arcaico da história grega caracterizou-se pela formação e desenvolvimento de cidades estado, entre as quais se pode mencionar Atenas. Na sua organização social os <i>demiurgos</i> constituíam:","o":["A aristocracia rural dona das melhores terras.","A camada inferior, eram trabalhadores braçais.","A segunda camada social, composta por pequenos proprietários rurais.","A terceira camada social, eram artesãos e viviam do próprio trabalho."],"c":3,"e":"Em Atenas arcaica, os demiurgos eram os artesãos e profissionais que viviam do seu trabalho, formando a terceira camada, abaixo dos eupátridas e dos geórgoi."},{"n":20,"tema":"História Geral","p":"Até meados do século XVIII, a Europa vivia no Antigo Regime cujas 3 principais características foram:","o":["Clero. Nobreza e Terceiro Estado.","Absolutismo monárquico, Sociedade estratificada e Mercantilismo.","Guerras entre Estados, Cruzadas religiosas e Mercantilismo.","Guerras entre Estados, Cruzadas religiosas e Luta de Classes."],"c":1,"e":"O Antigo Regime caracterizou-se pelo absolutismo monárquico, pela sociedade estamental (estratificada) e pelo mercantilismo. A opção A indica apenas os três estados.","d":1},{"n":21,"tema":"História Geral","p":"A Revolução francesa, iniciada em 1789, foi guiada pelos seguintes princípios:","o":["Liberdade, Igualdade e Fraternidade","Liberdade, Separação de poderes e Democracia.","Absolutismo, Mercantilismo e Fisiocratismo","Independência dos povos, Democracia e Igualdade."],"c":0,"e":"O lema da Revolução Francesa foi Liberdade, Igualdade e Fraternidade."},{"n":22,"tema":"História de África","p":"A que teoria da partilha de África se refere a seguinte frase: a partilha de África foi o culminar do longo processo de delapidação do continente iniciado com a chegada dos primeiros europeus em África.","o":["Teoria económica.","Teoria psicológica.","Teoria diplomática.","Teoria da dimensão africana."],"c":3,"e":"A teoria da dimensão africana vê a partilha como o culminar de um processo iniciado com o tráfico e a exploração do continente desde a chegada dos europeus."},{"n":23,"tema":"História de África","p":"As primeiras moedas usadas no comércio árabe da costa oriental africana, foram:","o":["O ouro e a prata.","Os cauris.","Lingotes de bronze.","As missangas de vidro."],"c":0,"e":"No comércio árabe da costa oriental, as primeiras moedas foram de ouro e prata. Cauris e missangas eram meios de troca, não moedas cunhadas. Há dúvida pois a tradição local também usou cobre (Kilwa); melhor leitura: A.","d":1},{"n":24,"tema":"História de África","p":"No âmbito do comércio triangular, os escravos levados do continente africano destinavam-se:","o":["Ao trabalho nas plantações de cana-de-açúcar, algodão, tabaco e seda na Europa e Ásia.","Ao trabalho nas plantações de cana-de-açúcar, algodão, tabaco, seda e lã na Europa.","Ao trabalho nas plantações de cana-de-açúcar, algodão, tabaco e especiarias na Índia.","Ao trabalho nas plantações de cana-de-açúcar, algodão e tabaco na América."],"c":3,"e":"No comércio triangular (Europa, África, América) os escravos iam trabalhar nas plantações e minas das Américas."},{"n":25,"tema":"História de África","p":"Alguns dos principais líderes resistências na África ao sul do sahara: Austral foram:","o":["Ngungunhane, Samuel Maherero, Lobengula, Samori Touré, Tchaka e Nzinga Mbandi","Ngungunhane, Samuel Maherero, Lobengula, Samori Touré , Prenph e Tchaka.","Ngungunhane, Samuel Maherero, Lobengula, Samori Touré , Prenph","Ngungunhane, Samuel Maherero, Lobengula, Samori Touré e Nkwame Nkrumah."],"c":0,"e":"Todos os nomes de A foram líderes de resistência ao sul do Sara (Nzinga Mbandi em Angola). Nkrumah foi nacionalista do século XX, não líder de resistência. B é parecida (Prempeh), pelo que a questão é ambígua; melhor leitura: A.","d":1},{"n":26,"tema":"História de África","p":"No âmbito das estratégias de resistência adoptadas pelas sociedades/estados africanos da África Meridional, o protectorado ou tutela foi a opção dos seguintes estados:","o":["Ndebele, Changanana, Bemba, Yao e Nguni, assim como pelas chefias dos Mangwende, Makoni e Mutasa","Sotho, Swazi, Ngwato, Tswana e Lozi.","Khoi-khoi, Xhosa, Mpondo, Tembu, Mfengu e Hlubi.","Bisa, Lungu, Iwa, Senga, Cewa, Njanja e os Nkonde."],"c":1,"e":"Sotho, Swazi, Ngwato, Tswana e Lozi aceitaram o protectorado britânico para preservar parte da autonomia."},{"n":27,"tema":"História de África","p":"A revolta Maji Maji que se deu no Tanganyica entre 1905 e 1907 foi motivada pelo facto de:","o":["Os alemães capturarem jovens para servirem ao seu exército nas vésperas da Primeira Guerra Mundial.","Os alemães e britânicos colocarem os nativos a trabalharem longas horas sem água nem alimentos.","Os alemães terem morto Kinjeketile Ngwale, o líder espiritual do povo Maji Maji.","Os alemães terem forçado aos nativos a plantarem algodão para exportação."],"c":3,"e":"A Maji Maji (1905-1907) foi desencadeada pela imposição alemã do cultivo forçado de algodão para exportação."},{"n":28,"tema":"História de África","p":"Em 1914, os seguintes estados africanos encontravam-se politicamente independentes do jugo colonial:","o":["Etiópia, Libéria e Darfur.","Eritreia , Libéria e Sera Leoa.","Etiópia, Líbia e Darfur.","Egipto, Libéria e Argélia."],"c":0,"e":"Em 1914 eram independentes a Etiópia, a Libéria e o sultanato de Darfur (anexado só em 1916)."},{"n":29,"tema":"História de África","p":"O império ultramarino Português em África era constituído por:","o":["Cabo Verde, Guiné Bissau, São Tomé e Príncipe, Moçambique e Angola.","Cabo Verde, Guiné Bissau, São Tomé e Príncipe, Moçambique, Angola e Timor Leste.","Cabo Verde, Guiné Bissau, São Tomé e Príncipe, Moçambique , Angola e Guiné Equatorial.","Cabo Verde, São Tomé e Príncipe, Moçambique e Angola."],"c":0,"e":"As cinco colónias portuguesas em África foram Cabo Verde, Guiné, São Tomé e Príncipe, Moçambique e Angola. Timor é na Ásia."},{"n":30,"tema":"História de África","p":"Os territórios outrora denominados, Niassalândia, Bechuanalândia, Sudoeste Africano e Basutolândia correspondem aos actuais países africanos, respectivamente:","o":["Malawi, Botswana, Namíbia e Lesotho.","Malawi, Swazilândia, Namíbia e Lesotho.","Malawi, Botswana, Etiópia e Lesotho.","Malawi, Botswana, Namíbia e Zâmbia."],"c":0,"e":"Niassalândia é o Malawi, Bechuanalândia o Botswana, Sudoeste Africano a Namíbia e Basutolândia o Lesotho."},{"n":31,"tema":"História de África","p":"Com conquista italiana da Etiópia em 1935, desaparecia o último Estado africano independente do jugo colonial, exceptuando:","o":["A Líbia que nunca tinha sido submetido ao domínio de uma potência colonial europeia.","A Libéria que nunca tinha sido submetido ao domínio de uma potência colonial europeia.","A Argélia que nunca tinha sido submetido ao domínio de uma potência colonial europeia.","A Egipto que nunca tinha sido submetido ao domínio de uma potência colonial europeia."],"c":1,"e":"A Libéria, fundada por ex-escravos norte-americanos, nunca foi colonizada. Líbia, Argélia e Egipto foram dominadas por potências europeias."},{"n":32,"tema":"História de África","p":"As colónias francesas da África do Norte até meados do século XX eram:","o":["Marrocos, Tunísia e Egipto e Mauritânia.","Marrocos, Tunísia, Argélia e Mauritânia","Marrocos, Tunísia, Costa de Marfim e Camarões.","Marrocos, Tunísia, Argélia e Djibouti"],"c":1,"e":"Marrocos, Tunísia e Argélia eram francesas, tal como a Mauritânia (Sara ocidental, no Magrebe alargado). O Egipto era britânico. A Mauritânia e Djibouti ficam fora da África do Norte em sentido estrito; melhor leitura: B.","d":1},{"n":33,"tema":"História de África","p":"A maior parte dos países africanos que alcançaram independência em 1960 foi por via de oposição pacífica, foram os casos de:","o":["Gana, Costa do Marfim, Benin, Burkina Faso, Níger, Mali, Somália, Mauritânia e Gabão.","Camarões, Costa do Marfim, Benin, Burkina Faso, Níger, Mali, Somália, Mauritânia e África do Sul.","Camarões, Etipia, Benin, Burkina Faso, Níger, Mali, Somália, Mauritânia e Gabão.","Camarões, Costa do Marfim, Benin, Burkina Faso, Níger, Mali, Somália, Mauritânia e Gabão."],"c":3,"e":"O Gana tornou-se independente em 1957, a Etiópia nunca foi colonizada e a África do Sul era independente desde 1910. Só D contém apenas países independentes em 1960."},{"n":34,"tema":"História de África","p":"A primeira colónia portuguesa em África a alcançar independência foi:","o":["Guiné-Bissau.","Cabo Verde.","São Tomé e Príncipe.","Angola."],"c":0,"e":"A Guiné-Bissau proclamou a independência em 1973 e foi reconhecida por Portugal em 1974, antes de Moçambique, Cabo Verde, São Tomé e Angola (1975)."},{"n":35,"tema":"História de África","p":"Em 1976, cinco Estados da África Austral agruparam-se para formar a Linha da Frente. Tais Estados foram:","o":["Swazilândia, África do Sul, Moçambique, Tanzânia e Zâmbia.","Angola, Botswana, Moçambique, Tanzânia e Zâmbia.","Namíbia, Botswana, Moçambique, Swazilândia e Zâmbia.","Lesotho, África do Sul, Moçambique, Tanzânia e Zimbabwe."],"c":1,"e":"Os cinco Estados da Linha da Frente foram Angola, Botswana, Moçambique, Tanzânia e Zâmbia, opostos ao apartheid e ao regime da Rodésia."},{"n":36,"tema":"História de África","p":"Julius Nyerere, kenneth kaunda e Hastings Banda foram líderes nacionalistas africanos dos seguintes países:","o":["Tanzânia, Zâmbia e Malawi.","Tanzânia, Quénia e Congo Brazzaville.","Tanzânia, Uganda e Namíbia.","Tanzânia, Zimbabwe e Malawi."],"c":0,"e":"Nyerere (Tanzânia), Kaunda (Zâmbia) e Banda (Malawi)."},{"n":37,"tema":"História de Moçambique","p":"Por volta dos séculos III e IV, começaram-se a instalar em Moçambique e em outras regiões da África Austral, comunidades de agricultores e pastores receberam a designação genérica de:","o":["Khoi-Khoi.","San.","Khoisan.","Bantu."],"c":3,"e":"Os agricultores e pastores que se instalaram na região entre os séculos III e IV foram os povos Bantu, que trabalhavam o ferro."},{"n":38,"tema":"História de Moçambique","p":"A existência das primeiras comunidades de agricultores em Moçambique é testemunhada pelas estações arqueológicas de:","o":["Chibuene e Manyikeni.","Chibuene e Chongoene.","Chongoene e Matola.","Chibuene e Grande Zimbabwe."],"c":2,"e":"Matola e Chongoene são sítios da Idade do Ferro Inicial, testemunhos das primeiras comunidades agrícolas. Manyikeni e Zimbabwe são posteriores e Chibuene foi sobretudo um porto comercial. (No original a opção C aparece com a letra F.)"},{"n":39,"tema":"História de Moçambique","p":"O estado do Monomotapa foi fundado, no século XV, por um grupo karanga dirigido por:","o":["Sochangane.","Muzila.","Matope.","Nhatsimba Mutota."],"c":3,"e":"Nyatsimba Mutota, chefe karanga, fundou o Estado do Monomotapa (Mwenemutapa) no século XV. Matope foi o seu filho e sucessor."},{"n":40,"tema":"História de Moçambique","p":"Durante o período mercantil em Moçambique, Manyikeni funcionou como:","o":["Estado satélite do Estado de Mwenemutapa.","Estélite do Grande Zimbabwe.","Entreposto comercial.","Primeiro Estado de Moçambique."],"c":2,"e":"Manyikeni, no sul de Moçambique, funcionou como entreposto do comércio do ouro entre o planalto e a costa. Há alguma dúvida, pois também é descrito como centro político regional; melhor leitura: C.","d":1},{"n":41,"tema":"História de Moçambique","p":"O ciclo de Ouro em Moçambique termina em 1693 quando:","o":["Revoltosos de Mwenemutapa assassinaram o padre Gonçalo da Silveira após baptizar o Mwenemutapa reinante.","Changamire Dombo se revoltou contra o governo central acusando-o de desviar o campesinato por uma actividade de troca.","O ouro perdeu valor no mercado devido a emergência do comércio de marfim que se mostrava mais lucrativo.","O Estado de Mwenemutapa foi abandonado devido a frequentes revoltas dos Estados satélites."],"c":1,"e":"Em 1693-1695 Changamire Dombo revoltou-se contra o Mwenemutapa e expulsou os portugueses do planalto, pondo fim ao ciclo do ouro. O assassinato de Gonçalo da Silveira foi em 1561."},{"n":42,"tema":"História de Moçambique","p":"No contexto do movimento abolicionista, Portugal aboliu o tráfico de escravos no império português sucessivamente em:","o":["1815, 1836 e 1850.","1815, 1836 e 1842.","1836, 1842 e 1884.","1836, 1842 e 1926."],"c":1,"e":"Portugal proibiu o tráfico a norte do Equador em 1815, em todo o império em 1836 e reforçou a proibição pelo tratado com a Grã-Bretanha em 1842. A abolição da escravatura é de 1869.","d":1},{"n":43,"tema":"História de Moçambique","p":"Durante o M'fecane Soshangana depois de fixar-se no território de actual Moçambique fundou o Estado de Gaza. O nome Gaza atribuído a seu estado deveu-se:","o":["A Necessidade de homenagear os guerreiros de Gwaza Muthine em Marracuene.","Ao facto de ter colocado a capital nos territórios de Gaza.","A necessidade de Homenagear o seu pai Gaza fundador do grande império perdido na África do Sul.","A situação geográfica nas margens do Limpopo em Gaza."],"c":2,"e":"Soshangane deu ao seu Estado o nome de Gaza em homenagem ao antepassado Gaza. As outras opções são explicações que não correspondem à tradição."},{"n":44,"tema":"História de Moçambique","p":"O sistema de prazos, na região centro de Moçambique, a partir do século XVI, resultou da:","o":["Presença comercial portuguesa.","Presença colonial portuguesa.","Conquista de terras pelos portugueses.","Conquista de terras pelos árabes."],"c":2,"e":"Os prazos nasceram da ocupação e conquista de terras pelos portugueses no vale do Zambeze. A questão é ambígua (A e B também são defensáveis); melhor leitura: C.","d":1},{"n":45,"tema":"História de Moçambique","p":"Os portugueses tentaram estabelecer em Moçambique o sistema de prazos da coroa. Em princípio as famílias tinham de permanecer:","o":["Uma geração.","Toda a vida.","Três gerações.","O tempo que quisessem."],"c":2,"e":"Os prazos da coroa eram arrendados por três vidas (gerações), sendo transmitidos por via feminina."},{"n":46,"tema":"História de Moçambique","p":"Em 1930, cessaram os privilégios das companhias na colónia de Moçambique, continuando em actividades apenas a:","o":["Companhia do Niassa","Companhia do Zambeze.","Companhia de Moçambique.","Sociedade agrícola do Madal."],"c":2,"e":"A Companhia de Moçambique manteve a concessão (Manica e Sofala) até 1942, enquanto as outras perderam os privilégios. A Madal também continuou como empresa agrícola; melhor leitura: C.","d":1},{"n":47,"tema":"História de Moçambique","p":"Na greve de 28 de Agosto de 1933, “greve da quinhenta” os estivadores do porto de Lourenço Marques exigiam:","o":["A reposição de 0.50 escudos (quinhenta) que haviam sido retirados dos seus salários.","O aumento de 0.50 escudos (quinhenta) no seu salário mensal.","O aumento de 0.50 escudos (quinhenta) por dia.","A reposição de 0.50 escudos (quinhenta) no seu salário diário."],"c":3,"e":"Os estivadores reivindicavam a reposição dos 50 centavos (quinhenta) cortados no salário diário. A opção A omite que o salário era diário."},{"n":48,"tema":"História de Moçambique","p":"O Núcleo de Estudantes Secundários Africanos de Moçambique (NESAM) fundado em 1949 contava com figuras como:","o":["Eduardo Mondlane, Joaquim Chissano, Samora Machel, Eduardo Mulembwe e Pascoal Mucumbi.","Eduardo Mondlane, Joaquim Chissano, Samora Machel, Armando Guebuza e Pascoal Mucumbi.","Eduardo Mondlane, Joaquim Chissano, Armando Guebuza, Josina Muthemba e Pascoal Mucumbi.","Nenhuma das opções."],"c":3,"e":"Samora Machel nunca foi do NESAM e Guebuza e Josina Muthemba eram demasiado jovens em 1949 (e Mondlane estudava na África do Sul). Melhor leitura: D, mas a questão pode ter outra chave.","d":1},{"n":49,"tema":"História de Moçambique","p":"O decurso e a experiência da luta pela independência em Moçambique despertaram a necessidade de contar com as mulheres no processo. Em Março de 1967, fundou-se o Destacamento Feminino. Antes do Destacamento Feminino existia uma organização feminina designada por:","o":["Mulheres na vanguarda.","MULIMO.","OMM.","LIFEMO."],"c":3,"e":"A Liga Feminina Moçambicana (LIFEMO) foi criada em 1966, antes do Destacamento Feminino. A OMM só surgiu em 1973.","d":1},{"n":50,"tema":"História de Moçambique","p":"Poucos anos depois do início da Luta Armada de Libertação Nacional dirigida pela FRELIMO, começaram a surgir territórios livres da dominação colonial que, receberam a designação de “zonas libertadas”. As primeiras zonas libertadas surgiram nas actuais províncias de:","o":["Manica e Sofala.","Maputo e Gaza.","Cabo Delgado e Niassa.","Niassa e Tete."],"c":2,"e":"A luta começou em 1964 no norte e as primeiras zonas libertadas surgiram em Cabo Delgado e no Niassa."},{"n":51,"tema":"História de Moçambique","p":"A 20 de Setembro de 1974 tomou posse o Governo de Transição em Moçambique no qual, Joaquim Chissano e Mário Machungo ocuparam respectivamente os seguintes cargos:","o":["Ministro das Relações Exteriores e Ministro das Finanças.","Primeiro-Ministro e Ministro da defesa.","Primeiro-Ministro e Ministro da Coordenação Económica.","Ministro das Finanças e Primeiro Ministro"],"c":2,"e":"No Governo de Transição, Joaquim Chissano foi Primeiro-Ministro e Mário Machungo Ministro da Coordenação Económica."},{"n":52,"tema":"História de Moçambique","p":"No dia 25 de Junho de 1975, proclamou-se a independência da República Popular de Moçambique; esta designação durou até à aprovação da nova constituição que transformaria em República de Moçambique, isso no ano de:","o":["1980","1985","1990","1994"],"c":2,"e":"A Constituição de 1990 (em vigor em Novembro) instituiu a República de Moçambique e o multipartidarismo."},{"n":53,"tema":"História de Moçambique","p":"Depois da Independência Nacional, o governo de Moçambique desenhou estratégias e planos com vista a alcançar um rápido desenvolvimento do país. O plano que definiu a década de 1980 como década do desenvolvimento foi:","o":["PARPA","PRE","PPI","PRES"],"c":2,"e":"O Plano Prospectivo Indicativo (PPI, 1980-1990) definiu os anos 80 como a década da vitória sobre o subdesenvolvimento."},{"n":54,"tema":"História de Moçambique","p":"No âmbito da democratização do país, as primeiras eleições democráticas foram realizadas em:","o":["1992","1994","1990","1986"],"c":1,"e":"As primeiras eleições multipartidárias (presidenciais e legislativas) realizaram-se em Outubro de 1994, após o Acordo Geral de Paz de 1992."}]},{"id":"his-ujc-2023","subj":"his","titulo":"Exame de História","inst":"UJC / ISRI","ano":2023,"tempo":120,"q":[{"n":1,"tema":"I. Historiografia e filosofia da História","p":"A História é uma ciência social. A sua cientificidade decorre do facto de este domínio do saber:","o":["Reconstruir a evolução das sociedades com fundamento em um acervo documental.","Possuir um objecto de estudo, metodologia e acervo documental para explicar a evolução das sociedades.","Ser uma fonte de informações que permitem ao historiador reconstruir a História de uma determinada região.","A afirmação de que “a História é uma ciência social” não corresponde à verdade."],"c":1,"e":"A cientificidade exige objecto de estudo, metodologia própria e fontes (acervo documental); só a opção B reúne os três elementos."},{"n":2,"tema":"I. Historiografia e filosofia da História","p":"A Historiografia define-se como:","o":["Um conjunto de obras escritas sobre o processo de desenvolvimento que traduzem a ideologia da classe dirigente.","Um conjunto de obras filosóficas concernentes a época caracterizada pela instabilidade política.","Um conjunto de obras escritas sobre mudanças e desenvolvimento de um povo, elaboradas de forma diacrónica e à luz de uma determinada corrente da filosofia da História.","Um conjunto de obras filosóficas sobre o papel do cidadão na História."],"c":2,"e":"Historiografia é o conjunto de obras históricas escritas, organizadas diacronicamente e orientadas por uma corrente da filosofia da História."},{"n":3,"tema":"I. Historiografia e filosofia da História","p":"Segundo António Enes (1894): «O negro, só o negro pode fertilizar a África adusta. Uma raça que no decurso de Séculos sem conto não produziu por esforço seu e espontâneo um só rudimento de civilização». Em qual das correntes da filosofia da história inscreveria este extracto:","o":["Marxista.","Idealista.","Europeocêntrica.","Racista."],"c":2,"e":"O texto nega capacidade civilizacional a África, típico da visão europeocêntrica, que é uma corrente da filosofia da História. Também é racista, mas a pergunta fala em corrente da filosofia da História; a melhor leitura é C.","d":1},{"n":4,"tema":"II. Da Antiguidade ao Liberalismo","p":"A crise e a divisão do Império Romano em Estado [romano] Oriental, com sede em Constantinopla, e Estado [romano] Ocidental, com sede em Roma, tornou-se inevitável na sequência de/da (s):","o":["Guerras constantes, entre os anos 100 a. C e 44 a. C, promovidas por Júlio César.","Cruzadas, no Século IX d. C.","Morte do Imperador Teodósio I, em 395 d. C.","Políticas impopulares do Imperador César Augusto, Ditador, entre 44 a. C. e 23 d.C., da República Romana."],"c":2,"e":"Com a morte de Teodósio I, em 395 d.C., o Império foi dividido definitivamente entre os seus filhos: Oriente (Constantinopla) e Ocidente."},{"n":5,"tema":"II. Da Antiguidade ao Liberalismo","p":"O Império romano Ocidental manteve-se, entre 395 e 476 d.C., estável. A sua desintegração, em 476 d. C., deveu-se a uma combinação de factores, nomeadamente:","o":["As invasões bárbaras e a revolta dos servos.","Invasões bárbaras em tempo em que as autoridades do Império deparavam com dificuldades decorrentes da falta de recursos para o financiamento de guerras para a captura de escravos; do declínio da economia comercial e industrial e da inflação.","A falta de recursos para o financiamento de guerras para a captura de escravos, o declínio da economia comercial e industrial, a inflação.","A revolta generalizada dos servos e a desestabilização da economia."],"c":1,"e":"A queda resultou da combinação de factores externos (invasões bárbaras) e internos (fim das guerras de captura de escravos, declínio económico, inflação); só B reúne ambos."},{"n":6,"tema":"II. Da Antiguidade ao Liberalismo","p":"Da desintegração do Império [romano] Ocidental emergiu o sistema feudal (Séc. V-Séc. IX). As características deste sistema são as seguintes:","o":["A integração política e administrativa como processos de formação de mercados e Estados nacionais;","Desintegração política e administrativa, economia de subsistência, exploração do trabalho de servos pela nobreza e clero e predominância da troca directa","Desintegração política e administrativa, economia mercantil, exploração do trabalho de servos pela nobreza e clero e predominância da troca directa;","Desintegração política e administrativa, economia mercantil, exploração do trabalho de operários pela nobreza e clero e predominância da troca directa."],"c":1,"e":"O feudalismo caracteriza-se por fragmentação do poder, economia de subsistência, servidão e troca directa; a economia mercantil é típica do período seguinte."},{"n":7,"tema":"II. Da Antiguidade ao Liberalismo","p":"O pagamento da renda, pelos servos aos senhores feudais, revelou-se dinâmico, passando do pagamento em trabalho para a renda em espécies e, desta, para a renda em dinheiro.","o":["A passagem da renda em trabalho para a renda em espécies resultou da pacificação do espaço social, da revolução das técnicas agrícolas e da produção de excedentes.","A passagem da renda em trabalho para a renda em espécies resultou de uma determinação feita pelos suseranos.","A passagem da renda em trabalho para a renda em espécies resultou da revolta dos membros do clero contra os servos.","A passagem da renda em trabalho para a renda em espécies decorreu da invasão turca, no Século XV, da região mediterrânica."],"c":0,"e":"Com a pacificação e as inovações agrícolas surgiram excedentes, o que permitiu pagar a renda em espécies em vez de trabalho."},{"n":8,"tema":"II. Da Antiguidade ao Liberalismo","p":"A passagem da renda em espécies para a renda em dinheiro, pelos servos, deveu-se:","o":["Ao ressurgimento das cidades;","À articulação de um conjunto de factores: por um lado, o ressurgimento das cidades e das profissões urbanas, e afirmação da necessidade em alimentos e matérias-primas diversas; a revolução das técnicas e tecnologias de produção permitiu a obtenção de excedentes nas zonas rurais. Nesta base, tornou-se inevitável a articulação entre as cidades e os espaços rurais, no sentido do desenvolvimento do comércio.","À revolução das técnicas e tecnologias de produção permitiu a obtenção de excedentes nas zonas rurais.","À epidemia da peste e aos efeitos socioeconómicos da guerra de cem anos."],"c":1,"e":"A monetarização da renda resultou da interacção entre renascimento urbano, procura de bens e excedentes rurais; as outras opções são parciais."},{"n":9,"tema":"II. Da Antiguidade ao Liberalismo","p":"A época do Renascimento (Séculos XV e XVI) foi marcada por mudanças económicas, políticas e culturais, de que se pode mencionar:","o":["A expansão do Império Romano para o Ocidente, Norte de África e da religião cristã.","A afirmação do pensamento crítico à religião passando-se a considerar o Homem como ser dotado de razão e o centro do universo; a reforma religiosa; a crise do feudalismo e a formação de Estados centralizados; a realização de grandes viagens marítimas na perspectiva do desenvolvimento do comércio;","A insubordinação religiosa por parte de chefes de Estado protestantes em prol da defesa do princípio da razão do Estado;","A conferência de Berlim, com o objectivo de promover a colonização de África."],"c":1,"e":"Humanismo, Reforma, crise do feudalismo, Estados centralizados e Descobrimentos marcam o Renascimento; Berlim é de 1884-85 e o Império Romano é anterior."},{"n":10,"tema":"II. Da Antiguidade ao Liberalismo","p":"O mercantilismo é uma ideologia que tem relação com a formação de Estados nacionais, na Europa. Esta ideologia:","o":["Defendia, por um lado, a preservação dos particularismos político-administrativos feudais e, por outro, os privilégios dos membros do clero.","Defendia a aliança entre o poder político e o grande negócio e, por isso, era contra os particularismos político-administrativos feudais, para, em vez deles, promover-se a integração do mercado nacional; politicamente centralizado, Estado devia proteger a economia nacional; o Estado devia preservar a balança de pagamentos favorável, devendo, por isso, promover o comércio internacional e acumular metais preciosos.","Defendia que o Estado devia proteger a economia nacional.","Defendia os interesses do clero e da nobreza."],"c":1,"e":"O mercantilismo associa Estado e burguesia comercial, combate o particularismo feudal, defende balança comercial favorável e acumulação de metais preciosos."},{"n":11,"tema":"II. Da Antiguidade ao Liberalismo","p":"Assinale com X o período que define o conceito moderno de Estado:","o":["O Estado é uma forma de organização política.","O Estado é uma forma de organização política que incide sobre um território e um agregado populacional; está dotado de uma autoridade, legitimada ao nível interno e reconhecida como entidade soberana, ao nível internacional.","O Estado é uma forma de organização política que incide sobre um território e um agregado populacional; está dotado de uma autoridade, legitimada ao nível interno e reconhecida como entidade soberana ao nível internacional; esta autoridade política, que reivindica o monopólio sobre os meios de violência legítima, tem para com os governados o dever de lhes assegurar a segurança, possibilitar-lhes a produção e o usufruto de bens e serviços públicos, tais como a educação, saúde, emprego, habitação e outros; ao nível internacional, representa o povo junto de outros Estados e organizações internacionais.","O Estado é uma forma de organização que, ao nível internacional, representa o povo junto de outros Estados e organizações internacionais."],"c":2,"e":"A definição moderna (Weber) inclui território, população, soberania, monopólio da violência legítima e deveres para com os governados; C é a mais completa.","d":1},{"n":12,"tema":"II. Da Antiguidade ao Liberalismo","p":"Pela revolução política de 1789-1791, a burguesia francesa transformou a Monarquia absolutista em Monarquia constitucional, conquistando, assim, o poder político. Esta mudança foi uma consequência:","o":["Da abolição da Assembleia Nacional Constituinte em 1792 e subsequente estabelecimento da Convenção como novo órgão legislador;","Da autoproclamação, em 1789, do 3º Estado em Assembleia Nacional Constituinte como órgão legislador e da institucionalização da democracia censitária;","Da autoproclamação, em 1789, do 3º Estado em Assembleia Nacional Constituinte como órgão legislador e institucionalização da democracia baseada no princípio de sufrágio universal;","Da prisão, julgamento e condenação, em Janeiro de 1793, do Rei Louis XVI à morte e da tomada da Bastilha pelos Jacobinos."],"c":1,"e":"Em 1789 o Terceiro Estado proclamou-se Assembleia Nacional Constituinte e a Constituição de 1791 instituiu o voto censitário (não universal); a execução do rei é de 1793."},{"n":13,"tema":"II. Da Antiguidade ao Liberalismo","p":"«(....)os direitos naturais e imprescindíveis do homem são: a liberdade, a propriedade, a segurança e resistência à opressão». Esta citação foi extraída da Declaração dos Direitos do Homem e do Cidadão, proclamados pela primeira vez pela:","o":["Revolução inglesa de 1688.","Revolução americana de 1776.","Revolução burguesa francesa de 1789.","Revolução russa de 1917."],"c":2,"e":"A Declaração dos Direitos do Homem e do Cidadão (26 de Agosto de 1789) é da Revolução Francesa e o artigo 2.º enumera esses quatro direitos."},{"n":14,"tema":"II. Da Antiguidade ao Liberalismo","p":"O liberalismo é uma ideologia que influenciou, nos Séculos XVIII e XIX, os processos políticos e económicos na América do Norte e na Europa Ocidental. Uma ideologia política:","o":["É um conjunto de princípios e valores religiosos.","Tendo como referência o contexto de vida e a experiência dos indivíduos, a ideologia propõe uma alternativa de sistema de relações sociais com base em mudanças económicas e políticas. Serve, por isso, de mecanismo de mobilização, pelos políticos, das massas para a acção política.","Tendo como referência o contexto de vida e a experiência dos indivíduos, a ideologia propõe-lhes um novo modo de vida.","É um acto de manipulação das massas."],"c":1,"e":"Uma ideologia política propõe um sistema alternativo de relações sociais e mobiliza as massas para a acção; não é religiosa nem mera manipulação."},{"n":15,"tema":"II. Da Antiguidade ao Liberalismo","p":"O liberalismo, como ideologia, defende:","o":["Os direitos do homem e do cidadão, a legitimação periódica das Instituições do Estado por via democrática, a organização da economia na base da propriedade privada e a regulação desta pelos mecanismos do mercado.","A nacionalização das empresas e dos serviços públicos.","A readopção do Bonapartismo para a regulação das relações entre os governantes e os governados.","A readopção do Jacobinismo para a regulação das relações entre os governantes e governados."],"c":0,"e":"O liberalismo defende direitos individuais, legitimação eleitoral periódica, propriedade privada e mercado; a nacionalização é socialista."},{"n":16,"tema":"III. Zimbabwe e capital mercantil","p":"O primeiro Estado do Zimbabwe estruturou-se no planalto central desta região, entre:","o":["1250 d. C. e 1450 d. C.","1100 d. C. e 1200 d. C.","900 d. C. e 1050 d. C.","700 d. C. e 850 d. C."],"c":0,"e":"O Estado do Grande Zimbabwe (chona-karanga) afirmou-se entre c. 1250 e 1450, antes de dar lugar ao Estado Mutapa."},{"n":17,"tema":"III. Zimbabwe e capital mercantil","p":"O Estado do Zimbabwe estruturou-se em consequência:","o":["Da formação da elite política chona-karanga e dos aparelhos do poder.","Influência da civilização dos fenícios, na África austral.","A formação da elite política chona-karanga e dos aparelhos do poder, na base do desenvolvimento da agro-pecuária, metalurgia e do comércio à longa distância com os árabes, cuja reprodução tornou inelutável o controle das zonas auríferas e das rotas comerciais.","A influência dos comerciantes portugueses, na África austral."],"c":2,"e":"O Zimbabwe assentou na elite chona-karanga, na agro-pecuária, metalurgia e comércio com os árabes (ouro); os portugueses chegaram depois e os fenícios não tiveram influência."},{"n":18,"tema":"III. Zimbabwe e capital mercantil","p":"O pré-industrial capitalismo europeu, entre os Séculos XV e XIX, actuou em África como agente de acumulação do capital mercantil. Indique as características da actuação do capital mercantil em África e, em particular, em Moçambique:","o":["Intervenção dos agentes do capital mercantil nos Estados Africanos, ocupação efectiva e organização da economia em benefício da Metrópole colonial.","Controle de empórios comerciais na Costa, responsabilizando-se às elites africanas a governação das respectivas unidades políticas e a produção de bens destinados para a troca desigual.","Envio e preservação, de forma permanente, de um exército.","Organização da produção de bens destinados para a troca desigual."],"c":1,"e":"Antes da ocupação efectiva (séc. XIX-XX), o capital mercantil limitou-se a feitorias costeiras, deixando às elites africanas o poder e a produção para a troca desigual."},{"n":19,"tema":"III. Zimbabwe e capital mercantil","p":"No contexto da actuação do capital mercantil, entre os Séculos XV e XVI, a Ilha de Sofala, Ilha de Moçambique e Quelimane, em Moçambique, foram palcos da luta pela supremacia comercial entre:","o":["Capital mercantil chinês e capital mercantil árabe.","Capital mercantil árabe e capital mercantil português.","Capital mercantil fenício e capital mercantil indiano.","Capital mercantil indiano e capital mercantil chinês."],"c":1,"e":"Desde a chegada de Vasco da Gama (1498), os portugueses disputaram aos árabes/swahilis o comércio da costa oriental africana."},{"n":20,"tema":"IV. Imperialismo e colonização de África","p":"No último quartel do Século XIX, em obediência às determinações da Conferência de Berlim, as potências Ocidentais ocuparam e transformaram a maior parte de África em domínios coloniais. Indica dois países que escaparam da colonização:","o":["Libéria, Lesoto.","Lesoto, Sudão do Sul.","Sudão do Sul, Burundi.","Libéria, Etiópia."],"c":3,"e":"A Libéria (fundada por ex-escravos americanos) e a Etiópia (vitória em Adwa, 1896) mantiveram a independência; a Etiópia só foi ocupada pela Itália em 1936-41."},{"n":21,"tema":"IV. Imperialismo e colonização de África","p":"A ocupação efectiva de África pelos Estados imperialistas, no Século XIX, estava associada a necessidades domésticas, resultantes de/da:","o":["Associação do capital bancário com os proprietários de manufacturas.","Desarticulação dos sectores económico agrícola, industrial, bancário e de serviços.","Mecanização da agricultura.","Dominância da economia industrial, génese do capital financeiro, exportação de capitais e conflitos entre o capital e o trabalho."],"c":3,"e":"O imperialismo decorreu do capitalismo monopolista: indústria dominante, capital financeiro, exportação de capitais, tensões sociais internas e busca de mercados e matérias-primas."},{"n":22,"tema":"IV. Imperialismo e colonização de África","p":"Identifique, na corrida pela ocupação de Colónias no Século XX, Estados que tinham interesses em colónias sem que fossem Estados potências imperialistas.","o":["Portugal e Japão.","Inglaterra e Alemanha.","Portugal e Espanha.","Estados Unidos e Japão."],"c":2,"e":"Portugal e Espanha tinham colónias mas já não eram potências industriais imperialistas; Inglaterra, Alemanha, EUA e Japão eram.","d":1},{"n":23,"tema":"IV. Imperialismo e colonização de África","p":"Aponte potências imperialistas em conflito, entre 1875-1919, por causa da divisão de Territórios coloniais em diferentes regiões de África","o":["Portugal e Alemanha, na África Austral; Inglaterra e França, na África do Norte; Bélgica e Inglaterra, na África Ocidental.","Portugal e Espanha, na África Austral; Inglaterra e França, na África do Norte; Bélgica e Inglaterra, na África Ocidental.","Inglaterra e França, na África do Norte e Ocidental; Inglaterra e Alemanha na África Austral; França e Alemanha, na África Ocidental e Central.","Portugal e Alemanha, na África Oriental; Inglaterra e França, na África Central; Bélgica e Inglaterra, na África Ocidental."],"c":2,"e":"As rivalidades principais foram anglo-francesa (Fachoda, Norte e Oeste), anglo-alemã (Sudoeste e Leste/Sul) e franco-alemã (Marrocos, Congo/Camarões)."},{"n":24,"tema":"IV. Imperialismo e colonização de África","p":"O movimento pela abolição da escravatura, em África, na segunda metade do Século XIX, era o corolário de necessidades em mão-de-obra, pois, em substituição da economia de tráfico em África, o capital industrial passou a investir em:","o":["Promoção da economia mercantil.","Economia de plantação, indústria mineira, construção de portos, ferrovias e estradas.","Trocas desiguais.","Guerras para a captura de escravos."],"c":1,"e":"O capital industrial queria trabalhadores locais para plantações, minas e infra-estruturas, substituindo o tráfico."},{"n":25,"tema":"IV. Imperialismo e colonização de África","p":"A Alemanha promoveu, entre 19 de Novembro de 1884 e 26 de Fevereiro de 1885, a Conferência de Berlim, na perspectiva de legitimar a regra de “ocupação colonial efectiva”. A exigência da Alemanha constituía uma reacção:","o":["Às deliberações, em 1776, da Conferência colonial de Bruxelas.","À sua posição desvantajosa na partilha do mercado mundial por causa da sua integração política e industrialização tardias; Obtenção de maiores benefícios deste facto pela Inglaterra e França, primeiras potências industriais.","À luta de Portugal, como Estado interessado e protegido na questão colonial, pela preservação das suas colónias.","Ao envolvimento tardio da Bélgica na colonização do continente Africano."],"c":1,"e":"A Alemanha, unificada (1871) e industrializada tardiamente, queria quebrar a vantagem anglo-francesa; 1776 é incoerente com a Conferência de Bruxelas (1876)."},{"n":26,"tema":"IV. Imperialismo e colonização de África","p":"Assinale a resposta verdadeira:","o":["Nigéria, Congo-Kinshasa e camarões foram Colónias britânicas.","Namíbia, Tanganica e Camarões foram Colónias da Alemanha antes da Primeira Guerra Mundial.","Moçambique, Gana e Mali foram Colónias britânicas.","Nigéria, Namíbia e Mali foram Colónias da Alemanha antes da Primeira Guerra Mundial."],"c":1,"e":"Sudoeste Africano (Namíbia), Tanganica e Camarões foram colónias alemãs até 1914-18; Congo era belga e Mali francês."},{"n":27,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"Com o exacerbar dos nacionalismos, formaram-se dois blocos políticos militares, que se envolveram, entre 1914 e 1918 num conflito global. Indique os países destes blocos e os respectivos líderes:","o":["Tríplice Entente: França (Ferdinand Foch e Georges Clemenceau), Império Austro-Húngaro (Fernando I), Império Russo (Nicolau II); Tríplice Aliança: Império Alemão (Guilherme II e Paul von Hindenburg), Estados Unidos da América (Woodrow Wilson; John Pershing), Império Otomano (Ismail Enver).","Tríplice Entente : Reino Unido ( Jorge V; Douglas Haig), Japão (Imperador Taisho; 1º Ministro Terauchi Masatake; 1º Ministro Hara Takashi), Estados Unidos da América Woodrow Wilson; John Pershing); Tríplice Aliança: Tríplice Aliança : Império Alemão (Guilherme II e Paul von Hindenburg), Império Austro-Húngaro (Fernando I), Japão (Imperador Taisho; 1º Ministro Terauchi Masatake; 1º Ministro Hara Takashi).","Tríplice Entente: Império Britânico e CommonWealth (Austrália, Nova Zelândia, Canadá, Terra Nova e África do Sul) (Jorge V; Douglas Haig e al.), França (Ferdinand Foch e Georges Clemenceau), Rússia (até 1916) (Nicolau II); Tríplice Aliança : Império Alemão (Guilherme II e Paul von Hindenburg) , Império Austro-Húngaro (Fernando I), Japão (Imperador Taisho; 1º Ministro Terauchi Masatake; 1º Ministro Hara Takashi).","Tríplice Entente : Império Alemão (Guilherme II e Paul von Hindenburg) , Império Austro-Húngaro (Fernando I), Japão (Imperador Taisho; 1º Ministro Terauchi Masatake; 1º Ministro Hara Takashi); Tríplice Aliança: Franla (Ferdinand Foch e Georges Clemenceau), Império Austro-Húngaro (Fernando I), Império Russo (Nicolau II)."],"c":2,"e":"C é a única com a Entente correcta (Reino Unido e domínios, França, Rússia) e a Aliança com Alemanha e Áustria-Hungria. Todas as opções têm erros (aqui o Japão, que lutou com a Entente); melhor leitura: C.","d":1},{"n":28,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"O términus da 1ª Grande Guerra (1914-1918) teve como base um acordo internacional definindo os termos da paz e da regulação das relações entre vitoriosos e perdedores da guerra. Este acordo ficou conhecido como:","o":["Tratado de Versalhes.","Tratado de Adis-Abeba.","Tratado de Londres.","Tratado de Lisboa."],"c":0,"e":"O Tratado de Versalhes foi assinado em 28 de Junho de 1919."},{"n":29,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"A 1ª Grande Guerra (1914-1918) teve como consequências:","o":["Perdas humanas estimadas em 10 milhões de mortos, trinta milhões de feridos e enormes prejuízos económicos; a formação da sociedade de Nações.","Perdas humanas estimadas em 10 milhões de mortos, trinta milhões de feridos e enormes prejuízos económicos; a formação da sociedade de Nações; desintegração dos impérios alemão e Otomano e britânico.","Perdas humanas estimadas em 10 milhões de mortos, trinta milhões de feridos e enormes prejuízos económicos; a formação da sociedade de Nações; desintegração dos impérios alemão e Otomano e britânico e português","Perdas humanas estimadas em 10 milhões de mortos, trinta milhões de feridos e enormes prejuízos económicos; a formação da sociedade de Nações; desintegração dos impérios alemão e otomano, russo e austro-húngaro; a génese de novos Estados na Europa do Leste."],"c":3,"e":"A guerra levou ao fim dos impérios alemão, otomano, russo e austro-húngaro e ao surgimento de novos Estados na Europa de Leste; os impérios britânico e português não se desintegraram."},{"n":30,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"Entre 1933 e 1945, em resposta à crise de superprodução de 1929, o Presidente Franklin D. Roosevelt observou uma política doméstica caracterizada por “Controle governamental dos preços, concessão de empréstimos aos agricultores, realização de grandes obras, criação do seguro de desemprego, apoio à indústria”. Como se chama esta política?","o":["Política socialista.","Política Neoliberal.","Política Proteccionista.","Política de New Deal."],"c":3,"e":"Estas medidas de intervenção estatal formaram o New Deal de Roosevelt."},{"n":31,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"A segunda Guerra Mundial, entre 1939 e 1945, com o qual se associa a reestruturação do sistema político mundial, desenrolou-se, em simultâneo, na Europa e Oceano Atlântico, África e Médio Oriente, Sudeste Asiático e Oceano Pacífico. Por conseguinte, é classificada como:","o":["Conflito opondo o comunismo e o socialismo.","Conflito pela libertação das colónias dos países imperialistas.","Conflito opondo países ricos e países pobres.","Conflito global."],"c":3,"e":"Por abranger vários continentes e oceanos em simultâneo, é um conflito global (mundial)."},{"n":32,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"Uma interacção de factores explica a deflagração, em 1939, deste conflito, nomeadamente:","o":["O ataque, pelas forças nipónicas, da base naval americana de Pearl Harbor, no Oceano Pacífico e a necessidades de defesa dos interesses nacionais dos EUA.","A crise de 1929-1933 e o holocausto da comunidade judaica, na Europa.","A ascensão de Benito Mussolini ao poder na Itália e de Adolfo Hitler, na Alemanha e a anexação da Áustria, à Alemanha","A ascensão ao poder de Partidos totalitários na Itália e na Alemanha, o impacto económico e social da crise de 1929-33, o nacionalismo e a denúncia, por Adolf Hitler, das cláusulas impostas à Alemanha pelo Tratado de Versalhes, a política de anexação de outros Estados, seguida pela Alemanha a partir de 1935 e a tendência armamentista, observada pelas potências mundiais."],"c":3,"e":"A guerra resultou de vários factores combinados (totalitarismos, crise de 1929, revanchismo contra Versalhes, anexações, corrida ao armamento); Pearl Harbor é de 1941 e o Holocausto é posterior."},{"n":33,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"Durante a segunda Guerra Mundial, os líderes dos países do eixo estavam em conflitos com os líderes dos países aliados. Encontravam-se assim alinhados:","o":["Adolf Hitler (Alemanha), MaoTse-Tung (China), Marechal Philippe Pétain (França de Vichy), Imperador Hirohito (Japão) contra Winston Churchil (Inglaterra), Joseph Stalin (URSS), Franklin Roosevelt (EUA), General Charles De Gaulle (Franca Livre), Bronilaw Komorowski (Polónia).","Adolf Hitler (Alemanha), Benito Mussoline (Itália), Marechal Ph. Petain (França de Vichy), Imperador Hirohito (Japão) contra Winston Churchil (Inglaterra), Joseph Stalin (URSS), Franklin Roosevelt (EUA), General Charles De Gaulle (Franca Livre), Bronilaw Komorowski (Polónia), Hendrik Frensch Verwoerd (África do Sul).","Adolf Hitler (Alemanha), Benito Mussoline (Itália), Marechal Ph. Petain (França de Vichy), Imperador Hirohito (Japão) contra Winston Churchil (Inglaterra), Joseph Stalin (URSS), Franklin Roosevelt (EUA), General Charles De Gaulle (Franca Livre), Bronilaw Komorowski (Polónia).","Adolf Hitler (Alemanha), Benito Mussoline (Itália), Marechal Ph. Petain (França de Vichy), Hailé Sélassié (Etiópia) contra Winston Churchil (Inglaterra), Joseph Stalin (URSS), Franklin Roosevelt (EUA), General Charles De Gaulle (Franca Livre), Bronilaw Komorowski (Polónia)."],"c":2,"e":"Eixo: Hitler, Mussolini, Hirohito (e Pétain, colaboracionista); Aliados: Churchill, Estaline, Roosevelt, De Gaulle, governo polaco no exílio. A inclui Mao (errado), B inclui Verwoerd (não era líder aliado) e D põe Hailé Selassié no Eixo."},{"n":34,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"As forças de Adoph Hitler criaram, durante a 2ª Guerra Mundial (1939-1945), dois centros para extermínio de Judeus e de soldados inimigos. Estes centros localizam-se em:","o":["Nas cidades de Viena e Vichy.","Nas cidades de Praga e Moscovo.","Nas vilas de Auschwitz e Treblinka.","Nas cidades de Berlim e Frankfurt."],"c":2,"e":"Auschwitz e Treblinka, na Polónia ocupada, foram campos de extermínio nazis."},{"n":35,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"No contexto da Guerra de 1939-45, as regiões da África do Norte e de “Corno de África” foram um palco de confrontos militares entre:","o":["1939-1945.","1939-1943.","1939-1940.","1939-1942."],"c":1,"e":"Os combates no Norte de África e Corno de África decorreram de 1940 a 1943 (rendição do Eixo na Tunísia, Maio de 1943); a opção que mais se aproxima é B. A pergunta é imprecisa.","d":1},{"n":36,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"As forças em conflito no palco Africano, durante a Segunda Grande Guerra, eram:","o":["Força conjunta britânico-americana (EUA), contra a força conjunta italo-alemã, pelo controle do mar mediterrâneo, canal de Suez e Corno de África.","Força conjunta nipo-japonesa contra a força conjunta germano-gaulesa, pelo controle do canal de Moçambique.","Força conjunta anglo-afrikander contra a força conjunta italo-germânica pelo controle dos portos e regiões mineiras sul-africanas.","Força conjunta russo-polaca contra a força conjunta britânico-gaulesa pela libertação da Nigéria."],"c":0,"e":"No teatro africano, britânicos (com americanos a partir de 1942) combateram italianos e alemães pelo Mediterrâneo, Suez e Corno de África."},{"n":37,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"O país do Imperador Haillé Sélassié II esteve, entre 1936-41, ocupado pelas forças de um dos Estados do Eixo. Haillé Sélassié I foi o Imperador do(a):","o":["Sudão;","Etiópia;","Nigéria;","Mali."],"c":1,"e":"Hailé Selassié foi imperador da Etiópia, ocupada pela Itália fascista entre 1936 e 1941."},{"n":38,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"A libertação do País do Imperador Haillé Sélassié II ocorreu em 1941, na sequência da intervenção das forças:","o":["Italo-germânicas.","Franco-americanas.","Etíope-britânicas.","Russo-polacas."],"c":2,"e":"Em 1941 forças britânicas e etíopes (com a Resistência) libertaram a Etiópia dos italianos."},{"n":39,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"Duas cidades Japonesas foram alvo em 1945 de lançamento de bombas atómicas dos EUA que mostraram aos seus adversários e ao mundo a sua superioridade militar. Indique nomes destas cidades:","o":["Hiroshima e Nagasaki.","Camberra e Pequim.","Pequim e Addis Abeba.","Nova Deli e Tóquio."],"c":0,"e":"Hiroshima (6 de Agosto) e Nagasaki (9 de Agosto de 1945)."},{"n":40,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"A segunda Grande Guerra teve consequências fundamentais no sistema político internacional, de que merecem referência as seguintes:","o":["A aliança estratégica entre a URSS e a China.","O isolamento dos EUA e da Europa.","Criação da Organização das Nações Unidas; reconhecimento do direito dos povos à autodeterminação, um dos factores da descolonização na Ásia e África; a emergência da URSS como superpotência rival, iniciando-se, assim, a guerra fria; recuperação económica da Europa e do Japão sob investimentos americanos; reorganização dos Estados em blocos político-regionais.","A desintegração do regime do Apartheid, por se tratar de crime contra a humanidade."],"c":2,"e":"ONU, autodeterminação, Guerra Fria e Plano Marshall são consequências directas; o Apartheid só terminou nos anos 1990."},{"n":41,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"A ONU é uma organização internacional com os seguintes objectivos:","o":["Garantir a recuperação económica dos países afectados pela guerra.","Promover a paz, segurança, amizade, cooperação entre países e o desenvolvimento.","Defender os direitos humanos e do cidadão.","Apoiar os movimentos nacionalistas."],"c":1,"e":"A Carta da ONU (1945) visa, antes de tudo, a paz e a segurança internacionais, a amizade e a cooperação entre os Estados."},{"n":42,"tema":"V. Primeira e Segunda Guerras Mundiais","p":"De 1945 a 2007, a ONU teve oito Secretários-Gerais. Destes, dois são de Estados africanos. Indique-os:","o":["Javier Pérez de Cuéllar e Boutros Boutros-Ghali.","Khofi Annan e Kurt Waldheim.","Boutros Boutros-Ghali e Khofi Annan.","Khofi Annan e Javier Pérez de Cuéllar."],"c":2,"e":"Boutros Boutros-Ghali (Egipto, 1992-96) e Kofi Annan (Gana, 1997-2006); Pérez de Cuéllar era peruano e Waldheim austríaco."},{"n":43,"tema":"VI. Pan-africanismo e descolonização","p":"A identidade pan-africanista revelou-se ser uma ideologia que aglutinou e mobilizou:","o":["Árabes contra os Judeus.","Descendentes de escravos nos EUA, região das Caraíbas, elites negras de África e residentes na Europa para a luta contra o racismo e injustiças da civilização Ocidental.","Capitalistas contra socialistas.","Cristãos contra os praticantes de religiões sincréticas em África."],"c":1,"e":"O pan-africanismo uniu negros da diáspora (EUA, Caraíbas, Europa) e africanos contra o racismo e a dominação ocidental."},{"n":44,"tema":"VI. Pan-africanismo e descolonização","p":"Identifique os valores e referências da acção política da identidade pan-africanista:","o":["Promoção do racismo negro como contraponto ao racismo de brancos.","Formação de comunidades de Estados em função da identidade histórica e linguística, herdada dos sistemas coloniais.","Resgate de elementos identitários das comunidades negras, nomeadamente, a memória histórica e conhecimento sobre línguas, artes, sistemas políticos pré-coloniais e a integração e união dos Estados Africanos, após a libertação do colonialismo.","Resgate de elementos identitários das comunidades negras, nomeadamente, a memória histórica e conhecimento sobre línguas."],"c":2,"e":"O pan-africanismo valoriza a memória e as culturas negras e defende a unidade dos Estados africanos após a descolonização; D é parcial."},{"n":45,"tema":"VI. Pan-africanismo e descolonização","p":"Qual o país, ou Estado, a que pertence cada um dos líderes da luta contra a dominação estrangeira a seguir indicados:","o":["Sekou Touré (Guiné-Conakri).","Amílcar Cabral (Guiné Equatorial).","Dingane (Angola).","Hasting K. Banda (Uganda)."],"c":0,"e":"Sekou Touré foi o líder da Guiné-Conakri; Cabral era da Guiné-Bissau/Cabo Verde, Dingane era zulu e Banda do Malawi."},{"n":46,"tema":"VI. Pan-africanismo e descolonização","p":"Gana, Senegal, Mali e Uganda adquiriram, respectivamente em 1957, 1960 e 1962, o estatuto de Estados independentes, em consequência de:","o":["Adopção de Constituições Federalistas pelas potências coloniais.","Lutas armadas contra o colonialismo.","Lutas pacíficas e acordos políticos com respectivas potências coloniais","Adopção de Constituições em prol da autonomização."],"c":2,"e":"Estes países (britânicos e franceses) alcançaram a independência por via pacífica e negociada, sem guerra de libertação."},{"n":47,"tema":"VI. Pan-africanismo e descolonização","p":"Indique quatro países africanos, cujas independências políticas foram reconhecidas pelas ex-potências coloniais, em consequência de processos de lutas armadas e subsequentes acordos políticos, para a transferência dos poderes para as lideranças africanas:","o":["Angola, Namíbia, Madagáscar, Tanzânia.","Angola, Guiné Equatorial, Moçambique, Namíbia","Angola, Botswana, Guiné-Conakry e Swazilândia","Argélia, Moçambique, Guiné-Bissau e Angola."],"c":3,"e":"Argélia, Moçambique, Guiné-Bissau e Angola conquistaram a independência por luta armada seguida de acordos (Évian, Lusaka, Argel, Alvor)."},{"n":48,"tema":"VI. Pan-africanismo e descolonização","p":"Conquistada a independência, há Estados em África que conheceram guerras civis, como o ilustram o caso de:","o":["Nigéria, Uganda, República dos Camarões e Ruanda.","Moçambique, Etiópia, Senegal e Tunísia.","Gana, Libéria, Namíbia e Guiné Equatorial.","Uganda, São-Tomé e Príncipe, Cabo-Verde e Malawi."],"c":0,"e":"Nigéria (Biafra), Uganda, Camarões e Ruanda viveram guerras civis; as outras listas incluem países que não as tiveram (Senegal, Tunísia, Gana, Cabo Verde...).","d":1},{"n":49,"tema":"VI. Pan-africanismo e descolonização","p":"“Estados da Linha da Frente” foi a Organização, de natureza político-diplomática, fundada em 1976, e que assumiu como missão a prestação de apoios multifacetados aos Movimentos de libertação:","o":["Na África Ocidental.","Na África Austral.","Na África do Norte.","Na região do Sahel."],"c":1,"e":"Os Estados da Linha da Frente (Tanzânia, Zâmbia, Angola, Moçambique, Botswana) apoiaram os movimentos de libertação da África Austral."},{"n":50,"tema":"VI. Pan-africanismo e descolonização","p":"O Comité Norueguês do Nobel (CNN) atribuiu, de 1901 ao presente, o prémio nobel da paz a 111 personalidades e 27 Organizações. Mencione personalidades que mereceram este galardão do CNN pela sua contribuição para a paz na África Austral:","o":["Jacob Zuma, Roleof Botha e Thabo Mbeki.","Desmond Tutu, Fredric De Klerk e Nelson Mandela.","Pieter Botha, Joaquim Chissano e Samora Machel.","Fredric De Klerk e Nelson Mandela e Dr Kamuzu Banda."],"c":1,"e":"Tutu (1984), Mandela e De Klerk (1993) receberam o Nobel da Paz pelo fim do apartheid e transição pacífica na África do Sul."},{"n":51,"tema":"VI. Pan-africanismo e descolonização","p":"A União Africana celebra o dia de África, todos os anos, em:","o":["25 de Junho.","25 de Maio","25 de Setembro.","25 de Dezembro."],"c":1,"e":"O Dia de África assinala a fundação da OUA em 25 de Maio de 1963."},{"n":52,"tema":"VII. Moçambique e África contemporânea","p":"Indica o título do livro escrito por Eduardo Mondlane, cuja primeira edição ocorreu em 1969, pelo qual justifica o Nacionalismo Moçambicano:","o":["Lutar por Moçambique.","O Processo Revolucionário de Moçambique.","A Unidade Nacional","Moçambique, Etnicidades, Nacionalismo e o Estado, Transição Inacabada."],"c":0,"e":"“Lutar por Moçambique” (The Struggle for Mozambique, 1969) é a obra de Eduardo Mondlane."},{"n":53,"tema":"VII. Moçambique e África contemporânea","p":"Agrupamentos [políticos] patrióticos, com base social em diferentes regiões de Moçambique, nomeadamente a UNAMI, MANU, UDENAMO e UNEMO, formaram, em congresso realizado em 1962 em Dar-Es-Salaam, um movimento [político] nacional, para o desencadeamento da luta anti-colonial. Este movimento passou a chamar-se:","o":["Partido do Congresso do Povo de Moçambique","Partido Democrático de Moçambique","Partido para a Libertação de Moçambique","Frente de Libertação de Moçambique"],"c":3,"e":"Em 25 de Junho de 1962 fundiram-se na Frente de Libertação de Moçambique (FRELIMO)."},{"n":54,"tema":"VII. Moçambique e África contemporânea","p":"O movimento [político] nacional que desencadeou, por um período de 10 anos, a luta anti-colonial em Moçambique, declarou-se, a partir de 1962, do ponto de vista ideológico, ser defensor do:","o":["Marxismo-Leninismo","Nacionalismo.","Liberalismo.","Fascismo."],"c":1,"e":"A FRELIMO começou por se definir como movimento nacionalista de libertação; o marxismo-leninismo só foi adoptado após 1977."},{"n":55,"tema":"VII. Moçambique e África contemporânea","p":"O movimento que recorreu à luta armada para a conquista da independência de Moçambique realizou, em 1968, o seu segundo congresso. Este congresso ocorreu em/na:","o":["Tanzânia, na cidade de Zanzibar.","Malawi, na Cidade de Lilongwe.","Moçambique, em Madjedje.","Zâmbia, na cidade de Lusaka."],"c":2,"e":"O II Congresso da FRELIMO (Julho de 1968) realizou-se em Matchedje, Niassa, em território libertado."},{"n":56,"tema":"VII. Moçambique e África contemporânea","p":"Com o avanço da luta anticolonial em Moçambique, o governo português desencadeou a sua maior operação militar, designada:","o":["Operação Queima palhota.","Operação Nó-Górdio.","Operação Anti-turras.","Operação Anti-Guerrilha."],"c":1,"e":"A Operação Nó Górdio (1970), comandada por Kaúlza de Arriaga, foi a maior ofensiva portuguesa em Moçambique."},{"n":57,"tema":"VII. Moçambique e África contemporânea","p":"Na sequência da adopção, por Moçambique, da Constituição de 1990, o regime político passou a observar os seguintes princípios:","o":["Não reconhecimento de direitos políticos aos cidadãos; existência de partido único como entidade do dirigente do Estado e da sociedade; controle, planificação da economia, produção de bens e serviços para os cidadãos;","Não reconhecimento de direitos políticos aos cidadãos e exercício da acção dirigente do Estado e da sociedade; legitimação do poder e das instituições através de eleições democráticas e transparentes, sob voto livre e secreto; controle, planificação da economia e alocação de bens e serviços aos cidadãos.","Não reconhecimento de direitos políticos aos cidadãos e exercício da acção dirigente do Estado e da sociedade; observação dos princípios da economia de mercado, responsabilizando-se a produção e oferta de bens e serviços ao sector privado e público em função da oferta e procura; controle, planificação da economia e alocação, pelo Estado de bens e serviços aos cidadãos.","Reconhecimento de direitos políticos aos cidadãos; legitimação do poder e das instituições através de eleições democráticas e transparentes, sob voto livre e secreto; observação dos princípios da economia de mercado, responsabilizando-se a produção e oferta de bens e serviços ao sector privado e público, em função da oferta e procura."],"c":3,"e":"A Constituição de 1990 instituiu o multipartidarismo, direitos políticos, eleições livres e economia de mercado."},{"n":58,"tema":"VII. Moçambique e África contemporânea","p":"Certos países da África Ocidental e da região Africana do Sahel, conheceram, no ano corrente, contrariamente à ordem constitucional democrática, golpes de estado. Identifique-os:","o":["Namíbia, Mali, Níger, Etiópia, Gabão.","Mali, Níger, Chade, Sudão, Gabão, Burkina Faso.","Egipto, Tunísia, Chade, Botswana, Etiópia.","Angola, Marrocos, Argélia, Zimbabwe, Egipto."],"c":1,"e":"Mali, Níger, Chade, Sudão, Gabão e Burkina Faso sofreram golpes de Estado em 2020-2023; as outras listas incluem países sem golpes recentes (Namíbia, Botswana, Angola...)."},{"n":59,"tema":"VII. Moçambique e África contemporânea","p":"Indique factores associados na origem dos recentes golpes de estado em países da região de África Ocidental e região do Sahel","o":["Perda de legitimidades dos governos nacionais em consequência da limitada capacidade de produção de bens e serviços públicos.","Perda de legitimidades dos governos nacionais em consequência da limitada capacidade de produção de bens e serviços públicos, ineficácia das políticas de desenvolvimento por causa da governação não transparente e influência negativa da ingerência das antigas potências coloniais.","Natureza autoritária dos governos depostos e o ciclo prolongado de fracasso de políticas de desenvolvimento.","Ciclo prolongado de fracasso de políticas de desenvolvimento e ineficácia dos governos democráticos."],"c":1,"e":"B é a mais completa (perda de legitimidade, fracasso das políticas, má governação e ingerência neocolonial). Questão interpretativa; C também é defensável.","d":1},{"n":60,"tema":"VII. Moçambique e África contemporânea","p":"O conflito entre Israel e a Palestina é um problema decorrente da segunda Grande Guerra. O primeiro ocorreu de Maio de 1948 a Julho de 1949, em oposição à fundação do Estado de Israel; O segundo, nos anos de 1950, a invasão, por Israel, da faixa de Gaza e a Península do Sinai no contexto da crise entre Egipto e a França e o Reino Unido; o terceiro, a guerra dos seis dias em 1967 após ataques por Israel contra a Síria, de que resultou a tomada da Faixa de Gaza, a Península do Sinai, as Colinas de Golã da Síria, Jerusalém Oriental e Cisjordânia; o quarto, a em 1973, em que países árabes derrotados na guerra de seis dias tentaram reaver seus territórios; o quarto, em 1987, em que a população Palestina, recorrendo a meios precários, revoltou-se contra a usurpação de suas terras, facto contra o qual Israel reagiu massacrando população Palestina indefesa. Assinale alternativa que explica este fenómeno:","o":["Existência de uma relação antagónica entre Israel, por a sua população ser da religião judaica e a Palestina, por ser formada por comunidades árabes.","Necessidade de conquista de terra como espaço vital para o Estado.","Oposição natural de Israel contra os Árabes por a mitologia do judaísmo tomar os Judeus como povo eleito para dominar a região.","Estratégia dos países com poder global depois da segunda Grande Guerra de fundar o Estado de Israel como plataforma para contextos cíclicos de guerra, que se revelam apropriados para venda de armas e reprodução do seu poder bélico, industrial e económico, através de alianças que permitem o controle e acesso a recursos energéticos."],"c":3,"e":"A prova opta pela leitura geopolítica e económica (D) em vez da explicação religiosa ou étnica (A, C). Pergunta de interpretação e opinião; melhor leitura: D.","d":1}]},{"id":"his-2022","subj":"his","titulo":"Exame de História","inst":"Comissão de Exames de Admissão","ano":2022,"tempo":120,"q":[{"n":1,"tema":"Historiografia","p":"Sob o ponto de vista epistemológico o termo história significa:","o":["Conto","Passado","Testemunha","Trajectória"],"c":2,"e":"Do grego <i>historía</i>/<i>histor</i>: aquele que vê, testemunha, e daí a investigação. Das opções dadas, \"testemunha\" é a mais próxima da etimologia; a questão é pouco precisa.","d":1},{"n":2,"tema":"Historiografia","p":"A escrita cuneiforme foi inventada por volta do IV milénio a.C. Esta escrita foi inventada pelos:","o":["Sumérios","Egípcios","Babilónios","Romanos"],"c":0,"e":"A escrita cuneiforme surgiu na Mesopotâmia, criada pelos Sumérios (c. 3300-3100 a.C.); os Egípcios usavam hieróglifos."},{"n":3,"tema":"Historiografia","p":"A historiografia cristã antiga deixou os Homens com uma visão curta ao …","o":["Incutir o preconceito de bem e mal","Incutir o preconceito de pecado","Incutir o preconceito de pecado, do bem e do mal","Incutir a aceitação do ser supremo"],"c":2,"e":"A historiografia cristã (Eusébio, Santo Agostinho) explicava a história pela providência divina, incutindo as noções de pecado, bem e mal. A opção C é a mais completa; a formulação é vaga.","d":1},{"n":4,"tema":"Historiografia","p":"A história dos Annales incentivou o desenvolvimento da chamada “história nova”, uma história explicativa, problemática, profunda e total. A escola dos Annales foi representada por nomes como:","o":["Nicolau Maquiavel, William Shakespeare e Damião Góis","Joseph Ki-Zerbo, Samir Amin e Frederick Cooper","Karl Marx, Friedrich Engels e Leopold Ranke","Marc Bloch, Lucien Febvre e Marc Ferro"],"c":3,"e":"A escola dos Annales (1929) foi fundada por Marc Bloch e Lucien Febvre, e continuada por Marc Ferro, entre outros."},{"n":5,"tema":"Historiografia","p":"Maquiavel foi mentor da concepção do Estado temporal em oposição ao Estado secular. Em que consistia essa concepção?","o":["Na existência de um soberano independente da igreja, centralização do poder","Na existência de uma igreja independente do soberano, centralização do poder e eleição de dirigentes","Na existência de um soberano independente da igreja, centralização do poder e eleição de dirigentes","Na existência de um mundo capitalista cujo poder é centralizado e os dirigentes são eleitos"],"c":0,"e":"Maquiavel defendia um Estado laico, com soberano autónomo face à Igreja e poder centralizado; não defendia a eleição dos dirigentes.","d":1},{"n":6,"tema":"Historiografia","p":"No século XVII, desenvolve-se o RACIONALISMO e o EMPIRISMO. Identifique os seus fundadores.","o":["René Descartes e John Locke","René Descartes e Montesquieu","John Locke e Voltaire","Santo Agostinho e Eusébio de Cesareia"],"c":0,"e":"Descartes é o fundador do racionalismo e Locke (com Bacon) do empirismo."},{"n":7,"tema":"Historiografia","p":"A história consiste na sucessão dos modos de produção. Identifique os defensores desta concepção.","o":["Positivistas","A escola dos Annales","Marxistas","Socialistas utópicos"],"c":2,"e":"O materialismo histórico marxista concebe a história como sucessão de modos de produção (comunidade primitiva, esclavagismo, feudalismo, capitalismo...)."},{"n":8,"tema":"Historiografia","p":"“África é um continente sem História”. Identifique a corrente que defende este posicionamento.","o":["Afrocentrista","Eurocentrista","Progressista","A Escola dos Annales"],"c":1,"e":"A corrente eurocentrista (Hegel, Trevor-Roper) negava história a África por falta de fontes escritas."},{"n":9,"tema":"Historiografia","p":"Um dos principais constrangimentos da Historiografia Africana está relacionado com:","o":["a abundância de especialistas formados em ciências naturais no continente","a existência em excesso de fontes escritas sobre os estados africanos desde os tempos remotos","a ausência total de fontes orais sobre a história do continente","a existência de vastas regiões de África com poucas ou nenhumas fontes escritas sobre períodos antigos"],"c":3,"e":"Em muitas regiões africanas há escassez de fontes escritas antigas, o que obriga ao recurso à tradição oral e à arqueologia."},{"n":10,"tema":"Historiografia","p":"O tratamento das fontes na ciência histórica obedece aos seguintes passos:","o":["análise, crítica e síntese","crítica, síntese e análise","crítica, análise e síntese","síntese, análise e crítica"],"c":0,"e":"Segue-se a ordem lógica: análise das fontes, crítica (externa e interna) e, por fim, síntese. A formulação difere consoante os manuais.","d":1},{"n":11,"tema":"Historiografia","p":"Restos de habitação abandonados por uma determinada sociedade representam:","o":["Um documento arqueológico","Um documento material e inconsciente","Um documento escrito e consciente","Um documento numismático e inconsciente"],"c":1,"e":"Vestígios de habitação são fontes materiais e não intencionais (inconscientes). A também é defensável, mas B é mais completa.","d":1},{"n":12,"tema":"História Geral","p":"A Guerra do Peloponeso foi a maior guerra da história:","o":["da Grécia clássica","da Mesopotâmia","do Egipto antigo","da Fenícia"],"c":0,"e":"A Guerra do Peloponeso (431-404 a.C.) opôs Atenas e Esparta na Grécia clássica."},{"n":13,"tema":"História Geral","p":"As reformas introduzidas por Drácon e Sólon permitiram reforçar o poder:","o":["Tirânico","Instituições democráticas","Oligárquico","Aristocrático"],"c":1,"e":"As reformas de Drácon (leis escritas) e Sólon (fim da escravatura por dívidas, classes censitárias) abriram caminho à democracia ateniense."},{"n":14,"tema":"História Geral","p":"A Dinastia Stuart chega ao trono em 1625 pelo rei Carlos. Esta dinastia era do tipo:","o":["Parlamentar","Absolutista","Democrática","Liberal"],"c":1,"e":"Carlos I Stuart defendia o absolutismo de direito divino, o que levou ao conflito com o Parlamento e à guerra civil."},{"n":15,"tema":"História Geral","p":"A Batalha de Saratoga foi a decisiva na guerra de independência dos EUA e deu-se a…","o":["1689","1750","1777","1882"],"c":2,"e":"A vitória americana em Saratoga (Outubro de 1777) conseguiu o apoio da França."},{"n":16,"tema":"História Geral","p":"Desde a sua fundação até 1945, ano da realização do Congresso de Manchester, o movimento Pan-Africano realizou vários congressos e conferências. Entretanto, o Congresso de Manchester distinguiu-se dos anteriores por:","o":["ter sido o primeiro a ser realizado numa cidade de um país colonizador, a Inglaterra","ter pedido apoio dos EUA e da ex-URSS para a causa da libertação da África","ter sido o primeiro em que africanos originários tomaram parte activa na sua preparação e realização","ter decidido criar um partido continental que negociava a independência simultânea de todos os africanos"],"c":2,"e":"O V Congresso (Manchester, 1945) foi o primeiro com forte presença e liderança de africanos (Nkrumah, Kenyatta), em vez de afro-americanos."},{"n":17,"tema":"História Geral","p":"A 9 de Novembro de 1799, o governo do Directório foi derrubado na França sob o comando de…","o":["Napoleão Bonaparte","Rei Henrique VIII","Heródoto","Martinho Lutero"],"c":0,"e":"O golpe do 18 Brumário (9 de Novembro de 1799) foi liderado por Napoleão Bonaparte."},{"n":18,"tema":"História Geral","p":"Em Junho de 1815, Napoleão entra na Bélgica, mas é derrotado por uma coligação anglo-prussiana na Batalha de…","o":["Zanzibar","Moscovo","Saratoga","Waterloo"],"c":3,"e":"Waterloo (18 de Junho de 1815), contra Wellington e Blücher, pôs fim aos Cem Dias."},{"n":19,"tema":"História Geral","p":"O acontecimento que marcou o início da Revolução Francesa a 14 de Julho de 1789 foi …","o":["o estabelecimento da República Burguesa","o estabelecimento do Directório","a queda do muro de Berlim","a tomada da Bastilha"],"c":3,"e":"A tomada da Bastilha, a 14 de Julho de 1789, simboliza o início da Revolução Francesa."},{"n":20,"tema":"História Geral","p":"A Declaração dos Direitos do Homem e do Cidadão foi adoptada pela primeira vez na...","o":["Revolução burguesa inglesa de 1688","Revolução burguesa francesa em 1789","Revolução americana de 1776","Revolução socialista de 1917"],"c":1,"e":"A Declaração dos Direitos do Homem e do Cidadão foi aprovada pela Assembleia Nacional francesa a 26 de Agosto de 1789."},{"n":21,"tema":"História Geral","p":"Os países que rubricaram o tratado de Brest-Litovsk foram:","o":["Áustria e Rússia","França e Portugal","Alemanha e Rússia","Inglaterra e Alemanha"],"c":2,"e":"O tratado de Brest-Litovsk (Março de 1918) retirou a Rússia soviética da I Guerra Mundial, em paz com as Potências Centrais, lideradas pela Alemanha."},{"n":22,"tema":"História Geral","p":"Uma das façanhas mais marcantes da II Guerra Mundial foi o chamado “Dia D” que residiu essencialmente em...","o":["Bombardeamento da base naval americana de Pearl Harbour, no Havai, pelos japoneses","Bombardeamento da base naval americana de Pearl Harbour, no Havai, pelos alemães","Ataques japoneses aos territórios da Ásia: Indochina, Singapura e Sumatra","Desembarque das tropas aliadas na Normandia"],"c":3,"e":"O Dia D (6 de Junho de 1944) foi o desembarque aliado na Normandia."},{"n":23,"tema":"História de África","p":"A Comunidade de Desenvolvimento da África Austral (SADC) é actualmente presidida por…","o":["Tomás Vieira","Yoweri Museveni","Paul Kagame","Lazarus Chakwera"],"c":3,"e":"Em 2021-2022 a presidência rotativa da SADC pertenceu ao Malawi, Lazarus Chakwera. A resposta depende da data da prova.","d":1},{"n":24,"tema":"História de África","p":"Entre o último semestre de 1987 e o primeiro semestre de 1988 desenrolou-se uma confrontação militar envolvendo as tropas sul-africanas, cubanas e também angolanas no Sudoeste Africano. Estamos a falar da …","o":["Batalha de Luanda Norte","Batalha dos Nama e Herero","Batalha de Adua","Batalha do Cuito Cuanavale"],"c":3,"e":"A batalha do Cuito Cuanavale (1987-88), em Angola, opôs as FAPLA/Cuba à África do Sul e acelerou a independência da Namíbia."},{"n":25,"tema":"História de África","p":"O Tratado de Naivasha, assinado em 9 de Janeiro de 2005, no Quénia, abriu espaço para o reconhecimento do último estado independente em África. Trata-se da independência de…","o":["Sudão do Sul em 9 de Julho de 2011","Sudão do Norte em 11 de Agosto de 2011","República da Libéria em 9 de Janeiro de 2005","Nova Zimbabwe em 13 de Maio de 2012"],"c":0,"e":"O Acordo de Naivasha (CPA) levou ao referendo e à independência do Sudão do Sul, a 9 de Julho de 2011."},{"n":26,"tema":"História de África","p":"O canal de Suez foi aberto em:","o":["1569","1669","1769","1869"],"c":3,"e":"O canal de Suez foi inaugurado em Novembro de 1869 (Ferdinand de Lesseps)."},{"n":27,"tema":"História de África","p":"Em 1914 apenas dois países africanos continuavam livres da colonização europeia. Estamos a falar de:","o":["Tunísia e Etiópia","Namíbia e Líbia","Etiópia e Libéria","Libéria e Líbia"],"c":2,"e":"Em 1914 só a Etiópia e a Libéria eram independentes."},{"n":28,"tema":"História de África","p":"Portugal e Inglaterra assinaram um tratado segundo o qual os ingleses reconheciam a soberania portuguesa nos territórios das duas margens do rio Zaire até às fronteiras do Estado do Congo. De que tratado se trata?","o":["Tratado do Zaire de 26 de Fevereiro de 1884","Tratado do Congo de 26 de Fevereiro de 1884","Tratado de Berlim de 26 de Fevereiro de 1884","Tratado de Berlim de 24 de Fevereiro de 1884"],"c":0,"e":"É o Tratado anglo-português do Zaire (Congo), de 26 de Fevereiro de 1884, que nunca foi ratificado. A e B são designações do mesmo tratado; melhor leitura: A, como nos manuais moçambicanos.","d":1},{"n":29,"tema":"História de África","p":"África foi colonizada pelos europeus. Identifique um dos factores políticos que levaram à colonização de África pelos europeus.","o":["Afirmar o prestígio e o poder nacional","Afirmar a riqueza das nações","Mostrar prestígio e poder nacional","Afirmar a autoridade e o poder nacional"],"c":0,"e":"Entre os factores políticos do imperialismo conta-se a afirmação do prestígio e do poder nacional. A e C são quase idênticas; melhor leitura: A.","d":1},{"n":30,"tema":"História de África","p":"As línguas bantu espalharam-se através da zona tropical, com um período de diferenciação local nas regiões de floresta e savana, antes da sua expansão final para oriente e região sul oriental. Identifique o autor desta teoria.","o":["Joseph Greenberg","Christopher Ehret","Roland Oliver","David Phillipson"],"c":1,"e":"A teoria da expansão por fases pela zona tropical é atribuída a Christopher Ehret; Greenberg propôs a origem Camarões/Nigéria e Oliver a expansão rápida. Confiança moderada.","d":1},{"n":31,"tema":"História de Moçambique","p":"O multipartidarismo é uma realidade no nosso país. Que instrumento legitimou o multipartidarismo em Moçambique?","o":["Acordo Geral de Paz de 1992","Declaração Universal dos Direitos Humanos","Constituição de 1990","III Congresso da Frelimo"],"c":2,"e":"A Constituição de 1990 consagrou o multipartidarismo e as liberdades democráticas."},{"n":32,"tema":"História de Moçambique","p":"A realização de eleições gerais em Moçambique constitui uma das manifestações da democracia moçambicana. Quando é que foram realizadas as primeiras eleições multipartidárias em Moçambique?","o":["1990","1994","1992","1999"],"c":1,"e":"As primeiras eleições gerais multipartidárias realizaram-se a 27-29 de Outubro de 1994, após o AGP de 1992."},{"n":33,"tema":"História de Moçambique","p":"Na História de Moçambique, Afonso Dhlakama foi um político revolucionário e líder carismático da RENAMO. A sua morte ocorreu na Serra da Gorongosa em…","o":["02 de Fevereiro de 2015","03 de Maio de 2018","10 de Maio de 2018","22 de Fevereiro de 2021"],"c":1,"e":"Afonso Dhlakama morreu a 3 de Maio de 2018, na Serra da Gorongosa."},{"n":34,"tema":"História de Moçambique","p":"Diferentemente da grande crise financeira global, que produziu perda permanente de produtos nos Estados Unidos e na Europa, no evento actual da pandemia as economias devem, após o término das campanhas de vacinação, voltar a operar na mesma tendência vigente antes da crise. A COVID-19 é a doença infecciosa descoberta muito recentemente em…","o":["Kawasaki em Outubro de 2019","Caxemira em Novembro de 2019","Califórnia em Dezembro de 2019","Wuhan em Dezembro de 2019"],"c":3,"e":"Os primeiros casos de COVID-19 foram identificados em Wuhan (China), em Dezembro de 2019."},{"n":35,"tema":"História de Moçambique","p":"Em Moçambique, as eleições gerais e multipartidárias são organizadas e geridas por dois órgãos, nomeadamente o Secretariado Técnico de Administração Eleitoral (STAE) e a Comissão Nacional de Eleições (CNE). Durante as eleições de 1994, a CNE era presidida por:","o":["Jamisse Taimo","Joaquim Chissano","Brazão Mazula","Pascoal Mucumbe"],"c":2,"e":"Brazão Mazula presidiu à CNE nas eleições de 1994."},{"n":36,"tema":"História de Moçambique","p":"As últimas eleições gerais multipartidárias realizadas em Moçambique (15 de Outubro de 2019) foram bastante concorridas; com efeito, enquanto para a Assembleia da República concorreram 26 partidos e coligações, para a Presidência da República concorreram:","o":["4 candidatos","7 candidatos","12 candidatos","14 candidatos"],"c":0,"e":"Em 2019 concorreram quatro candidatos presidenciais: Nyusi, Ossufo Momade, Daviz Simango e Mário Albino."},{"n":37,"tema":"História de Moçambique","p":"Com o objectivo de garantir uma paz efectiva e duradoura, o Presidente da República, Filipe Jacinto Nyusi, procedeu ao lançamento oficial do Processo de Desarmamento, Desmobilização e Reintegração (DDR) dos homens residuais da Renamo, no âmbito dos consensos alcançados entre o Governo e a Renamo, em Maputo, a…","o":["03 de Fevereiro de 2017","06 de Outubro de 2018","25 de Setembro de 2019","19 de Dezembro de 2020"],"c":1,"e":"O DDR decorre do Memorando de Entendimento sobre Assuntos Militares (Agosto de 2018); a melhor leitura da data do lançamento oficial é 6 de Outubro de 2018, mas não consegui confirmar.","d":1},{"n":38,"tema":"História de Moçambique","p":"O I Congresso da FRELIMO em solo pátrio decorreu entre 20 e 25 de Julho de 1968 em…","o":["Matola","Matchedje","Bilene","Pemba"],"c":1,"e":"O II Congresso da Frelimo (1968) realizou-se em Matchedje, província do Niassa, nas zonas libertadas. A opção \"Madjedje\" corresponde a Matchedje."},{"n":39,"tema":"História de Moçambique","p":"O nome de Changamire Dombo é muito importante na História das relações entre os mercadores portugueses e o Estado dos Mwenemutapas. Com efeito foi Changamire quem:","o":["Assinou um acordo de assistência militar com o capitão português de Tete","Comandou uma revolta armada generalizada contra a presença portuguesa no Estado","Concedeu privilégios comerciais aos mercadores portugueses","Autorizou, pela primeira vez, os portugueses a construírem igrejas e feitorias"],"c":1,"e":"Changamire Dombo (c. 1684-1696) liderou a revolta que expulsou os portugueses do planalto do Zimbabwe e do Estado dos Mwenemutapas."},{"n":40,"tema":"História de Moçambique","p":"Daviz Mbepo Simango foi uma figura incontornável na política moçambicana ao destacar-se como Presidente do Conselho Municipal da Beira e do partido Movimento Democrático de Moçambique. Daviz Simango morreu a:","o":["22 de Fevereiro de 2021","07 de Setembro de 2019","17 de Outubro de 2020","28 de Abril de 2021"],"c":0,"e":"Daviz Simango morreu a 22 de Fevereiro de 2021, na África do Sul, vítima de doença."},{"n":41,"tema":"História de Moçambique","p":"O regime colonial português substituiu o imposto de palhota pelo imposto de capitação em:","o":["1910","1915","1930","1942"],"c":3,"e":"Resposta provável: 1942, mas não consegui confirmar a data da substituição.","d":1},{"n":42,"tema":"História de Moçambique","p":"Os prazos eram atribuídos aos colonos portugueses idos de Goa, por:","o":["uma geração","duas gerações","três gerações","quatro gerações"],"c":2,"e":"Os prazos da Coroa eram concedidos por três vidas (gerações), por via feminina."},{"n":43,"tema":"História de Moçambique","p":"Entre 1976 e 1992, Moçambique foi assolado pela guerra civil cujo término foi assinalado pela assinatura do Acordo Geral de Paz. Localize no tempo e espaço o referido acordo.","o":["1990, na Itália","1992, em Roma","1994, no Vaticano","1991, em Roma"],"c":1,"e":"O Acordo Geral de Paz foi assinado em Roma a 4 de Outubro de 1992 por Chissano e Dhlakama."},{"n":44,"tema":"História de Moçambique","p":"O lobolo é um mecanismo de estabilidade dos casamentos e de subordinação da mulher em relação ao homem. De que sociedade é característica esta prática?","o":["Patrilinear ou Uxorilocalidade","Patrilinear","Martilinear ou Virolocalidade","Qualquer sociedade"],"c":1,"e":"O lobolo é típico das sociedades patrilineares (do sul de Moçambique), em que a mulher vai viver com a família do marido. A uxorilocalidade é própria das matrilineares."},{"n":45,"tema":"História de Moçambique","p":"Para garantir a soberania, o Estado vale-se de muitos instrumentos. Identifique-os.","o":["Polícia, território, tribunais, cadeias, imprensa, educação","Polícia, população, tribunais, cadeias, imprensa, educação","Polícia, exército, tribunais, cadeias, imprensa, educação","Presidente, Ministérios, Polícia, população, tribunais, cadeias"],"c":2,"e":"Os instrumentos do Estado são aparelhos de repressão e ideológicos: polícia, exército, tribunais, cadeias, imprensa, educação. Território e população são elementos do Estado, não instrumentos."},{"n":46,"tema":"História de Moçambique","p":"O encontro entre árabes e povos de Moçambique resultou no aparecimento de novos núcleos linguísticos a destacar…","o":["Mwali, nahara e coti","Mwani, nahara e coti","Mwani, wahara e coti","Bantu, nahara e coti"],"c":1,"e":"Do contacto árabe-bantu surgiram o kimwani, o nahara e o koti (kikoti), no litoral norte."},{"n":47,"tema":"História de Moçambique","p":"No século XVI, foram criados os prazos no vale do Zambeze. Identifique a origem das terras dos prazeiros.","o":["Doação, compra e conquista","Doação, pilhagem e conquista","Conquista, doação e escravização","Pilhagem e compra"],"c":0,"e":"As terras dos prazeiros resultaram de doação (por chefes africanos), compra e conquista."},{"n":48,"tema":"História de Moçambique","p":"A concessão dos prazos era feita de preferência por via feminina para…","o":["atrair mulheres solteiras brancas a povoarem o vale do Zambeze","atrair casais brancos a povoarem o vale do Zambeze","atrair homens e mulheres brancos a povoarem o vale do Zambeze","atrair mulheres solteiras brancas a casarem com africanos no vale do Zambeze"],"c":0,"e":"A transmissão por via feminina (a herdeira devia casar com um português) visava atrair mulheres brancas e fixar população portuguesa no Zambeze. A formulação é discutível.","d":1},{"n":49,"tema":"História de Moçambique","p":"Moçambique separa-se de Goa em 1752. Qual foi o objectivo dessa separação?","o":["Subordinar-se directamente a Lisboa","Subordinar-se directamente a Portugal","Subordinar-se ao Governador-Geral de Moçambique","Subordinar-se directamente ao governador de Moçambique"],"c":0,"e":"Em 1752 Moçambique tornou-se governo autónomo, dependente directamente de Lisboa (Coroa) e já não do Estado da Índia. A e B são quase equivalentes.","d":1},{"n":50,"tema":"História de Moçambique","p":"O filho nascido de um casamento pertence à família da mãe. Esta ligação é típica da sociedade…","o":["Patrilinear","Matrilinear ou Uxorilocalidade","Matrilinear ou Virolocalidade","Patrilinear e Matrilinear"],"c":1,"e":"Na sociedade matrilinear a filiação segue a linha da mãe, com residência uxorilocal (na família da mulher). A opção C está mal formulada."}]},{"id":"his-up-2019","subj":"his","titulo":"Exame de Admissão de História","inst":"Universidade Pedagógica (UP)","ano":2019,"tempo":120,"q":[{"n":1,"tema":"Historiografia","p":"As primeiras literaturas de carácter histórico foram","o":["Os antigos escritos hieróglifos egípcios.","As cosmogonias e mitografias.","O código de Hamurabi.","Os antigos escritos cuneiformes sobre a Mesopotâmia."],"c":0,"e":"Dúvida: A e D são ambas defensáveis (escritos egípcios e mesopotâmicos), e B também aparece em manuais. Melhor leitura: A, os escritos hieroglíficos do Egipto, os mais antigos registos de carácter histórico.","d":1},{"n":2,"tema":"Historiografia","p":"A principal característica da historiografia judaica foi:","o":["Ter a Bíblia como elemento sagrado de união dos hebreus.","O monoteísmo ou fidelidade à Jeová como único Deus.","Incapacidade de aceder à visão universalista do Homem.","Atribuir aos seus líderes um poder espiritual e temporal."],"c":1,"e":"Dúvida: A e B são defensáveis. Melhor leitura: B, pois a história hebraica é vista como obra do Deus único (Jeová), que dirige o povo escolhido.","d":1},{"n":3,"tema":"Historiografia","p":"A mitologia grega considerava que a humanidade tinha passado por cinco etapas de evolução nomeadamente a idade do ouro, da prata, do bronze, dos heróis e do ferro. A etapa do ouro é a melhor porque:","o":["Nela havia muito que podia proporcionar riqueza.","Nela não havia preocupações, sofrimento, velhice, etc.","Nela a Grécia colonizou as ilhas do Mediterrâneo","Nela os Gregos fundaram as cidades de Atenas e Esparta."],"c":1,"e":"Em Hesíodo, a idade do ouro era uma época de paz e abundância, sem trabalho, doença nem velhice."},{"n":4,"tema":"Historiografia","p":"O grande contributo de Tucídides para a história foi:","o":["Ter acreditado em Heródoto nas suas viagens.","Ter participado na guerra do Peloponeso e produzido uma obra sobre a mesma.","Ter iniciado o questionamento das fontes, procurando apurar a sua veracidade e credibilidade.","Ter sido o cidadão grego que mais obras escreveu sobre a antiguidade clássica."],"c":2,"e":"Tucídides é considerado pioneiro do método crítico: confrontava testemunhos e procurava a veracidade. Ter participado na guerra é um facto, mas não o seu contributo metodológico."},{"n":5,"tema":"Historiografia","p":"A Historiografia Romana antiga foi apologética e pragmática, e, foi obra de:","o":["Políbio, Tito Lívio, Xenofonte, Éforo, etc.","Plutarco, Políbio, Tito Lívio, Flávio Josefo, Xenofonte.","Éforo, Salústio, Suetónio, Marc Bloch.","Flávio Josefo, Salústio, Suetónio, Políbio, Tácito, Tito Lívio, etc."],"c":3,"e":"Só a opção D reúne apenas autores da época romana (Salústio, Tácito, Tito Lívio, Suetónio, Políbio, Josefo). Xenofonte e Éforo são gregos e Marc Bloch é contemporâneo."},{"n":6,"tema":"Historiografia","p":"Apesar dos grandes contributos dados pela historiografia positivista, ela recebeu algumas críticas pelo facto de:","o":["Defender a relatividade do conhecimento em oposição ao conhecimento absoluto.","Reconhecer apenas três estágios da evolução da sociedade: Teológico, Metafísico e Positivo.","Reduzir o papel do historiador e tentar formular leis para explicar os factos históricos.","Não ter não ter se enquadrado nos debates entre os idealistas e os materialistas."],"c":2,"e":"O positivismo foi criticado por reduzir o historiador a mero compilador de documentos 'objectivos' e por querer encontrar leis gerais da história, como nas ciências naturais."},{"n":7,"tema":"Historiografia","p":"No contexto da História dos Annales a frase “A verdadeira História é uma História Universal”; pertence a:","o":["Lucien Febvre","Marc Bloch","Fernand Braudel","Vitorino Magalhães Godinho"],"c":1,"e":"Dúvida: não consegui confirmar a origem exacta da frase. Melhor leitura: Marc Bloch, que defendia a história comparada e de âmbito alargado.","d":1},{"n":8,"tema":"Historiografia","p":"A proliferação das fontes escritas sobre África a partir do século XV foi obra de:","o":["Mercadores europeus.","Exércitos coloniais","Missionários","Administradores coloniais."],"c":0,"e":"Dúvida: mercadores, navegadores e missionários produziram relatos. Melhor leitura: A, mercadores europeus, activos desde o século XV; os exércitos e administradores coloniais surgem sobretudo no século XIX.","d":1},{"n":9,"tema":"Historiografia","p":"As fontes orais são preponderantes para reconstituir a História de África. Elas permitem:","o":["Lançar a pergunta e ter a resposta de imediato; fazer vários questionamentos antes de registar a resposta, perceber o que o narrador diz e o que pretendia dizer; associar os gestos às palavras.","Reconstituir varias linhagens a partir de uma única fonte que vai narrando a historia de uma geração para outra.","Integrar os mitos que legitimaram as acções de certos reis.","Permitem ao narrador corrigir de imediato a sua resposta e acrescentar algo sempre que quiser."],"c":0,"e":"A vantagem da fonte oral é a interacção directa: o historiador questiona, esclarece o sentido e observa gestos e entoação. As restantes opções são parciais ou imprecisas."},{"n":10,"tema":"Historiografia","p":"Na historiografia Moçambicana a obra “Lutar por Moçambique” pertence a:","o":["Samora Machel","Marcelino dos Santos","Eduardo Mondlane","Malyn Newitt"],"c":2,"e":"“Lutar por Moçambique” (1969) é de Eduardo Mondlane, primeiro presidente da FRELIMO."},{"n":11,"tema":"História Geral","p":"As primeiras sociedades de classes foram:","o":["Grega e Romana","Egípcia e Mesopotâmica","Egípcia e Indiana","Americana"],"c":1,"e":"As primeiras sociedades de classes surgiram no Oriente antigo, no Egipto e na Mesopotâmia, por volta de 3000 a.C."},{"n":12,"tema":"História Geral","p":"Na periodização da História considera-se que a queda do Império Romano do Ocidente marca o início da Idade Média. Esta ocorreu no ano de:","o":["1543","1914","476","1505"],"c":2,"e":"Em 476 d.C. Odoacro depôs Rómulo Augústulo, último imperador romano do Ocidente."},{"n":13,"tema":"História Geral","p":"Na vigência do absolutismo na Europa, a frase: “O estado sou eu” pertence a:","o":["Napoleão Bonaparte","Luís XVI","Adolfo Hitler","Luís XIV"],"c":3,"e":"A frase é atribuída a Luís XIV, o Rei-Sol, símbolo do absolutismo francês."},{"n":14,"tema":"História Geral","p":"Para impulsionar a expansão marítima portuguesa foi fundada em Sagres, em 1417, um centro de construção e estudos navais, onde concentrava os maiores conhecedores da ciência náutica da época. Essa obra pertence a:","o":["Dom Sebastião, o desejado.","Luís de Camões","Vasco da Gama","Dom Afonso Henrique"],"c":3,"e":"A Escola de Sagres é atribuída ao Infante D. Henrique; a opção D traz 'Afonso Henrique' (provável erro de impressão por 'Henrique'). É a única opção plausível, pois as outras são de outras épocas.","d":1},{"n":15,"tema":"História Geral","p":"A Reforma protestante iniciada na Europa no século XVI ganhou maior expressão nos seguintes países:","o":["França, Bélgica e Inglaterra","Alemanha, França e Itália.","Suíça, Inglaterra e Alemanha","Alemanha, Espanha e Portugal"],"c":2,"e":"A Reforma (Lutero, Calvino, Henrique VIII) prosperou na Alemanha, Suíça e Inglaterra; Espanha, Portugal e Itália permaneceram católicas."},{"n":16,"tema":"História Geral","p":"A contra reforma ou reforma católica foi materializada através de:","o":["Perseguição e morte dos protestantes.","Concílio de Trento, Inquisição, Index e Companhia de Jesus.","Inquisição, Index, companhia de Jesus e teocentrismo.","Concílio de Trento e proclamação da autoridade suprema do Papa."],"c":1,"e":"Os instrumentos da Contra-Reforma foram o Concílio de Trento (1545-63), a Inquisição, o Index de livros proibidos e a Companhia de Jesus."},{"n":17,"tema":"História Geral","p":"A primeira Constituição que contemplava a separação de poderes foi:","o":["Americana de 1777.","Francesa de 1789.","Americana de 1787.","Inglesa de 1642."],"c":2,"e":"A Constituição dos EUA de 1787 foi a primeira escrita a consagrar a separação de poderes (legislativo, executivo, judicial). A de 1777 corresponde aos Artigos da Confederação."},{"n":18,"tema":"História Geral","p":"Durante a Revolução francesa, Napoleão Bonaparte é nomeado comandante do Exército francês em:","o":["1795","1789","1791","1821"],"c":0,"e":"Em 1795, após reprimir a insurreição realista de 13 Vendimiário, Napoleão foi nomeado comandante do Exército do Interior; em 1796 passou ao de Itália. Das opções, 1795 é a melhor.","d":1},{"n":19,"tema":"História Geral","p":"A guerra Franco- prussiana que se desenrolou entre 1870 – 1871 foi um conflito entre:","o":["França e Rússia","Rússia e Alemanha","Alemanha e França","EUA e Japão"],"c":2,"e":"Foi o conflito entre a França de Napoleão III e a Prússia e aliados, que levou à unificação alemã."},{"n":20,"tema":"História Geral","p":"A Revolução Socialista de Outubro de 1917 foi dirigida por:","o":["Karl Marx.","Mikhail Gorbatchov","Vladimir Lenin","Friedrich Engels"],"c":2,"e":"Lenine liderou os bolcheviques na Revolução de Outubro de 1917."},{"n":21,"tema":"História de África","p":"O tratado de Zaire assinado a 26 de Fevereiro de 1884 visava resolver as contradições entre:","o":["Bélgica e Alemanha","Inglaterra e França","Portugal e Inglaterra","Portugal e Espanha"],"c":2,"e":"O Tratado do Zaire (Westminster, 1884) entre Portugal e Inglaterra reconhecia a soberania portuguesa na foz do Congo, em troca de liberdade de comércio; foi uma das causas da Conferência de Berlim."},{"n":22,"tema":"História de África","p":"No âmbito das relações comerciais entre África e Europa durante o período colonial a África estava encarregue de:","o":["Fornecer escravos.","Fornecer matéria-prima e consumir produtos manufacturados.","Abastecer os exércitos coloniais através de recrutamento de militares africanos.","Exaltar e defender as metrópoles."],"c":1,"e":"No sistema colonial, África fornecia matérias-primas e era mercado para os produtos manufacturados das metrópoles. O fornecimento de escravos é anterior."},{"n":23,"tema":"História de África","p":"Entre os séculos XVI e XVIII, a África participou no comércio triangular principalmente com os seguintes produtos","o":["Marfim, peles de animais e ouro.","Café, cacau e óleo de palma","Escravos","Sal e conchas."],"c":2,"e":"No comércio triangular o principal produto africano foi o escravo, enviado para as Américas."},{"n":24,"tema":"História de África","p":"Os três Estados africanos pré-coloniais que ocuparam sucessivamente a mesma extensão territorial foram:","o":["Grande Zimbabwe, Manyikeni e Marave.","Shroda, Mapungubwe e Menemutapa.","Gana, Mali e Songhay.","Grande Zimbabwe, Manyikeni e Mwenemutapa."],"c":2,"e":"Gana, Mali e Songhai sucederam-se na mesma região do Sudão Ocidental (séc. VIII-XVI). As outras opções misturam estados coexistentes ou de regiões diferentes."},{"n":25,"tema":"História de África","p":"O termo gana que mais tarde seria usado para designar o grande império que se desenvolveu na África Ocidental, significa:","o":["Terra de Ouro.","Grande Guerreiro.","Terra dos ashanti.","Conquista e submissão."],"c":0,"e":"'Gana' era o título do rei; o império ficou conhecido como 'Terra do Ouro' pela riqueza aurífera.","d":1},{"n":26,"tema":"História de África","p":"As principais teorias sobre a partilha de África e a colonização podem ser agrupadas em:","o":["Teoria económica, Teorias psicológicas, Teorias diplomáticas e Teoria da dimensão Africana.","Teorias psicológicas, Teoria de trocas desiguais, Teoria da conquista e Teoria colonial.","Teoria de Darwinismo social, Teoria das resistências e Teoria da Soberania.","Teoria económica, Teorias psicológicas, Teorias diplomáticas, Teoria da dimensão Africana e Teoria da dominação e resistência."],"c":0,"e":"Dúvida: A e D são próximas. Melhor leitura: A, o agrupamento clássico em quatro grandes grupos (económicas, psicológicas, diplomáticas e da dimensão africana).","d":1},{"n":27,"tema":"História de África","p":"No âmbito das estratégias de resistência adoptadas pelas sociedades/estados africanos da África Meridional, o protectorado ou tutela foi a opção dos seguintes estados:","o":["Ndebele, Changanana, Bemba, Yao e Nguni, assim como pelas chefias dos Mangwende, Makoni e Mutasa","Sotho, Swazi, Ngwato, Tswana e Lozi.","Khoi-khoi, Xhosa, Mpondo, Tembu, Mfengu e Hlubi.","Bisa, Lungu, Iwa, Senga, Cewa, Njanja e os Nkonde."],"c":1,"e":"Moshoeshoe (Sotho), Suazis, Khama (Ngwato), Tswana e Lozi aceitaram o protectorado britânico para se protegerem de bóeres e outras potências."},{"n":28,"tema":"História de África","p":"A revolta Maji Maji que se deu no Tanganyika entre 1905 e 1907 teve como líder:","o":["Kinjeketile Ngwale","Abushir","Hassan Bin Omar","Mbunga"],"c":0,"e":"Kinjeketile Ngwale, médium religioso, deu início à revolta contra o domínio alemão."},{"n":29,"tema":"História de África","p":"Em África a Alemanha teve como colónias os seguintes Territórios:","o":["Tanganyika, Quénia, Zanzibar e Namíbia.","Namíbia, Tanganyika, Etiópia e Eritreia.","Togo, Camarões, Namíbia e Tanganyika.","Namíbia, Níger, Djibuti e Marrocos."],"c":2,"e":"As colónias alemãs em África: Togo, Camarões, Sudoeste Africano (Namíbia) e África Oriental Alemã (Tanganyika, Ruanda, Burundi)."},{"n":30,"tema":"História de África","p":"Depois da Primeira guerra Mundial a Alemanha perdeu todas as suas colónias. O Sudoeste africano/Namíbia passou para administração de:","o":["Inglaterra.","França.","Africa do Sul.","SWAPO (Organização do Povo do Sudoeste Africano)."],"c":2,"e":"A Sociedade das Nações confiou o mandato do Sudoeste Africano à União Sul-Africana."},{"n":31,"tema":"História de África","p":"Até ao início da Primeira Guerra Mundial em 1914, apenas dois estados africanos é que haviam escapado da dominação colonial, nomeadamente:","o":["África do Sul e Lesotho","Etiópia e Eritreia","Etiópia e Libéria","Etiópia e Africa do Sul."],"c":2,"e":"Só a Etiópia e a Libéria mantinham independência em 1914."},{"n":32,"tema":"História de África","p":"Nas colónias portuguesas a luta de libertação nacional foi dirigida pelos seguintes movimentos:","o":["FRELIMO, MPLA, PAIGC e ANC.","FNLA, MPLA, UNITA, FRELIMO, MPLA, PAIGC e MLSTP","FRELIMO, MPLA e PAIGC.","FRELIMO, MPLA, PAIGC, FNLA e ZANU FP."],"c":2,"e":"Dúvida: B também lista movimentos das colónias portuguesas, mas repete o MPLA. Melhor leitura: C, os três movimentos da CONCP; A e D incluem organizações de outros países (ANC, ZANU).","d":1},{"n":33,"tema":"História de África","p":"A 25 de Maio de 1963 foi assinada a Acta da Criação da Organização da Unidade Africana cujo primeiro presidente foi:","o":["Kwame Nkrumah","Hailé Selassié","Joseph Arthur Ankrah","Joseph-Desiré Mobuto"],"c":1,"e":"O imperador Hailé Selassié da Etiópia foi o primeiro presidente da OUA, com sede em Adis Abeba."},{"n":34,"tema":"História de África","p":"A Transformação da Organização da Unidade Africana (O.U.A) em União Africana deu-se no ano de:","o":["1980","2002","2010","2015"],"c":1,"e":"A União Africana foi lançada em Durban em Julho de 2002, sucedendo à OUA."},{"n":35,"tema":"História de África","p":"A Namíbia foi o último país da África Austral a tornar-se independente em 21 de Março de","o":["1990","1992","1994","2001"],"c":0,"e":"A Namíbia tornou-se independente a 21 de Março de 1990, com Sam Nujoma presidente; a África do Sul só tem eleições multirraciais em 1994, mas já era soberana."},{"n":36,"tema":"História de Moçambique","p":"Substituindo a comunidade primitiva, vários grupos populacionais foram chegando a Moçambique desde há mais de 1700 anos, povoando gradualmente as bacias fluviais costeiras e os planaltos do interior. As evidências desse povoamento podem encontrar-se nos seguintes locais:","o":["Montanhas de Chinhampere, Estações arqueológicas de Manyikeni e Chibuene.","Estações arqueológicas do vale do Zambeze, do vale do Save, do monte Binga e da serra de Manica.","Grande Zimbabwe, Manyikeni, Mwenemutapa, e Marave.","Estações arqueológicas de Matola, Chongoene, Chibuene, Hola-Hola, Bajone, Mavita e Serra Maua."],"c":3,"e":"Os sítios de Matola, Chongoene, Chibuene, Hola-Hola, Bajone, Mavita e Serra Maúa documentam o povoamento da Idade do Ferro Antiga (séculos III-IV). As outras opções incluem estruturas posteriores ou fora de Moçambique.","d":1},{"n":37,"tema":"História de Moçambique","p":"Na História de Moçambique e em função do produto mais procurado, o período de 1760/70 a 1836/40 corresponde a:","o":["Ciclo de ouro","Ciclo de oleaginosas","Ciclo de escravos","Ciclo de marfim"],"c":2,"e":"O ciclo do ouro e marfim precede esse período; entre c. 1760/70 e 1836/40 dominou o tráfico de escravos."},{"n":38,"tema":"História de Moçambique","p":"Dos Estados satélites de Mwenemutapa, a área de Manyikeni pertencia a:","o":["Quiteve","Barué","Manica","Sedanda"],"c":3,"e":"Dúvida: não consegui confirmar. Melhor leitura: Sedanda, o estado satélite do sul (Sofala/Save), ao qual se associa a região de Manyikeni.","d":1},{"n":39,"tema":"História de Moçambique","p":"O comércio de escravos foi o pilar da economia das seguintes formações politicas:","o":["Estados Militares do Vale do Zambeze e Estados afro-islâmicos da costa.","Prazos do vale do Zambeze, Estados Nguni e Estado de Gaza.","Prazos do vale do Zambeze, Estado de Gaza e Estados Ajaua.","Estados Militares do Vale do Zambeze, Estados Marave e Estado de Mwenemutapa."],"c":2,"e":"Dúvida: B e C são defensáveis. Melhor leitura: C, pois prazos, Gaza e Ajauas (Yao) viveram do tráfico; o Estado de Gaza e os Nguni são o mesmo grupo de estados, redundantes em B.","d":1},{"n":40,"tema":"História de Moçambique","p":"Os principais líderes de resistência no Norte de Moçambique foram:","o":["Kuphula Munu, Nongue Nongue, Cambuemba e Molid Volay.","Mataca, Makanjila, Marave, Maguguana e Mucutu-Munu.","Farlahi, Mataca, Mussa Quanto, Khomala, Kuphula Munu, Molid Volay e Mucu-Munu.","Farlahi, Mataca, Mussa Quanto, Khomala, Kuphula Munu, Nongue Nongue e Cambuemba."],"c":2,"e":"Dúvida: C e D são próximas. Melhor leitura: C, que inclui Molid Volay (Angoche) e Mucu-Munu, ambos associados ao Norte.","d":1},{"n":41,"tema":"História de Moçambique","p":"Para perseguir e capturar Ngungunhane chefe do Estado de Gaza os portugueses usaram como pretexto:","o":["A recusa de Ngungunha em fornecer escravos do seu império.","Os contactos entre Ngungunhane e a British South Africa Company que operava em Manica.","A transferência da capital do Estado de Gaza em 1889 de Mussurize para Mandlakaze que representava um perigo para a dominação colonial portuguesa no sul.","A recusa de Ngungunhane em entregar os chefes revoltosos Mahazule e Nwamatibjana que haviam se refugiado no estado de Gaza."],"c":3,"e":"O pretexto foi a recusa em entregar os régulos revoltosos Maazul e Nwamatibjana, refugiados em Gaza, na guerra de 1895."},{"n":42,"tema":"História de Moçambique","p":"Na greve de 28 Agosto de 1933 (greve da quinhenta) os estivadores do porto de Lourenço Marques exigiam:","o":["O aumento de 0.50 escudos por dia.","O aumento de 0.50 escudos por mês.","A reposição de 0.50 escudos que haviam sido retirados do seu salario diário.","A reposição de 0.50 escudos que haviam sido retirados do seu salario mensal."],"c":2,"e":"Os estivadores exigiam a reposição de 50 centavos retirados do salário diário (daí 'greve da quinhenta'), não um aumento.","d":1},{"n":43,"tema":"História de Moçambique","p":"O Núcleo dos Estudantes Secundários Africanos de Moçambique (NESAM) foi fundado em:","o":["1920","1949","1964","1975"],"c":1,"e":"O NESAM foi criado em 1949 em Lourenço Marques e foi um viveiro de nacionalistas."},{"n":44,"tema":"História de Moçambique","p":"Em 1930 cessaram os privilégios das companhias na colónia de Moçambique, continuando com actividades apenas a:","o":["Companhia do Niassa","Companhia do Zambeze","Companhia de Moçambique","Sociedade agrícola do Madal"],"c":1,"e":"Dúvida: questão pouco clara (a Companhia de Moçambique manteve a concessão até 1942; a do Niassa terminou em 1929). Melhor leitura: B, a Companhia do Zambeze, que perdeu privilégios mas manteve actividade económica.","d":1},{"n":45,"tema":"História de Moçambique","p":"No contexto do trabalho migratório os limites de tempo de contrato para os mineiros moçambicanos no Natal foi fixado pela primeira vez no ano de:","o":["1901","1903","1909","1928"],"c":2,"e":"Dúvida: não consegui confirmar. Melhor leitura: 1909, ano da Convenção entre o Transvaal e Moçambique que regulou a duração dos contratos.","d":1},{"n":46,"tema":"História de Moçambique","p":"A 25 de Junho de 1962 é fundada em Dar-Es-Salam a Frente de Libertação de Moçambique (FRELIMO), a partir da fusão de três movimentos nomeadamente: UDENAMO, MANU e UNAMI. Estes movimentos era liderados respectivamente por:","o":["Adelimo Guambe, Urias Simango e Marcelino dos Santos.","Adelimo Guambe, Mateus Mmole e José Baltazar Chagonga.","Adelimo Guambe Mateus Mmole e Máximo Dias.","Adelimo Guambe, Urias Simango e Fanuel Malhuza."],"c":1,"e":"UDENAMO: Adelino Gwambe; MANU: Mateus Mmole; UNAMI: Baltazar Chagonga. Urias Simango liderava a UDENAMI."},{"n":47,"tema":"História de Moçambique","p":"O decurso e a experiência da luta pela independência em Moçambique despertaram a necessidade de contar com as mulheres no processo. Em Março de 1967, fundou-se o Destacamento Feminino. Antes do Destacamento Feminino existiu uma organização feminina designada por:","o":["LIFEMO.","MULIMO.","OMM.","Mulheres na vanguarda."],"c":0,"e":"A Liga Feminina de Moçambique (LIFEMO) foi criada em 1966; a OMM só surge em 1973."},{"n":48,"tema":"História de Moçambique","p":"A 20 de Setembro de 1974 tomou posse o Governo de Transição em Moçambique tendo Mário Machungo como:","o":["Ministro das Relações Exteriores","Coordenação Económica","Primeiro-ministro","Ministro das Finanças"],"c":1,"e":"Dúvida: não confirmei o cargo exacto. Melhor leitura: B, Machungo foi responsável pela área económica; o primeiro-ministro era Joaquim Chissano.","d":1},{"n":49,"tema":"História de Moçambique","p":"A primeira Constituição de Moçambique independente foi aprovada em:","o":["7 de Setembro de 1974","20 de Setembro de 1974","20 de Junho de 1975","25 de Junho de 1975"],"c":3,"e":"A Constituição foi aprovada e entrou em vigor na proclamação da independência, a 25 de Junho de 1975."},{"n":50,"tema":"História de Moçambique","p":"A Linha da Frente foi a primeira forma de Coordenação e Integração Regional formalmente reconhecida dos países da África Austral, sendo constituída por:","o":["Angola, Botswana, Moçambique, Zimbabwe e Suazilândia.","Angola, Botswana, Malawi, Quénia e Namíbia.","Angola, Botswana, Moçambique, Quénia e Namíbia.","Angola, Botswana, Moçambique, Tanzânia e Zâmbia."],"c":3,"e":"Os Estados da Linha da Frente eram Angola, Botswana, Moçambique, Tanzânia e Zâmbia (depois também o Zimbabwe)."},{"n":51,"tema":"História de Moçambique","p":"A Frente de Libertação de Moçambique (FRELIMO) transformou-se de movimento para partido politico em:","o":["1974","1975","1977","1990"],"c":2,"e":"No III Congresso, em Fevereiro de 1977, a FRELIMO passou a partido marxista-leninista."},{"n":52,"tema":"Cultura Geral","p":"O prémio Nobel da Paz 2018 foi repartido entre:","o":["O ex-Presidente dos EUA Barack Obama e o líder religioso do Tibet Dalai Lama","O Médico Congolês Denis Mukwege e a ex-escrava sexual do Estado Islâmico Nadia Murad.","O ex-secretário geral da ONU Kofi Annan e o ex-Presidente Português Aníbal Cavaco Silva","Os médicos James P. Allison (americano) e Tasuku Honju (japonês)"],"c":1,"e":"Mukwege e Nadia Murad receberam o Nobel da Paz de 2018 pelo combate à violência sexual na guerra. A opção D refere o Nobel da Medicina."},{"n":53,"tema":"Cultura Geral","p":"O vírus do HIV foi descoberto pela primeira vez na década de:","o":["1960","1970","1980","1990"],"c":2,"e":"O HIV foi isolado em 1983 (Institut Pasteur), logo na década de 1980."},{"n":54,"tema":"Cultura Geral","p":"A presidência da SADC é rotativa, sendo actualmente pertencente a:","o":["Cyril Ramaphosa, Presidente da África do Sul","Mokgweetsi Masisi, Presidente do Botswana","Filipe Nyusi, Presidente de Moçambique","Hage Geingob, Presidente da Namíbia."],"c":3,"e":"Dúvida: depende da data. Em 2018-19 a presidência da SADC coube à Namíbia (Geingob); Tanzânia assumiu em Agosto de 2019 e Moçambique em 2020. Melhor leitura: D.","d":1},{"n":55,"tema":"Cultura Geral","p":"Em 2010 a África do Sul tornou-se no primeiro país africano a organizar uma competição mundial em futebol. Esta competição decorreu entre:","o":["11 de Julho a 11 de Julho","14 de Junho a 15 de Julho","11 de Julho a 11 de Agosto","25 de Junho a 25 de Julho"],"c":0,"e":"O Mundial 2010 decorreu de 11 de Junho a 11 de Julho. A opção A tem erro de impressão ('Julho' em vez de 'Junho') mas é a mais próxima.","d":1}]},{"id":"his-ensaio-a","subj":"his","titulo":"Ensaio A de História · Completar espaços","inst":"A PEN Aulas","ano":2025,"q":[{"n":1,"tema":"Organizações e datas-chave","p":"A Sociedade de Geografia de Lisboa surge no ano _____.","r":"1875","e":"Fundada em 1875, impulsionou a exploração e a ocupação científica e política de África por Portugal."},{"n":2,"tema":"Nomes actuais","p":"O nome actual do antigo Sudoeste Africano é _____.","r":"Namíbia","e":"Antiga colónia alemã, passou à administração da África do Sul após a 1ª GM e tornou-se independente em 1990."},{"n":3,"tema":"Organizações e datas-chave","p":"A África Ocidental Francesa (AOF) surge no ano _____.","r":"1895","e":"Federação das colónias francesas da África Ocidental, com capital em Dacar (Senegal)."},{"n":4,"tema":"Organizações e datas-chave","p":"A África Equatorial Francesa (AEF) surge no ano _____.","r":"1910","e":"Federação de colónias francesas da África Central (Gabão, Congo, Ubangui-Chari e Chade), com capital em Brazzaville."},{"n":5,"tema":"Organizações e datas-chave","p":"O dia do continente africano é _____.","r":"25 de Maio","e":"Comemora a fundação da OUA em 25 de Maio de 1963."},{"n":6,"tema":"Organizações e datas-chave","p":"O ano do continente africano é o ano _____.","r":"1960","e":"Em 1960 tornaram-se independentes 17 países, a maioria antigas colónias francesas."},{"n":7,"tema":"Organizações e datas-chave","p":"A lei-quadro foi publicada em _____.","r":"1956","e":"A loi-cadre (Lei Defferre) de 1956 deu maior autonomia interna às colónias francesas."},{"n":8,"tema":"Organizações e datas-chave","p":"A Comunidade Francesa (CF) surge em _____.","r":"1958","e":"Criada pela Constituição de De Gaulle (1958); só a Guiné recusou e ficou independente nesse ano."},{"n":9,"tema":"Resistência e Pan-africanismo","p":"A Batalha de Adua foi em _____.","r":"1896","e":"A 1 de Março de 1896, o exército etíope de Menelik II venceu os italianos."},{"n":10,"tema":"Resistência e Pan-africanismo","p":"Na Batalha de Adua, a Etiópia derrotou a _____.","r":"Itália","e":"A vitória sobre a Itália garantiu a independência da Etiópia (até à invasão italiana de 1935-36)."},{"n":11,"tema":"Resistência e Pan-africanismo","p":"Em 1914, a _____ e a _____ continuavam livres e independentes.","r":"Etiópia · Libéria","e":"Eram os dois únicos Estados africanos não colonizados em 1914."},{"n":12,"tema":"Independências e luta","p":"Os colonos da _____ proclamaram a sua independência unilateral em 1965.","r":"Rodésia do Sul","e":"A minoria branca de Ian Smith declarou a UDI em 1965; o país só ficou independente como Zimbabwe, em 1980."},{"n":13,"tema":"Resistência e Pan-africanismo","p":"O 1º congresso _____ foi realizado na cidade francesa de _____, no ano de 1919.","r":"Pan-Africano · Paris","e":"Organizado por W. E. B. Du Bois, coincidiu com a Conferência de Paz do pós-1ª GM."},{"n":14,"tema":"Resistência e Pan-africanismo","p":"O 5º congresso _____ foi realizado na cidade inglesa de _____.","r":"Pan-Africano · Manchester","e":"Realizou-se em 1945 e foi marcado pela presença de Nkrumah e Kenyatta; defendeu a independência africana."},{"n":15,"tema":"Partilha e colónias","p":"Uma das colónias da Alemanha antes de 1914 foi _____.","r":"Togo (também Camarões, Tanganica, Sudoeste Africano)","e":"Qualquer destas serve: Togo, Camarões, Tanganica (actual Tanzânia continental), Sudoeste Africano (Namíbia) ou Ruanda-Urundi."},{"n":16,"tema":"Nomes actuais","p":"O nome actual da Bechuanalândia é _____.","r":"Botswana","e":"Protectorado britânico que se tornou independente em 1966."},{"n":17,"tema":"Nomes actuais","p":"O nome actual da Basutolândia é _____.","r":"Lesoto","e":"Protectorado britânico, independente em 1966."},{"n":18,"tema":"Organizações e datas-chave","p":"A OUA surge no ano _____.","r":"1963","e":"Fundada em Adis Abeba, a 25 de Maio de 1963."},{"n":19,"tema":"Organizações e datas-chave","p":"A OUA teve como primeiro presidente: _____.","r":"Haile Selassie","e":"Imperador da Etiópia, presidiu à primeira Assembleia (1963); o primeiro secretário-geral foi Diallo Telli (Guiné)."},{"n":20,"tema":"Organizações e datas-chave","p":"A UA é oficialmente criada na cimeira de _____, realizada em 2022.","r":"Durban","e":"A UA foi criada na cimeira de Durban (África do Sul) em 2002, não em 2022: o enunciado tem gralha no ano. Substituiu a OUA.","d":1},{"n":21,"tema":"Independências por data","p":"Ficou independente a 06/3/1957: o _____.","r":"Gana","e":"Primeira colónia da África subsariana a ficar independente, sob Kwame Nkrumah (antiga Costa do Ouro)."},{"n":22,"tema":"Independências por data","p":"Ficou independente a 02/10/1958: a _____.","r":"Guiné (Conacri)","e":"Votou «Não» à Comunidade Francesa e Sékou Touré proclamou a independência."},{"n":23,"tema":"Independências por data","p":"Ficaram independentes em 1956: _____ e _____.","r":"Marrocos · Tunísia","e":"Em 1956 tornaram-se também independentes o Sudão (1 de Janeiro), Marrocos e a Tunísia. Como são duas lacunas, assume-se Marrocos e Tunísia (antigos protectorados franceses); o Sudão seria igualmente válido.","d":1},{"n":24,"tema":"Independências por data","p":"Ficou independente a 01/10/1960: a _____.","r":"Nigéria","e":"Antiga colónia britânica, independente em 1960 (ano de África)."},{"n":25,"tema":"Independências por data","p":"Iniciou a sua luta armada em 1954: a _____.","r":"Argélia","e":"A FLN iniciou a luta armada a 1 de Novembro de 1954."},{"n":26,"tema":"Independências por data","p":"Ficou independente a 06/7/1964: o _____.","r":"Malawi","e":"Antiga Niassalândia, britânica; independente em 1964 com Hastings Banda."},{"n":27,"tema":"Independências por data","p":"Ficou independente a 24/10/1964: a _____.","r":"Zâmbia","e":"Antiga Rodésia do Norte, britânica; primeiro presidente Kenneth Kaunda."},{"n":28,"tema":"Independências por data","p":"Ficou independente a 30/9/1966: o _____.","r":"Botswana","e":"Antiga Bechuanalândia; primeiro presidente Seretse Khama."},{"n":29,"tema":"Independências por data","p":"Ficou independente a 04/10/1966: o _____.","r":"Lesoto","e":"Antiga Basutolândia, britânica."},{"n":30,"tema":"Independências por data","p":"Ficou independente a 03/7/1962: a _____.","r":"Argélia","e":"Depois de uma guerra de libertação (1954-62) contra a França, na sequência dos Acordos de Évian."},{"n":31,"tema":"Organizações e datas-chave","p":"A SADCC, comunidade regional, surge no ano _____, ano de independência do _____.","r":"1980 · Zimbabwe","e":"A SADCC (1980) visava reduzir a dependência económica face à África do Sul do apartheid; deu origem à SADC em 1992."},{"n":32,"tema":"Organizações e datas-chave","p":"A Linha da Frente surge no ano _____.","r":"1970","e":"Grupo de Estados vizinhos da África do Sul e da Rodésia (Tanzânia, Zâmbia, Botswana, depois Angola e Moçambique) de apoio à libertação da África Austral. Alguns manuais datam-no de meados dos anos 70, daí a dúvida.","d":1},{"n":33,"tema":"Organizações e datas-chave","p":"O ANC, partido sul-africano, surge no ano _____.","r":"1912","e":"Fundado como South African Native National Congress, em Bloemfontein."},{"n":34,"tema":"Exploração europeia","p":"_____ foi um missionário inglês que perdeu a vida em 1873.","r":"David Livingstone","e":"Explorador e missionário (de origem escocesa), morreu em 1873 na actual Zâmbia."},{"n":35,"tema":"Exploração europeia","p":"_____ e _____ encontraram-se em Novembro de 1871.","r":"Livingstone · Stanley","e":"Encontro em Ujiji, junto ao lago Tanganica; Stanley foi enviado pelo New York Herald."},{"n":36,"tema":"Exploração europeia","p":"Capelo e _____ partiram de Angola a Moçambique em 1877.","r":"Ivens","e":"Hermenegildo Capelo e Roberto Ivens, exploradores portugueses; a travessia Angola-Contra-Costa concluiu-se em 1884-85."},{"n":37,"tema":"Nomes actuais","p":"O nome actual da antiga Costa do Ouro: _____.","r":"Gana","e":"Nome adoptado na independência, em 1957."},{"n":38,"tema":"Nomes actuais","p":"O nome actual do antigo Alto Volta: _____.","r":"Burkina Faso","e":"Mudou de nome em 1984, sob Thomas Sankara."},{"n":39,"tema":"Nomes actuais","p":"O nome actual da antiga Rodésia do Norte: _____.","r":"Zâmbia","e":"Independente em 1964."},{"n":40,"tema":"Nomes actuais","p":"O nome actual da Niassalândia: _____.","r":"Malawi","e":"Independente em 1964."},{"n":41,"tema":"Partilha e colónias","p":"Portugal e Inglaterra assinaram o _____ a 26 de Fevereiro de 1884.","r":"Tratado do Zaire (Tratado do Congo)","e":"Reconhecia a soberania portuguesa na foz do Zaire; contribuiu para a convocação da Conferência de Berlim."},{"n":42,"tema":"África do Sul","p":"A 21/3/1960 tivemos, na vizinha África do Sul, o Massacre de _____.","r":"Sharpeville","e":"A polícia matou dezenas de manifestantes contra as leis do passe."},{"n":43,"tema":"África do Sul","p":"A 16/6/1976 tivemos, na vizinha África do Sul, o Massacre de _____.","r":"Soweto","e":"Revolta de estudantes contra o ensino obrigatório em africâner."},{"n":44,"tema":"Nacionalistas e movimentos","p":"_____ foi um nacionalista do Senegal.","r":"Léopold Sédar Senghor","e":"Poeta, líder do BDS e primeiro presidente do Senegal independente (1960)."},{"n":45,"tema":"Nacionalistas e movimentos","p":"_____ foi um nacionalista do Gana.","r":"Kwame Nkrumah","e":"Líder do CPP e primeiro chefe de governo/presidente do Gana independente."},{"n":46,"tema":"Nacionalistas e movimentos","p":"_____ foi um nacionalista da Argélia.","r":"Ahmed Ben Bella","e":"Dirigente da FLN e primeiro presidente da Argélia independente. Também válidos: Ferhat Abbas, Messali Hadj."},{"n":47,"tema":"Nacionalistas e movimentos","p":"_____ foi um nacionalista de Angola.","r":"Agostinho Neto","e":"Líder do MPLA e primeiro presidente de Angola. Também válidos: Holden Roberto, Jonas Savimbi."},{"n":48,"tema":"Nacionalistas e movimentos","p":"CPP foi um movimento do _____.","r":"Gana","e":"Convention People's Party (Partido da Convenção do Povo), fundado por Nkrumah em 1949."},{"n":49,"tema":"Nacionalistas e movimentos","p":"BDS foi um movimento do _____.","r":"Senegal","e":"Bloco Democrático Senegalês, fundado por Senghor em 1948."},{"n":50,"tema":"Nacionalistas e movimentos","p":"FLN foi um movimento da _____.","r":"Argélia","e":"Frente de Libertação Nacional, que conduziu a guerra de independência (1954-62)."}]},{"id":"his-ensaio-b","subj":"his","titulo":"Ensaio B de História · Verdadeiro ou Falso","inst":"A PEN Aulas","ano":2025,"q":[{"n":1,"tema":"Partilha e ocupação","p":"A Conferência de Lisboa foi fundamental para que se ocupasse o continente africano.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. Foi a Conferência de Berlim (1884-85) que fixou as regras da ocupação efectiva de África."},{"n":2,"tema":"Partilha e ocupação","p":"Os africanos foram consultados no processo de conquista dos territórios africanos.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. Os africanos não foram consultados; a partilha foi decidida pelas potências europeias."},{"n":3,"tema":"Colónias e potências","p":"A Inglaterra foi a potência com mais colónias em África.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro, em número de colónias (a Grã-Bretanha teve o maior número de territórios). Em extensão territorial, a França era a maior. A dúvida está no critério.","d":1},{"n":4,"tema":"Colónias e potências","p":"A Etiópia manteve-se independente pelo menos antes de 1914.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. A Etiópia (e a Libéria) eram livres em 1914; a Itália só a ocupou em 1935-36."},{"n":5,"tema":"Colónias e potências","p":"A Libéria pertencia à Sociedade Americana Colonizadora (SAC), formada em 1822.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro quanto ao essencial: a Libéria foi fundada por ex-escravos norte-americanos enviados pela Sociedade Americana de Colonização. Rigorosamente, a sociedade foi criada em 1816-17 e 1822 é o ano de fundação de Monróvia/colonização; o gabarito provável é V.","d":1},{"n":6,"tema":"Colónias e potências","p":"A Libéria nunca foi ocupada pelos colonizadores.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Nunca foi colonizada por uma potência europeia (independente em 1847)."},{"n":7,"tema":"Colónias e potências","p":"O Togo foi inicialmente ocupado pela Alemanha.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. O Togo foi colónia alemã (Togoland) a partir de 1884."},{"n":8,"tema":"Colónias e potências","p":"A Tanzânia foi inicialmente ocupada pela Alemanha.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Tanganica fez parte da África Oriental Alemã."},{"n":9,"tema":"Colónias e potências","p":"O antigo Sudoeste Africano foi inicialmente ocupado pela Alemanha.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Actual Namíbia, colónia alemã desde 1884."},{"n":10,"tema":"Colónias e potências","p":"A antiga Rodésia do Sul foi ocupada pela Inglaterra.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Actual Zimbabwe, ocupada pela British South Africa Company de Cecil Rhodes."},{"n":11,"tema":"Colónias e potências","p":"A antiga Rodésia do Norte foi ocupada pela Inglaterra.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Actual Zâmbia, território britânico."},{"n":12,"tema":"Colónias e potências","p":"A antiga Niassalândia foi ocupada pela Inglaterra.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Actual Malawi, protectorado britânico."},{"n":13,"tema":"Colónias e potências","p":"O Senegal foi ocupado pela Inglaterra.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. O Senegal foi colónia francesa (AOF)."},{"n":14,"tema":"Colónias e potências","p":"A Mauritânia foi ocupada pela Inglaterra.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. A Mauritânia foi colónia francesa (AOF)."},{"n":15,"tema":"Mapa cor-de-rosa","p":"Portugal desenhou, em 1887, o mapa cor-de-rosa.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Em 1886-87 Portugal apresentou o mapa cor-de-rosa, ligando Angola a Moçambique."},{"n":16,"tema":"Mapa cor-de-rosa","p":"O mapa criou conflitos com a Alemanha.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. O conflito foi com o Reino Unido, que queria ligar o Cabo ao Cairo."},{"n":17,"tema":"Mapa cor-de-rosa","p":"A Alemanha deu um ultimato de 48 horas a Portugal em 1890.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. O Ultimato de 11 de Janeiro de 1890 foi dado pelo Reino Unido, não pela Alemanha."},{"n":18,"tema":"Mapa cor-de-rosa","p":"O mapa cor-de-rosa pretendia ligar Moçambique a Angola.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Pretendia unir Angola e Moçambique por um território contínuo."},{"n":19,"tema":"Mapa cor-de-rosa","p":"A Alemanha pretendia, por outro lado, ligar Cabo ao Cairo.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. Quem pretendia ligar o Cabo ao Cairo era o Reino Unido."},{"n":20,"tema":"Colónias e potências","p":"A Argélia foi colonizada pela Itália.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. A Argélia foi colonizada pela França (desde 1830)."},{"n":21,"tema":"Independências","p":"1960 é o ano de África.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Em 1960 17 países africanos ficaram independentes."},{"n":22,"tema":"Independências","p":"Gana proclamou a independência em 1957.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. A 6 de Março de 1957, sob Nkrumah."},{"n":23,"tema":"Nacionalistas e movimentos","p":"O movimento que conduziu o povo do Gana à independência é UGCC.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. Foi o CPP (Convention People's Party) de Nkrumah; a UGCC, anterior (1947), era mais moderada e Nkrumah saiu para fundar o CPP."},{"n":24,"tema":"Independências","p":"Marrocos proclamou a independência em 1954.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. Marrocos tornou-se independente em 1956."},{"n":25,"tema":"Independências","p":"Mandela ficou preso por 27 anos.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Preso de 1962/64 a 1990."},{"n":26,"tema":"Independências","p":"Mandela foi o primeiro presidente negro da África do Sul.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Eleito em 1994."},{"n":27,"tema":"Independências","p":"Mandela ganhou o Prémio Nobel de Paz em 1993.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Partilhou o prémio com F. W. de Klerk em 1993."},{"n":28,"tema":"Independências","p":"A Argélia ficou independente em 1965.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. A Argélia ficou independente em 1962."},{"n":29,"tema":"Mandatos e 1ª GM","p":"A Alemanha perdeu todas as colónias africanas depois da 1ª GM.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Foram transferidas para a Sociedade das Nações e entregues como mandatos."},{"n":30,"tema":"Mandatos e 1ª GM","p":"O Togo passou para o controlo da França depois da 1ª GM.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro (em parte): o Togo foi repartido, ficando a maior parte (a leste) sob mandato francês e uma faixa a oeste sob mandato britânico.","d":1},{"n":31,"tema":"Mandatos e 1ª GM","p":"A Tanzânia passou para o controlo da França depois da 1ª GM.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. Tanganica passou para o Reino Unido."},{"n":32,"tema":"Colónias e potências","p":"A África Ocidental Francesa (AOF) surge em 1895.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Criada em 1895, com capital em Dacar."},{"n":33,"tema":"Colónias e potências","p":"A Mauritânia e o Senegal faziam parte da África Ocidental Francesa (AOF).","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Ambos integravam a AOF."},{"n":34,"tema":"Mandatos e 1ª GM","p":"O Tratado de Versalhes instituiu o sistema de mandatos.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. O Tratado de Versalhes (1919) e o Pacto da SDN criaram os mandatos para as ex-colónias alemãs e otomanas."},{"n":35,"tema":"Mandatos e 1ª GM","p":"As colónias da Alemanha passaram a ser administradas por França e Inglaterra.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro no essencial. Também a Bélgica (Ruanda-Urundi) e a União Sul-Africana (Sudoeste Africano) receberam mandatos."},{"n":36,"tema":"Independências","p":"A maior parte das colónias independentes em 1960 eram inglesas.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. A maioria das colónias independentes em 1960 era francesa."},{"n":37,"tema":"Colónias e potências","p":"A cidade do Cabo é uma cidade sul-africana descoberta pelos holandeses em 1652.","o":["Verdadeiro","Falso"],"c":0,"e":"Os holandeses (Jan van Riebeeck, Companhia das Índias Orientais) fundaram a Cidade do Cabo em 1652; foi descoberta pelos portugueses (Bartolomeu Dias, 1488). Assume-se V pela data e fundação holandesa, mas «descoberta» é rigorosamente incorrecto.","d":1},{"n":38,"tema":"Independências","p":"Botswana, da zona austral de África, proclamou a independência em 1966.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. 30 de Setembro de 1966."},{"n":39,"tema":"Colónias e potências","p":"Bechuanalândia era o nome do actual Lesoto.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. A Bechuanalândia é o actual Botswana; o Lesoto era a Basutolândia."},{"n":40,"tema":"Colónias e potências","p":"A África Equatorial Francesa (AEF) surge em 1910.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Criada em 1910, com capital em Brazzaville."},{"n":41,"tema":"Independências","p":"A primeira república africana negra foi a Libéria, independente em 1847.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Proclamada a 26 de Julho de 1847."},{"n":42,"tema":"Independências","p":"A UA celebra o dia de África, todos os anos, a 25 de Maio.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Marca a fundação da OUA em 1963."},{"n":43,"tema":"Independências","p":"Argélia, Moçambique, Angola e Gana obtiveram as independências por via armada.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. O Gana obteve a independência por via pacífica (negociação, acção política)."},{"n":44,"tema":"Independências","p":"Gana, Senegal e Uganda obtiveram as independências por via armada.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. Os três obtiveram-na por via pacífica."},{"n":45,"tema":"Independências","p":"A ONU nunca teve um secretário-geral africano.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. Boutros Boutros-Ghali (Egipto, 1992-96) e Kofi Annan (Gana, 1997-2006)."},{"n":46,"tema":"Partilha e ocupação","p":"O Tratado de Zaire foi assinado em 1884.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Tratado do Zaire (Anglo-Português), 26 de Fevereiro de 1884."},{"n":47,"tema":"Nacionalistas e movimentos","p":"Lumumba é um nacionalista do Gana.","o":["Verdadeiro","Falso"],"c":1,"e":"Falso. Patrice Lumumba foi nacionalista do Congo (Belga, actual RDC)."},{"n":48,"tema":"Nacionalistas e movimentos","p":"Agostinho Neto é um nacionalista de Angola.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Líder do MPLA e primeiro presidente de Angola."},{"n":49,"tema":"Nacionalistas e movimentos","p":"FLN foi um movimento independentista da Argélia.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. Frente de Libertação Nacional (1954)."},{"n":50,"tema":"Nacionalistas e movimentos","p":"UNIP é um movimento independentista da Zâmbia.","o":["Verdadeiro","Falso"],"c":0,"e":"Verdadeiro. United National Independence Party, de Kenneth Kaunda."}]},{"id":"his-ficha-2025-08","subj":"his","titulo":"Ficha de exercício de História","inst":"Turma dos revoltados · Prof.ª A. Muchundze","ano":2025,"q":[{"n":1,"tema":"Descolonização e nacionalismos em África","p":"A Namíbia sofreu uma dupla ocupação alemã e inglesa, tornou-se independente no dia:","o":["22/04/1976","21/03/1990","22/05/1987","13/05/1990","18/04/1980"],"c":1,"e":"A Namíbia, antiga colónia alemã e depois administrada pela África do Sul, tornou-se independente a 21 de Março de 1990, sob a liderança da SWAPO."},{"n":2,"tema":"Descolonização e nacionalismos em África","p":"O Movimento Nacional Congolês (MNC) tornou o seu país independente no dia:","o":["06/03/1957","02/10/1958","01/10/1960","06/07/1964","24/10/1964"],"c":2,"e":"O Congo (MNC de Lumumba) tornou-se independente a 30/06/1960, data que não consta das opções. Dúvida: a melhor leitura é a opção de 1960 (01/10/1960), a única do ano certo, mas está provavelmente errada ou mal transcrita.","d":1},{"n":3,"tema":"Descolonização e nacionalismos em África","p":"A Nigéria tornou-se independente no ano de:","o":["1958","1960","1961","1865","1968"],"c":1,"e":"A Nigéria proclamou a independência a 1 de Outubro de 1960."},{"n":4,"tema":"Descolonização e nacionalismos em África","p":"A Somália esteve sucessivamente sob o domínio:","o":["Italiano, Britânico e Francês","Britânico, Francês e Italiano","Italiano, Francês e Britânico","Francês, Italiano e Britânico","Português, Britânico e Italiano"],"c":0,"e":"A Somália foi repartida entre Itália, Grã-Bretanha e França (Somália Italiana, Britânica e Francesa). Dúvida: a ordem de domínio é pouco clara; a melhor leitura é a opção A, a única com as três potências correctas na ordem habitual dos manuais.","d":1},{"n":5,"tema":"Descolonização e nacionalismos em África","p":"O primeiro país da África ao Sul do Sahara a alcançar a independência foi:","o":["Gana","Tanzânia","Guiné-Conacri","Libéria","Senegal"],"c":0,"e":"O Gana (Costa do Ouro), liderado por Kwame Nkrumah, foi independente em 6 de Março de 1957, o primeiro da África Subsariana colonial."},{"n":6,"tema":"Descolonização e nacionalismos em África","p":"Na História da descolonização do continente africano, existem países que alcançaram as suas independências no mesmo ano. Por exemplo, países como Mali, Camarões, Chade, Senegal, Costa do Marfim, Gabão, Togo e Níger tornaram-se independentes no ano de:","o":["1940","1958","1960","1963","1975"],"c":2,"e":"1960 ficou conhecido como o 'Ano de África': cerca de 17 países, sobretudo da África Francesa, tornaram-se independentes."},{"n":7,"tema":"Descolonização e nacionalismos em África","p":"O último país da África Austral a tornar-se independente foi:","o":["Zimbábue","Madagáscar","Namíbia","Lesotho","Suazilândia"],"c":2,"e":"A Namíbia independentizou-se em 1990, depois do Zimbábue (1980) e de Moçambique e Angola (1975)."},{"n":8,"tema":"Descolonização e nacionalismos em África","p":"Embora a sua principal marca tenha sido a administração directa, os franceses aplicaram, nalguns casos, o sistema de administração indirecta em África. Como exemplo de território onde a França aplicou o sistema de administração indirecta pode-se citar o caso:","o":["Do Marrocos","Da Argélia","Do Senegal","Da Costa do Marfim","Do Madagáscar"],"c":0,"e":"Em Marrocos (e na Tunísia), protectorados, a França governou através das autoridades locais (sultão), isto é, administração indirecta. Argélia, Senegal e Madagáscar foram de administração directa/assimilação."},{"n":9,"tema":"Descolonização e nacionalismos em África","p":"O país da África Austral que se tornou independente a 4 de Outubro de 1966 e que teve como primeiros líderes Leabua Jonathan (chefe do governo) e o rei Mashoeshoe II (chefe de Estado) foi:","o":["Lesotho","Suazilândia","Botswana","Namíbia","Malawi"],"c":0,"e":"O Lesotho (antiga Basutolândia) tornou-se independente a 4 de Outubro de 1966."},{"n":11,"tema":"Descolonização e nacionalismos em África","p":"\"Umkhonto we Sizwe\" foi o braço armado do seguinte movimento de libertação:","o":["ZAPU","TANU","SWAPO","ANC","Chama cha Mapinduzi"],"c":3,"e":"Umkhonto we Sizwe ('Lança da Nação') foi criado em 1961 pelo ANC, na África do Sul."},{"n":12,"tema":"Descolonização e nacionalismos em África","p":"A \"South West African People's Organization (SWAPO)\" foi o movimento que lutou pela libertação do povo de:","o":["Marrocos","Mauritânia","Botswana","Lesoto","Namíbia"],"c":4,"e":"A SWAPO lutou pela independência da Namíbia (Sudoeste Africano)."},{"n":13,"tema":"Descolonização e nacionalismos em África","p":"Samuel Maherero, Menelik II, Abushiri e Dingane foram de:","o":["Namíbia, Etiópia, Tanzânia e África do Sul","Namíbia, Etiópia, Zimbábue e África do Sul","Namíbia, Etiópia, Egipto e África do Sul","Namíbia, Etiópia, Líbia e África do Sul","Namíbia, Etiópia, Argélia e África do Sul"],"c":0,"e":"Maherero (hereros, Namíbia), Menelik II (Etiópia), Abushiri (resistência na costa da Tanzânia) e Dingane (zulus, África do Sul)."},{"n":14,"tema":"Descolonização e nacionalismos em África","p":"Lat Dior lutou contra o colonialismo europeu do século XIX. Liderou a resistência em:","o":["Costa do Marfim","Senegal","Gana","África do Sul","Marrocos"],"c":1,"e":"Lat Dior Diop foi damel de Cayor, no Senegal, e resistiu à penetração francesa."},{"n":15,"tema":"Descolonização e nacionalismos em África","p":"O ANC surgiu em:","o":["1908","1912","1913","1914","1910"],"c":1,"e":"O South African Native National Congress, depois ANC, foi fundado em 1912 em Bloemfontein."},{"n":16,"tema":"Descolonização e nacionalismos em África","p":"O Zimbabwe proclamou a sua independência no ano:","o":["1975","1976","1980","1990","1960"],"c":2,"e":"O Zimbábue tornou-se independente a 18 de Abril de 1980."},{"n":16,"tema":"Descolonização e nacionalismos em África","p":"O Malawi proclamou a sua independência no ano:","o":["1962","1964","1966","1968","1965"],"c":1,"e":"O Malawi (Niassalândia) tornou-se independente a 6 de Julho de 1964."},{"n":17,"tema":"Descolonização e nacionalismos em África","p":"Kwame Nkrumah liderou o nacionalismo de:","o":["Senegal","Nigéria","Gana","Marrocos","Argélia"],"c":2,"e":"Nkrumah liderou o CPP e levou o Gana à independência em 1957."},{"n":18,"tema":"Descolonização e nacionalismos em África","p":"Proclamou a independência em 1965:","o":["Serra Leoa","Gâmbia","Gana","Nigéria","Marrocos"],"c":1,"e":"A Gâmbia tornou-se independente em 18 de Fevereiro de 1965."},{"n":19,"tema":"Descolonização e nacionalismos em África","p":"Patrice Lumumba é um nacionalista de:","o":["Congo","Chade","Togo","Mauritânia","Argélia"],"c":0,"e":"Lumumba, líder do MNC, foi o primeiro-ministro do Congo independente em 1960."},{"n":20,"tema":"Descolonização e nacionalismos em África","p":"Proclamou a independência em 1961:","o":["Gana","Nigéria","Serra Leoa","Gâmbia","Zimbábue"],"c":2,"e":"A Serra Leoa tornou-se independente em 27 de Abril de 1961."},{"n":21,"tema":"Descolonização e nacionalismos em África","p":"Marrocos proclamou a independência em:","o":["1955","1956","1957","1958","1960"],"c":1,"e":"Marrocos obteve a independência da França em 1956 (2 de Março)."},{"n":22,"tema":"Descolonização e nacionalismos em África","p":"Proclamou a independência a 1 de Outubro de 1960:","o":["Costa do Marfim","Senegal","Gana","Nigéria","Marrocos"],"c":3,"e":"A Nigéria tornou-se independente a 1 de Outubro de 1960."},{"n":22,"tema":"Descolonização e nacionalismos em África","p":"Proclamou a sua independência no dia 24 de Outubro de 1964:","o":["Malawi","Zâmbia","Botswana","Zimbábue","Serra Leoa"],"c":1,"e":"A Zâmbia (Rodésia do Norte), liderada por Kenneth Kaunda, tornou-se independente a 24 de Outubro de 1964."},{"n":23,"tema":"Descolonização e nacionalismos em África","p":"Nelson Mandela ficou preso por:","o":["24 anos","25 anos","26 anos","27 anos","28 anos"],"c":3,"e":"Mandela esteve preso 27 anos (1962-1990)."},{"n":24,"tema":"Descolonização e nacionalismos em África","p":"O Movimento Nacionalista Congolês (MNC) foi liderado por:","o":["Julius Nyerere","Kenneth Kaunda","Kwame Nkrumah","Modibo Keita","Patrice Lumumba"],"c":4,"e":"O MNC foi fundado e liderado por Patrice Lumumba."},{"n":25,"tema":"Descolonização e nacionalismos em África","p":"A independência económica dos territórios da África Austral passava por reduzir a sua dependência relativamente à África do Sul e ao Ocidente. O organismo regional criado para o efeito foi:","o":["Linha da Frente","CEDEAO","SADC","SADCC","ANC"],"c":3,"e":"A SADCC (Conferência de Coordenação para o Desenvolvimento da África Austral) foi criada em 1980 em Lusaka; a SADC só surgiu em 1992."},{"n":26,"tema":"Descolonização e nacionalismos em África","p":"Em termos cronológicos, a descolonização da África Ocidental Britânica processou-se na seguinte ordem:","o":["Gana, Nigéria, Serra Leoa e Gâmbia","Gâmbia, Nigéria, Serra Leoa e Gana","Gana, Nigéria, Gâmbia e Serra Leoa","Gana, Gâmbia, Serra Leoa e Nigéria","Gana, Serra Leoa, Gâmbia e Nigéria"],"c":0,"e":"Gana (1957), Nigéria (1960), Serra Leoa (1961) e Gâmbia (1965)."},{"n":27,"tema":"Descolonização e nacionalismos em África","p":"O Gana é da África Ocidental, o qual foi colonizado por:","o":["Bélgica","França","Inglaterra","Alemanha","Itália"],"c":2,"e":"O Gana (Costa do Ouro) foi colónia britânica. Dúvida: no original a opção C está em falta (só A, B, D, E); reconstruiu-se 'Inglaterra' como opção C, por ser a única resposta correcta.","d":1},{"n":28,"tema":"Descolonização e nacionalismos em África","p":"A Argélia é da África do Norte, o qual foi colonizado por:","o":["Inglaterra","Portugal","Alemanha","Bélgica","França"],"c":4,"e":"A Argélia foi colónia francesa desde 1830 até 1962."},{"n":29,"tema":"Descolonização e nacionalismos em África","p":"Moçambique é da África Austral, o qual teve como movimento na luta pela independência:","o":["MANU","UDENAMO","UNAMI","FRELIMO","RENAMO"],"c":3,"e":"A FRELIMO, fundada em 1962 (fusão de MANU, UDENAMO e UNAMI), conduziu a luta armada de libertação nacional."},{"n":30,"tema":"Descolonização e nacionalismos em África","p":"Angola é da África Austral, a sua luta pela independência nacional foi desencadeada por:","o":["UNITA","FNLA","MPLA","PAIGC","UDENAMO"],"c":2,"e":"A luta armada angolana foi iniciada pelo MPLA em 4 de Fevereiro de 1961. Dúvida possível: a FNLA iniciou acções em Março de 1961, mas a data de referência é do MPLA."},{"n":31,"tema":"Descolonização e nacionalismos em África","p":"O antigo Sudoeste Africano é da África Austral, a sua luta pela independência nacional foi conduzida por:","o":["PCP","UGCC","FLN","SWAPO"],"c":3,"e":"A SWAPO conduziu a luta pela independência da Namíbia."},{"n":32,"tema":"Descolonização e nacionalismos em África","p":"O MPLA foi liderado por:","o":["Nelson Mandela","Agostinho Neto","Nino Vieira","Samora Machel","Eduardo Mondlane"],"c":1,"e":"Agostinho Neto foi o líder do MPLA e primeiro presidente de Angola."},{"n":33,"tema":"Descolonização e nacionalismos em África","p":"Léopold Sédar Senghor foi um nacionalista de:","o":["Nigéria","Senegal","Costa do Marfim","Angola"],"c":1,"e":"Senghor foi poeta, nacionalista e primeiro presidente do Senegal independente (1960)."},{"n":34,"tema":"Descolonização e nacionalismos em África","p":"O CPP é um movimento de:","o":["Gana","Congo","Argélia","Senegal","Marrocos"],"c":0,"e":"O Convention People's Party (CPP) foi o partido de Nkrumah, no Gana."},{"n":35,"tema":"Descolonização e nacionalismos em África","p":"Kenneth David Kaunda foi um nacionalista da África:","o":["Central","Austral","Ocidental","Oriental"],"c":1,"e":"Kaunda liderou a independência da Zâmbia, país da África Austral. Dúvida possível: alguns autores situam a Zâmbia na África Central."},{"n":36,"tema":"Descolonização e nacionalismos em África","p":"A Guiné (Conacri) proclamou a sua independência em:","o":["2 de Outubro de 1958","1 de Outubro de 1958","2 de Outubro de 1959","3 de Outubro de 1960","5 de Outubro de 1958"],"c":0,"e":"A Guiné de Sékou Touré disse 'não' à Comunidade Francesa e proclamou a independência a 2 de Outubro de 1958."},{"n":37,"tema":"Descolonização e nacionalismos em África","p":"O organismo fundado a 17 de Agosto de 1992 foi:","o":["SADCC","SADC","CPLP","ANC","Linha da Frente"],"c":1,"e":"A SADC substituiu a SADCC pelo Tratado de Windhoek, a 17 de Agosto de 1992."},{"n":38,"tema":"Descolonização e nacionalismos em África","p":"Na Gâmbia, antiga colónia britânica da África Ocidental, o processo de descolonização foi dirigido pelo People's Progressive Party (PPP), dirigido por Dawda Jawara. Antes de adoptar esse nome, o PPP chamava-se:","o":["Gambia National Party","Protectorate People's Party","National Progressive Party","Gambia African Union","United Independence Party"],"c":1,"e":"O PPP de Jawara chamava-se Protectorate People's Party antes de mudar de nome em 1960."}]},{"id":"por-up-2018","subj":"por","titulo":"Exame de Admissão de Português","inst":"Universidade Pedagógica (UP)","ano":2018,"tempo":120,"textos":["<p><b>Saberemos ler?</b></p>\n<p>Pode nem sequer passar pela cabeça de uma pessoa que concluiu, pelo menos, a escolaridade obrigatória a ideia de que talvez não saiba realmente ler um texto.</p>\n<p>No entanto, a verdade é que o <i>saber ler</i> não se resume à nossa capacidade de reunirmos e pronunciarmos aquele conjunto de letras que formam uma palavra, a qual, por sua vez, se junta a outras na composição da frase, que é a unidade mínima do discurso.</p>\n<p>Essa capacidade de se compreender uma mensagem transmitida num código que é comum ao emissor e ao receptor (como é o caso, de que aqui nos ocupamos, da língua portuguesa para emissor e receptor portugueses) apenas faz com que um indivíduo se possa considerar alfabetizado num nível muito primário, que será uma espécie de grau zero do saber ler.</p>\n<p>Ora, o fundamental é, justamente, que tomemos consciência desse facto: porque se nos deixarmos ficar num optimismo de auto-suficiência, sem pormos em causa as nossas limitações, tornar-nos-emos irredutíveis a toda a possibilidade de progresso no que diz respeito à nossa competência de leitores. Corremos o risco de estagnar num insuficiente grau da nossa formação linguística. Num grau que só deveria ser ainda um grau – e nunca o ponto de paragem final.</p>\n<p>Também precisamos de reconhecer que essa competência é de extrema importância, tanto para o nosso prazer como para o nosso sucesso social – já ela nos vai permitir passar de consumidores passivos a produtores de textos escritos ou de actos de fala.</p>\n<p>Todos sabemos, por experiência própria, com que agrado e apreço é escutada uma pessoa que \"fala bem\" e como se torna confrangedor ouvir alguém exprimir-se com incorrecções. Isso chega a tornar-se motivo de riso, mais ou menos educadamente dissimulado.</p>\n<p>Quanto à forma como se escreve, também essa é quase sempre o factor mais determinante de preferência em muitas das oportunidades que se nos apresentam na vida. Os escolhidos para o desempenho de cargos honoríficos são geralmente aqueles que sabem utilizar correctamente a sua língua, exprimindo-se com aquela elegância, aquela arte que todos apreciam e tão poucos conseguem revelar na sua linguagem.</p>\n<p>Na nossa cultura, é lendo que se adquirem os conhecimentos de base, bem como pistas para posterior investigação dessas bases; assim, quanto mais lermos, mais vontade teremos de ler. Mas isto apenas se, de facto, <i>soubermos ler</i>.</p>\n<p>Nas civilizações dos povos com escrita, como é a nossa, ela tornou-se o lugar privilegiado para a conservação e transmissão dos dados culturais.</p>\n<p>É nos textos escritos que encontramos compilados os saberes daqueles que nos antecederam, o que nos permite avançar sempre, sem termos de recomeçar constantemente a partir do ponto inicial, do \"marco zero\" dos conhecimentos. Os povos sem escrita não praticam um processo de conhecimento linear, por etapas, progressivo, que é próprio do pensamento científico na busca incessante do saber; a resposta às perguntas que o homem faz em relação ao mundo que o rodeia e a si mesmo é uma resposta poética, total, não científica; é a resposta do mito.</p>\n<p>O mito procura dar uma resposta global às grandes interrogações do homem. Quanto ao pensamento científico, esse necessita de progredir por fases, que correspondem a parcelas do conhecimento; avança por etapas, tentando explicar um dado número de fenómenos, para, a partir daí, seguir para outros. E assim por diante, disse Descartes que o pensamento científico divide a dificuldade em tantas partes quantas as necessárias para a resolver.</p>\n<p>Ora, a escrita possibilita este tipo de investigação, porque permite que se registem as sucessivas descobertas. E nenhuma memória o poderia fazer. O pensamento mítico, pelo contrário, responde numa totalidade, ou seja: dá uma resposta que pretende ser total. Evidentemente que, nos nossos dias, este tipo de resposta não faz sentido para nós; não podemos conceder-lhe mais que um sorriso e um interesse de carácter histórico ou antropológico. O nosso conhecimento processa-se de outra forma, necessitando de ser registado através da escrita para poder avançar.</p>\n<p>Podemos desenvolver a nossa competência de leitores, exercitando a nossa perspicácia, a nossa rapidez de apreensão de um texto, a nossa segurança na compreensão daquilo que ele nos quer, de facto, dizer. Para isso, temos de começar pela análise dos diferentes tipos de problemas que se nos deparam quando lemos. De um modo geral, estes problemas podem dividir-se em dois grandes grupos: o grupo que integra as deficiências de apreensão do texto, por um lado, e o que engloba as questões originadas por um excesso de adesão a certos tipos de texto, por parte do leitor, e que são geralmente devidas à falta de espírito crítico.</p>\n<p><i>Teresa Moura Guedes, in Falar Melhor, Escrever Melhor, Selecções do Reader's Digest, pp. 92 e 93 (adaptado)</i></p>"],"q":[{"n":1,"tema":"Interpretação de texto","p":"Com o título <i>Saberemos ler?</i>, a autora:","o":["Pretende obter respostas dos leitores","Convida os leitores para aulas de leitura no futuro","Quer mostrar que a leitura é complexa","Revela que há muitos analfabetos"],"c":2,"e":"O texto defende que saber ler vai muito além de pronunciar letras e palavras, que ler exige compreensão e progressão contínua; a pergunta do título é retórica e sublinha essa complexidade.","tx":0},{"n":2,"tema":"Interpretação de texto","p":"Com a afirmação <i>Pode nem sequer passar pela cabeça de uma pessoa…</i> (1º parágrafo), a autora defende que:","o":["Há estudantes que não sabem ler em voz alta","Quem concluiu a escolaridade obrigatória não sabe ler","É frequente muitos lerem com dificuldades","Muitos leitores não compreendem o que lêem"],"c":3,"e":"A autora diz que mesmo quem tem escolaridade pode não saber realmente ler um texto, isto é, não o compreender (o saber ler não é só decifrar). A opção b generaliza demais.","tx":0},{"n":3,"tema":"Interpretação de texto","p":"De acordo com o texto, a unidade mínima do discurso é:","o":["A letra","A frase","A palavra","Um conjunto de letras"],"c":1,"e":"O 2º parágrafo diz que a palavra se junta a outras na composição da frase, «que é a unidade mínima do discurso».","tx":0},{"n":4,"tema":"Interpretação de texto","p":"O grau zero do saber ler, conforme o texto, significa:","o":["Ser analfabeto","Ter dificuldade na leitura de textos","Compreender textos escritos","Saber ler textos escritos em Português"],"c":2,"e":"O grau zero corresponde à capacidade de compreender uma mensagem num código comum ao emissor e ao receptor, ou seja, compreender o que está escrito, num nível muito primário. A opção d é próxima (o português é só o exemplo dado), por isso há alguma dúvida.","d":1,"tx":0},{"n":5,"tema":"Interpretação de texto","p":"Com a expressão <i>tomemos consciência desse facto</i> (4º parágrafo), a autora:","o":["Apela para sermos leitores competentes","Põe em causa as limitações dos leitores","Diz que há indivíduos incompetentes na leitura","Mostra que há insuficiências na nossa formação linguística"],"c":3,"e":"«Desse facto» é o de a leitura básica ser apenas o grau zero; tomar consciência dele é reconhecer as insuficiências da nossa formação linguística, sob pena de estagnarmos. A opção a também é defensável (apelo), pelo que a questão é ambígua.","d":1,"tx":0},{"n":6,"tema":"Interpretação de texto","p":"Segundo o texto, a competência de leitura é importante, porque:","o":["Permite que passemos a ser bons consumidores de textos","Garante o sucesso escolar","Proporciona prazer","Concorre para a melhoria da competência linguística e discursiva"],"c":2,"e":"O 5º parágrafo refere importância «para o nosso prazer» e para o sucesso social, e permite passar de consumidores passivos a produtores de textos. O sucesso é social, não escolar, e não se fala em «bons consumidores».","tx":0},{"n":7,"tema":"Interpretação de texto","p":"Conforme o texto, uma pessoa é escutada com agrado e apreço quando:","o":["Provoca riso","Se exprime com correcção","Fala bem dos dirigentes e do seu país","Fala bem de si mesmo"],"c":1,"e":"O 6º parágrafo diz que se escuta com agrado quem «fala bem», ao passo que exprimir-se com incorrecções provoca riso.","tx":0},{"n":8,"tema":"Interpretação de texto","p":"A forma como se escreve é quase sempre o factor mais determinante:","o":["Porque garante a ocupação de cargos honoríficos","Se souber compor textos com correcção e elegância","De preferência em muitas oportunidades","Para os poucos que conseguem revelar na sua mensagem"],"c":2,"e":"O 7º parágrafo diz que a forma como se escreve é quase sempre o factor mais determinante «de preferência em muitas das oportunidades» que a vida apresenta; as outras opções deturpam a frase.","tx":0},{"n":9,"tema":"Interpretação de texto","p":"De acordo com a autora, a leitura concorre para (8º parágrafo):","o":["Sabermos ler","A nossa cultura","A nossa formação","A nossa investigação"],"c":3,"e":"No 8º parágrafo, é lendo que se adquirem os conhecimentos de base e «pistas para posterior investigação».","tx":0},{"n":10,"tema":"Interpretação de texto","p":"Segundo a autora, os textos escritos:","o":["Permitem-nos avançar sempre","Permitem-nos partir do ponto inicial","Permitem-nos recomeçar constantemente a partir do ponto inicial","Permitem-nos estabelecer um conhecimento progressivo"],"c":0,"e":"O texto diz que os textos escritos nos permitem avançar sempre, sem termos de recomeçar constantemente do ponto inicial; as opções b e c afirmam o contrário.","tx":0},{"n":11,"tema":"Interpretação de texto","p":"A diferença entre o mito e o pensamento científico, de acordo com o texto:","o":["É que o primeiro pertence aos povos sem escrita","É que o segundo responde às inquietações do Homem","É que o primeiro dá respostas completas e o segundo fornece respostas incompletas","É que o primeiro dá uma resposta global, enquanto o segundo estabelece etapas para a resposta"],"c":3,"e":"O mito dá uma resposta global; o pensamento científico avança por fases, dividindo a dificuldade em partes.","tx":0},{"n":12,"tema":"Interpretação de texto","p":"Conforme o texto, para o nosso conhecimento poder avançar:","o":["Precisa da escrita","Deve-se combater o pensamento mítico","Precisa de cientistas","Precisa de pessoas com formação superior"],"c":0,"e":"O texto diz que o nosso conhecimento «necessita de ser registado através da escrita para poder avançar».","tx":0},{"n":13,"tema":"Interpretação de texto","p":"Para desenvolvermos a nossa competência de leitores:","o":["Devemos descobrir os problemas que temos na leitura","Devemos ser rápidos na leitura de textos","Devemos ler textos com segurança","Devemos criticar os textos"],"c":0,"e":"O último parágrafo diz que temos de começar pela análise dos diferentes tipos de problemas que se nos deparam quando lemos.","tx":0},{"n":14,"tema":"Gramática","p":"A oração <i>\"que concluiu, pelo menos, a escolaridade obrigatória\"</i> (1º parágrafo) é:","o":["Subordinada integrante","Subordinada causal","Subordinada relativa","Subordinada consecutiva"],"c":2,"e":"O «que» é pronome relativo (retoma «uma pessoa» e é sujeito de «concluiu»): oração subordinada adjectiva relativa."},{"n":15,"tema":"Gramática","p":"O conector <i>\"no entanto\"</i> (2º parágrafo) possui:","o":["Um valor aditivo","Um valor contrastivo","Um valor causal","Um valor conclusivo"],"c":1,"e":"«No entanto» é locução conjuncional/conector adversativo: opõe a verdade (saber ler é mais do que decifrar) à ideia do parágrafo anterior."},{"n":16,"tema":"Gramática","p":"As palavras <i>essa, uma, caso</i> e <i>primário</i> (3º parágrafo) são, respectivamente:","o":["Demonstrativo, artigo, verbo, substantivo","Possessivo, numeral, substantivo, adjectivo","Substantivo, artigo, verbo, adjectivo","Demonstrativo, artigo, substantivo, adjectivo"],"c":3,"e":"«Essa» é determinante demonstrativo; «uma» é artigo indefinido; «caso» (o caso) é substantivo; «primário» qualifica «nível», logo é adjectivo."},{"n":17,"tema":"Vocabulário","p":"As palavras <i>auto-suficiência, irredutíveis, possibilidade</i> são:","o":["Composta por justaposição, derivada por prefixação, derivada por sufixação","Composta por aglutinação, derivada por prefixação e sufixação, derivada por sufixação","Composta por justaposição, derivada por sufixação, derivada por sufixação","Composta por justaposição, derivada por prefixação e sufixação, derivada por sufixação"],"c":3,"e":"«Auto-suficiência» liga dois elementos com hífen (justaposição); «irredutíveis» tem prefixo ir- (in-) e sufixo -ível; «possibilidade» deriva de «possível» + -dade."},{"n":18,"tema":"Vocabulário","p":"As palavras da família de <i>leitura</i> são:","o":["Leiteiro, letreiro, literato, literacia","Literacia, liteira, literatura, leitor","Leitor, literacia, literatura, letra","Leitor, literatura, liteira, letra"],"c":2,"e":"Leitor, literacia, literatura e letra partilham a raiz lat. <i>lit(t)era</i>/<i>legere</i> (ler, letras). Leiteiro (leite), letreiro e liteira têm outra origem ou outro sentido.","d":1},{"n":19,"tema":"Vocabulário","p":"As palavras da família de <i>mito, global, progressivo</i> são, respectivamente:","o":["Mirtilo, globo, progredir","Mítico, globalização, progressão","Mitologia, globalidade, progressibilidade","Mítico, glocal, possessivo"],"c":1,"e":"Mítico (mito), globalização (global) e progressão (progressivo) são palavras da mesma família. Mirtilo, glocal e possessivo não têm relação; «progressibilidade» não é palavra consagrada."},{"n":20,"tema":"Gramática","p":"Em <i>\"…sabem utilizar correctamente <u>a sua língua</u>\"</i> a pronominalização da expressão sublinhada é:","o":["Sabem utilizar correctamente-a","Sabem utilizar-a correctamente","Sabem utilizá-la correctamente","Sabem utiliza-la correctamente"],"c":2,"e":"O pronome «a» liga-se ao infinitivo por hífen e toma a forma «-la» depois de -r, que cai; o -a de «utilizar» acentua-se: «utilizá-la»."},{"n":21,"tema":"Gramática","p":"Em <i>O pai ofereceu-me uma camisa</i>, a passiva correspondente é:","o":["Fui oferecido uma camisa pelo pai","Fui oferecida uma camisa pelo pai","Uma camisa foi-me oferecida pelo pai","Foi-lhe oferecida uma camisa pelo pai"],"c":2,"e":"O complemento directo «uma camisa» passa a sujeito da passiva e o complemento indirecto «me» mantém-se: «Uma camisa foi-me oferecida pelo pai». Em d o pronome «lhe» alteraria a pessoa."},{"n":22,"tema":"Vocabulário","p":"Nas palavras <i>conhecimento, mito, investigação, livro, ciência, importância</i>, a palavra intrusa é:","o":["Mito","Livro","Importância","Ciência"],"c":1,"e":"Todas são nomes abstractos (conceitos, ideias); «livro» é um nome concreto. Há alguma ambiguidade (por exemplo, quanto à formação).","d":1},{"n":23,"tema":"Gramática","p":"Nas palavras <i>nossa, essa, lhe, quem, aquilo, ali, cujo</i> a palavra intrusa é:","o":["Nossa","Cujo","Ali","Aquilo"],"c":2,"e":"As restantes são pronomes/determinantes (possessivo, demonstrativo, pessoal, relativo); «ali» é advérbio de lugar."},{"n":24,"tema":"Vocabulário","p":"Os hiperónimos de <i>atum, couve, Volvo, Teresa</i> são respectivamente:","o":["Peixe, vegetal, viatura, pessoa","Animal, planta, objecto, escritora","Peixe, vegetal, veículo, escritora","Sardinha, vegetal, viatura, pessoa"],"c":0,"e":"Hiperónimo é o termo mais geral: atum é peixe, couve é vegetal, Volvo é viatura e Teresa é pessoa. «Escritora» e «sardinha» são menos/mais específicos do que o pedido ou incorrectos."},{"n":25,"tema":"Vocabulário","p":"Os antónimos de <i>elegância, simpatia, sucesso, verdade</i> são, respectivamente:","o":["Inelegância, desimpatia, insucesso, inverdade","Deselegância, antipatia, insucesso, inverdade","Anelegância, antipatia, insucesso, desverdade","Inelegância, antipatia, insucesso, inverdade"],"c":1,"e":"As formas consagradas são deselegância, antipatia, insucesso e inverdade. «Desimpatia», «anelegância» e «desverdade» não existem; «inelegância» não é a forma usual."},{"n":26,"tema":"Gramática","p":"Na sequência <i>\"porque permite que se registem\"</i> (12º parágrafo) ocorrem duas orações:","o":["Causal e relativa","Causal e temporal","Causal e completiva","Causal e condicional"],"c":2,"e":"«Porque permite» é subordinada adverbial causal; «que se registem» é subordinada substantiva completiva (integrante), complemento de «permite»."},{"n":27,"tema":"Gramática","p":"Na sequência <i>\"porque permite que se registem\"</i> (12º parágrafo):","o":["O <i>se</i> é pronome reflexo","O <i>se</i> é conjunção condicional","O <i>se</i> é partícula apassivante","O <i>se</i> é pronome recíproco"],"c":2,"e":"«Registem-se as descobertas» equivale a «as descobertas sejam registadas»: o verbo concorda com o sujeito paciente («sucessivas descobertas»), logo «se» é partícula apassivante."},{"n":28,"tema":"Gramática","p":"Na expressão <i>\"nível muito primário\"</i>, o adjectivo encontra-se:","o":["No grau superlativo relativo de superioridade","No grau superlativo absoluto analítico","No grau superlativo relativo de inferioridade","No grau superlativo absoluto sintético"],"c":1,"e":"«Muito» + adjectivo forma o superlativo absoluto analítico (o sintético seria primaríssimo)."},{"n":29,"tema":"Gramática","p":"Falei com o homem. O homem é um escritor. A frase complexa correcta é:","o":["O homem que falei com ele é um escritor.","O homem é um escritor que falei com ele.","É um escritor o homem que falei com ele.","O homem com quem falei é um escritor."],"c":3,"e":"O relativo regido por preposição exige «com quem» (ou «com o qual»); as outras opções repetem o pronome «ele» ou usam «que» sem preposição."},{"n":30,"tema":"Literatura","p":"Um dramaturgo é aquele que:","o":["Escreve textos dramáticos","Participa em peças teatrais","Declama poemas","Escreve ensaios"],"c":0,"e":"Dramaturgo é o autor de textos dramáticos (peças de teatro); quem participa nelas é actor."},{"n":31,"tema":"Literatura","p":"O romance pertence:","o":["Ao género épico","Ao género dramático","Ao género lírico","Ao género narrativo"],"c":3,"e":"O romance é um texto em prosa em que se narra uma história: género narrativo. O género épico é o da epopeia, em verso."},{"n":32,"tema":"Literatura","p":"O texto lírico caracteriza-se por:","o":["Apresentar acções de personagens","Exprimir emoções","Narrar na 1ª pessoa","Breves momentos de avanço"],"c":1,"e":"O género lírico exprime emoções e sentimentos do eu poético; a acção de personagens é própria do dramático/narrativo."},{"n":33,"tema":"Literatura","p":"Um verso heróico possui:","o":["Sete sílabas métricas","Seis sílabas métricas","Dez sílabas métricas","Nove sílabas métricas"],"c":2,"e":"O decassílabo heróico tem dez sílabas métricas, com acentos na 6ª e na 10ª (como n'<i>Os Lusíadas</i>)."},{"n":34,"tema":"Literatura","p":"O autor de <i>Raiz de orvalho e outros poemas</i> é:","o":["Rui Craveirinha","Rui Nogar","Mia Couto","Noémia de Sousa"],"c":2,"e":"<i>Raiz de Orvalho e Outros Poemas</i> (1983) é a obra de estreia de Mia Couto."},{"n":35,"tema":"Literatura","p":"O autor de <i>Os Maias</i> é:","o":["Eça de Queiroz","Aldino Muianga","Armando Artur","Luís de Camões"],"c":0,"e":"<i>Os Maias</i> (1888) é romance de Eça de Queirós."},{"n":36,"tema":"Literatura","p":"Lília Momplé é autora de:","o":["<i>Karingana Ua Karingana</i>","<i>Os olhos da cobra verde</i>","<i>Niketche</i>","<i>Os Lusíadas</i>"],"c":1,"e":"<i>Os olhos da cobra verde</i> é de Lília Momplé; <i>Karingana ua Karingana</i> é de José Craveirinha, <i>Niketche</i> de Paulina Chiziane e <i>Os Lusíadas</i> de Camões."}]},{"id":"por-up-2016","subj":"por","titulo":"Exame de Admissão de Português","inst":"Universidade Pedagógica (UP)","ano":2016,"tempo":120,"textos":["<p><b>CONFIDENCIALIDADE E SIDA: UM DEBATE EM ABERTO</b></p>\n<p>A confidencialidade à volta do HIV e SIDA vem sendo um tema alvo de acesos debates que dividem opiniões. À partida, a confidencialidade enquadra-se no conjunto de práticas normativas da deontologia médica e dos profissionais de saúde, de um modo geral.</p>\n<p>Em face de uma situação concreta de um diagnóstico positivo em HIV a um indivíduo nas condições sócio-económicas, políticas e culturais que caracterizam Moçambique actualmente, será lícito pensar se em autorizar que o conhecimento desse facto seja de domínio público, ou dever-se-á primar pelo sigilo?</p>\n<p>Presentemente, no âmbito dos cuidados de saúde para com as pessoas que obtêm resultado positivo nos testes de HIV, não têm sido poucas as vozes que defendem o levantamento do sigilo e confidencialidade à volta da doença. A razão que tem sido sustentada à volta deste posicionamento é a de que comunicando publicamente o resultado, protege-se a sociedade, particularmente os parceiros com quem o indivíduo em causa priva intimidade. Acresce-se, ainda, que tal medida resultaria paulatinamente na diminuição do estigma e discriminação, esvaziando o temor em quebrar o silêncio e desmistificando a doença.</p>\n<p>Trata-se, efectivamente, de uma matéria que encerra várias considerações complexas. Estas atravessam áreas diversas, desde a de direitos humanos, passando por questões éticas e morais e desembocando, de alguma forma, em questões jurídico-legais, sem descorar da essência da deontologia médica, que aconselha, à partida, o sigilo médico como um importantíssimo direito do doente e uma obrigação deontológica e ética do médico (Rueff, 2004).</p>\n<p>Mas o que justifica que esta questão seja efervescente em domínio do HIV e SIDA? É que se está diante de uma doença que, no caso de Moçambique, se espalha maioritariamente através da relação sexual desprotegida entre indivíduos em que um deles é seropositivo. O estado de seropositividade em adultos tem levantado uma conotação negativa generalizada, cuja interpretação social a qualifica de resultado de má conduta, promiscuidade, entre outros.</p>\n<p>Sendo a sexualidade uma construção social que ainda gravita em tabu, é de esperar que à seropositividade se associe o estigma e a discriminação, dois males que constituem um atentado à preservação da vida de quem, à partida, já tem de lutar com o vírus no organismo, sendo assim empurrado para “uma morte social que precede a morte física” (Sontag, 1998).</p>\n<p>O direito à vida é primário e nestas circunstâncias precede todos os outros direitos que possam assistir ao indivíduo. Sendo assim, quando as circunstâncias induzem à hipótese de contaminação a terceiros, perigando desta feita a sua saúde, então, protegê-los desse perigo assume-se como um imperativo e dever moral de quem detém a verdade.</p>\n<p>Não sendo, todavia, uma matéria consensual, é importante aflorar outros contornos que este assunto encerra.</p>\n<p><b>A REVELAÇÃO VOLUNTÁRIA</b></p>\n<p>É importante referir que em grande medida, o que contribui para o sigilo à volta da infecção com HIV e SIDA é o ostracismo generalizado que o indivíduo em causa possa eventualmente sofrer. A discriminação por doença não é um fenómeno novo e não é exclusivo ao HIV e SIDA. Com efeito, registos há na história das doenças mais marcantes na humanidade, de comportamentos discriminatórios que acompanharam a sua evolução e a forma como os pacientes eram vistos e tratados. A tuberculose e a lepra são dois casos mais expressivos e próximos, tendo o impacto que geraram em tempos atingido a dimensão de um alarme generalizado, pela ignorância sobre como enfrentar a própria endemia e prevenir o seu alastramento. Esse conhecimento veio solidificar-se mais tarde.</p>\n<p>Relativamente ao HIV e SIDA, já desde o seu diagnóstico e tipificação em 1981 que o imperativo de não gerar um alarme generalizado, susceptível de conduzir a pânico e instabilidade social, tem acompanhado o posicionamento não apenas de cientistas, mas também de políticos e defensores de direitos humanos.</p>\n<p>É assim que já nos primeiros anos que se seguiram ao diagnóstico científico e tipificação do HIV e SIDA, se assiste a movimentos de <i>lobby</i> com a finalidade de ver respeitados certos princípios que contribuiriam, por um lado, para reduzir o possível pânico que poderia gerar-se ao nível da comunidade de um modo geral e, por outro, estimular a que indivíduos de livre vontade pudessem aderir ao teste e à badalada quebra do silêncio.</p>\n<p>Valerá ajuntar que o facto de os primeiros testes de HIV terem ocorrido em indivíduos que pertenciam a grupos marginalizados e ostracizados pode ter, de certo modo, contribuído para o fortalecimento do secretismo que desde então vem caracterizando o tratamento deste problema de saúde pública (Glum, 2002). Com efeito, as primeiras manifestações daquilo que viria a ser conhecido como o Síndroma de Imunodeficiência Adquirida (SIDA) são encontradas em grupos de homossexuais e consumidores de drogas injectáveis que já vinham sofrendo estigmatização e discriminação por o seu comportamento social e, particularmente, o sexual ser visto como uma perversão.</p>\n<p>Assim, os princípios que terão configurado a agenda de <i>lobbying</i> para a observância de direitos que assistem à vontade individual no contexto do HIV e SIDA resumiam-se no que hoje constitui os principais referentes dos direitos humanos, particularmente das pessoas que vivem com HIV e SIDA, nomeadamente:</p>\n<p>• Teste anónimo e confidencial;<br>• Teste voluntário e precedido de pré-aconselhamento;<br>• Direitos especiais nos postos de trabalho;<br>• Proibição de testes obrigatórios; e<br>• Condenação de todo o tipo de discriminação e estigma motivado por HIV e SIDA.</p>\n<p>A expectativa social para com estes princípios era a de que a sua materialização poderia resultar, efectivamente, em tomada de consciência generalizada, através dos programas de prevenção e aconselhamento, e consequentemente, adesão ao teste voluntário e, particularmente, à quebra pública do silêncio por forma a refrear o tabu que circunda a infecção e o estigma que a acompanha. Esta expectativa ainda que comece a ganhar campo, está ainda por se realizar na sua plenitude.</p>\n<p>Contrariamente a essa expectativa, vozes de cidadãos começam a vir a público questionar o porquê da confidencialidade à volta do HIV e SIDA; o porquê do não anúncio público dos resultados de indivíduos que obtêm teste positivo nos exames médicos. Indaga-se, se não será esta atitude um procedimento que ao invés de controlar, promove o alastramento do vírus e da doença?</p>\n<p>Enquanto isso, não são poucos os casos de casais em que uma das partes, apesar de conhecer o seu estado de seropositividade, mantém-no em sigilo e continua a relacionar-se sexualmente com o parceiro de forma natural.</p>\n<p>Portanto, a questão da confidencialidade à volta do HIV e SIDA, para além de atravessar matérias de cariz jurídico e legal, é sobretudo uma questão ética e moral. É que no caso referido acima, o silêncio sobre uma situação que atenta contra a vida de outrem e que em situação de gravidez também atenta contra a saúde da criança por nascer, ou sobre a vida dos dependentes, parece já não poder circunscrever-se à relação paciente-médico ou ao contexto rígido da confidencialidade. Parece uma matéria que merece tratamento alargado pelo menos até ao nível do agregado familiar e dos círculos de relação afectiva e amorosa do visado.</p>\n<p>A situação do HIV e SIDA é generalizada em África onde a principal via de transmissão é a relação sexual desprotegida entre parceiros com sero-status diferentes. A sua prevalência espalha-se em todos os grupos etários com particular incidência para a faixa etária dos 15-49 anos, tida como a das pessoas sexualmente activas.</p>\n<p>Por outro lado, e como referem alguns estudos de outros quadrantes do mundo, a violação do sigilo acarreta o risco de discriminação, podendo conduzir ao abandono do sistema de saúde, sacrificando assim o sistema médico – por este não pautar pelo princípio de confiança e de segredo (Rueff, 2004). É já conhecimento generalizado na literatura sobre saúde sexual e reprodutiva, que os grupos marginalizados e ostracizados de cidadãos raras vezes procuram serviços ou conselho médico (United Natios, 2005).</p>\n<p><i>In: Relatório Nacional do Desenvolvimento Humano 2007 – Moçambique</i></p>"],"q":[{"n":1,"tema":"Interpretação de texto","p":"De acordo com o texto, a confidencialidade à volta do HIV/SIDA vem sendo um tema alvo de acesos debates que dividem opiniões porque:","o":["Se trata de um assunto de grande interesse social;","Se enquadra no conjunto de práticas normativas da deontologia médica e de saúde em geral;","Existem opiniões prós e contra a confidencialidade sobre o HIV/SIDA;","As condições sócio-económicas, políticas e culturais, características de Moçambique, se impõem."],"c":2,"e":"O texto apresenta vozes que defendem o levantamento do sigilo e outras que o defendem (a confidencialidade é 'à partida' a norma deontológica); é a existência de posições opostas que divide opiniões. A opção D é a mais próxima como alternativa, mas as condições só contextualizam a pergunta. Enunciado algo circular.","d":1,"tx":0},{"n":2,"tema":"Interpretação de texto","p":"A opinião de se quebrar o sigilo e a confidencialidade em torno do HIV e SIDA apoia-se:","o":["Na protecção social e eliminação gradual do estigma e ostracismo;","Nos cuidados de saúde para pessoas que obtêm resultados positivos nos testes de HIV;","Na deontologia profissional dos médicos e dos profissionais da saúde;","No esvaziamento do temor em quebrar o silêncio e em mitigar a doença."],"c":0,"e":"Os defensores argumentam que, comunicando publicamente, 'protege-se a sociedade' e que a medida 'resultaria paulatinamente na diminuição do estigma e discriminação'. A deontologia (C) sustenta, pelo contrário, o sigilo; em D o texto fala em 'desmistificar', não em mitigar a doença.","tx":0},{"n":3,"tema":"Interpretação de texto","p":"Segundo o texto, a questão da confidencialidade à volta do SIDA, em Moçambique, é efervescente porque:","o":["A seropositividade associa-se ao estigma e à discriminação, para além de outros males que constituem uma ameaça à vida das pessoas;","A seropositividade resulta da má conduta e da promiscuidade dos indivíduos;","A seropositividade é geralmente vista como resultado de males como má conduta, promiscuidade e outros;","O HIV – SIDA espalha-se maioritariamente através de relações sexuais desprotegidas."],"c":3,"e":"A resposta do texto à pergunta 'o que justifica que esta questão seja efervescente?' é 'É que se está diante de uma doença que, no caso de Moçambique, se espalha maioritariamente através da relação sexual desprotegida'. As outras opções são consequências ou interpretações sociais, referidas depois.","d":1,"tx":0},{"n":4,"tema":"Interpretação de texto","p":"A expressão “uma morte social que precede a morte física” significa:","o":["Valorização social seguido de desaparecimento físico;","Preservação social seguida do desaparecimento físico;","Ostracismo social seguida de exclusão social;","Exclusão social que condena, à partida, o indivíduo à morte."],"c":3,"e":"O estigma e a discriminação 'empurram' o seropositivo para a exclusão da sociedade (morte social) antes da morte biológica. A opção C repete a ideia de exclusão social sem referir a morte.","tx":0},{"n":5,"tema":"Interpretação de texto","p":"De acordo com o texto, a primazia do direito à vida impõe que:","o":["Os seropositivos sejam, devidamente cuidados em unidades sanitárias específicas;","Os seropositivos protejam os terceiros da contaminação pelo HIV e SIDA;","Os seropositivos periguem a saúde de terceiros;","Os seropositivos assumam o imperativo e o dever moral de deter a verdade."],"c":1,"e":"O texto diz que, havendo risco de contaminação de terceiros, 'protegê-los desse perigo assume-se como um imperativo e dever moral de quem detém a verdade'. A opção D deturpa a frase: o dever é proteger, não 'deter a verdade'.","tx":0},{"n":6,"tema":"Interpretação de texto","p":"A passagem textual “a discriminação por doença não é um fenómeno novo e não é exclusiva a HIV e SIDA” significa que:","o":["Essa discriminação é universal;","Essa discriminação é contemporânea e extensiva a outras doenças;","Essa discriminação é antiga e extensiva a outras doenças;","Essa discriminação é antiga e extensiva a outros povos."],"c":2,"e":"'Não é um fenómeno novo' = antiga; 'não é exclusiva ao HIV' = extensiva a outras doenças (o texto cita a tuberculose e a lepra).","tx":0},{"n":7,"tema":"Interpretação de texto","p":"A tuberculose e a lepra são, na história das doenças mais marcantes em termos de comportamentos discriminatórios, as mais expressivas e próximas, devido:","o":["À dimensão alarmante que atingiram;","À falta de conhecimento sobre como lidar com elas e evitar o seu espalhamento;","À má fé das populações;","À instabilidade social e pânico gerado por estas doenças."],"c":0,"e":"O texto diz 'tendo o impacto que geraram em tempos atingido a dimensão de um alarme generalizado'. A ignorância (B) explica o alarme, não o carácter expressivo dos casos; dúvida entre A e B.","d":1,"tx":0},{"n":8,"tema":"Interpretação de texto","p":"De acordo com o texto, os movimentos de lobby mobilizados logo após o diagnóstico e tipificação do HIV e SIDA foram motivados por:","o":["Redução de pânico e estimulação da realização de testes;","Discriminação de indivíduos portadores de HIV/SIDA;","Imperativo de ocultar a gravidade da doença, de modo a não provocar pânico e instabilidade social;","Encorajamento de indivíduos a aderir livremente ao teste e a badalada quebra do silêncio."],"c":0,"e":"Os movimentos de lobby visavam 'por um lado, reduzir o possível pânico (...) e, por outro, estimular a que indivíduos de livre vontade pudessem aderir ao teste'. A reúne os dois objectivos; D refere apenas o segundo, pelo que há alguma ambiguidade.","d":1,"tx":0},{"n":9,"tema":"Interpretação de texto","p":"Os principais argumentos dos defensores da confidencialidade à volta do HIV e SIDA são:","o":["Não gerar um alarme generalizado e não acentuar a estigmatização dos indivíduos em que ocorreram os primeiros testes;","Não gerar um alarme generalizado e estimular a instabilidade social;","Desencadeamento de movimentos de lobby com a finalidade de ver respeitados certos princípios com vista a redução de pânico;","Redução da estigmatização e discriminação dos homossexuais e consumidores de drogas padecendo de HIV e SIDA."],"c":0,"e":"O texto refere o imperativo de não gerar alarme generalizado (pânico) e o facto de os primeiros testes terem sido feitos a grupos já estigmatizados, o que reforçou o secretismo. B é absurda (o alarme conduz à instabilidade, que se quer evitar).","tx":0},{"n":10,"tema":"Interpretação de texto","p":"A divergência de opiniões sobre a confidencialidade à volta do HIV e SIDA deve-se:","o":["À existência de princípios de direitos humanos particularmente sobre o HIV e SIDA;","À expectativa social em relação ao impacto dos direitos humanos;","Ao questionamento sobre a vantagem da confidencialidade e ao envolvimento sexual desprotegido por pessoas detentoras de informação sobre o seu estado;","À sua discussão nos diferentes domínios, tais como: o jurídico e legal, ética e moral."],"c":2,"e":"O texto contrapõe os cidadãos que questionam o porquê da confidencialidade ('se não será esta atitude um procedimento que (...) promove o alastramento') aos casos de casais em que um dos parceiros oculta o estado e continua a ter relações.","tx":0},{"n":11,"tema":"Interpretação de texto","p":"Segundo o texto, o silêncio sobre uma situação que atenta contra a vida de outras pessoas circunscreve-se no domínio:","o":["Da relação paciente-médico;","Do agregado familiar e círculos de relação afectiva e amorosa;","Do contexto de confidencialidade;","Da relação paciente/médico, agregado familiar e círculos de relação afectiva e amorosa."],"c":3,"e":"O texto diz que o silêncio 'parece já não poder circunscrever-se à relação paciente-médico ou ao contexto rígido da confidencialidade', merecendo 'tratamento alargado pelo menos até ao nível do agregado familiar e círculos afectivos'. Enunciado ambíguo; D (alargamento a todos estes domínios) é a melhor leitura, B é defensável.","d":1,"tx":0},{"n":12,"tema":"Interpretação de texto","p":"A expressão “a prevalência do HIV e SIDA em África espalha-se em todos os grupos etários, com particular incidência para a faixa etária 15-49 anos” quer dizer:","o":["O HIV – SIDA em África é transmitido principalmente pela relação sexual;","O HIV – SIDA dissemina-se facilmente em África;","A seropositividade em África afecta exclusivamente pessoas com 15-49 anos;","A seropositividade em África é predominante no intervalo de 15-49 anos."],"c":3,"e":"'Todos os grupos etários, com particular incidência' nos 15-49 anos significa predomínio nessa faixa, sem exclusividade (por isso C está errada).","tx":0},{"n":13,"tema":"Interpretação de texto","p":"No último parágrafo do texto invocam-se outros estudos para:","o":["Explicar a saúde sexual e reprodutiva;","Evidenciar a pertinência da confidencialidade à volta do HIV e SIDA;","Mostrar que há grupos de indivíduos que raramente procuram serviços ou conselho médico;","Destacar o sacrifício por que o sistema médico tem passado."],"c":1,"e":"Os estudos citados mostram que a violação do sigilo gera discriminação e afasta as pessoas dos serviços de saúde, ou seja, reforçam a pertinência da confidencialidade. C refere um dado desses estudos, não a sua finalidade; há dúvida entre B e C.","d":1,"tx":0},{"n":14,"tema":"Interpretação de texto","p":"O texto “Confidencialidade e SIDA: Um Debate em Aberto” é:","o":["Descritivo;","Expositivo-argumentativo;","Expositivo-explicativo;","Narrativo."],"c":1,"e":"O texto expõe o tema e confronta argumentos a favor e contra o sigilo, sem tomar uma posição definitiva: é expositivo-argumentativo.","tx":0},{"n":15,"tema":"Interpretação de texto","p":"A opção do tipo de texto assumida justifica-se pelo facto de:","o":["Descrever as opiniões de diferentes indivíduos sobre a confidencialidade a volta do HIV e SIDA;","Apresentar argumentos sobre as diferentes opiniões em torno da confidencialidade a volta do HIV e SIDA;","Transmitir um saber sobre a confidencialidade a volta do HIV e SIDA;","Narrar factos ligados a confidencialidade a volta do HIV e SIDA."],"c":1,"e":"É a apresentação de argumentos sobre posições divergentes que justifica o carácter argumentativo, além do expositivo. C justificaria apenas um texto expositivo-explicativo.","tx":0},{"n":16,"tema":"Gramática","p":"As palavras efervescente, particularmente e adesão são, respectivamente:","o":["Substantivo, adjectivo e substantivo;","Substantivo, advérbio e substantivo;","Adjectivo, advérbio e substantivo;","Adjectivo, advérbio e adjectivo."],"c":2,"e":"'Efervescente' qualifica 'questão' (adjectivo); 'particularmente' modifica o adjectivo/verbo (advérbio de modo); 'adesão' é um nome (substantivo)."},{"n":17,"tema":"Gramática","p":"As palavras sublinhadas em “A Confidencialidade à volta do HIV e SIDA vem sendo um tema alvo de acesos debates que dividem opiniões” são respectivamente:","o":["Substantivo, artigo definido e conjunção integrante;","Substantivo, contracção prepositiva com artigo definido e pronome relativo;","Substantivo preposição e conjunção integrante;","Advérbio, contracção prepositiva e pronome relativo."],"c":1,"e":"'Confidencialidade' é substantivo; 'à' = a (preposição) + a (artigo definido); 'que' retoma 'debates' e é sujeito de 'dividem': pronome relativo."},{"n":18,"tema":"Formação de palavras","p":"As palavras inconfortável e sexualidade são formadas por:","o":["Composição por aglutinação e derivação por sufixação;","Composição por justaposição e composição por aglutinação;","Derivação por parassíntese e derivação por sufixação;","Derivação por prefixação e derivação por sufixação."],"c":3,"e":"Inconfortável = prefixo in- + confortável (conforto + -ável, sufixo): derivação por prefixação (e sufixação). Sexualidade = sexual + -idade: derivação por sufixação. Não há composição."},{"n":19,"tema":"Ortografia · Plural","p":"Os plurais de “relaçãozinha”, “mal” e “fiel-homem” são, respectivamente.","o":["Relaçõezinhas, males, e fieis-homens;","Relaçãozinhas, males e fieis-homens;","Relaçõezinhas, males e fiel-homens;","Relaçãozinhas, mais e fieis-homens."],"c":0,"e":"Nos diminutivos em -zinho/-zinha, pluraliza-se o nome-base e o sufixo: relações + zinhas = relaçõezinhas. 'Mal' faz 'males'; em 'fiel-homem' (adjectivo + substantivo) ambos variam: fiéis-homens."},{"n":20,"tema":"Gramática","p":"A oração sublinhada em “trata-se, efectivamente, de uma matéria que encerra várias considerações complexas”, é:","o":["Subordinada relativa;","Subordinada causal;","Subordinada consecutiva;","Subordinada integrante."],"c":0,"e":"'Que encerra várias considerações complexas' é introduzida pelo pronome relativo 'que' (antecedente 'matéria') e funciona como modificador do nome: subordinada adjectiva relativa."},{"n":21,"tema":"Gramática","p":"A oração sublinhada em “acresce-se, ainda, que tal medida resultaria paulatinamente na diminuição do estigma e discriminação”, é","o":["Subordinada final;","Subordinada integrante;","Subordinada relativa;","Subordinada consecutiva."],"c":1,"e":"É introduzida pela conjunção integrante 'que' e funciona como sujeito (oração completiva) de 'acresce-se'."},{"n":22,"tema":"Gramática","p":"A expressão descontínua sublinhada em “(…) tem acompanhado o posicionamento não apenas de cientistas, mas também de políticos e defensores de direitos humanos” exprime a ideia de:","o":["Oposição;","Consequência;","Adição;","Companhia."],"c":2,"e":"'Não apenas... mas também' é uma locução conjuncional copulativa correlativa, que acrescenta um elemento a outro: ideia de adição."},{"n":23,"tema":"Gramática","p":"As palavras sublinhadas em “portanto, a questão da confidencialidade a volta do HIV/SIDA, para além de atravessar matéria de cariz jurídico e legal, é sobretudo uma questão ética e moral” exprimem, respectivamente:","o":["Fim e adição;","Consequência e oposição;","Causa e adição;","Conclusão e adição."],"c":3,"e":"'Portanto' é conjunção conclusiva; 'e' liga 'jurídico' e 'legal', coordenação copulativa (adição)."},{"n":24,"tema":"Gramática","p":"A oração sublinhada em “(…) não são poucos os casos de casais em que uma das partes, apesar de conhecer o seu estado de seropositividade, mantém-no em sigilo (…)” são respectivamente:","o":["Subordinada concessiva;","Coordenada adversativa;","Coordenada conclusiva;","Subordinada consecutiva."],"c":0,"e":"'Apesar de conhecer...' exprime uma concessão (oposição não impeditiva), logo oração subordinada concessiva (infinitiva). O enunciado diz 'respectivamente' mas a opção A é a única que classifica correctamente a oração sublinhada."},{"n":25,"tema":"Funções sintácticas","p":"As funções sintácticas das passagens sublinhadas em incansavelmente, os profissionais de saúde realizam permanentemente movimentos de lobby, com vista a redução de pânico em relação ao HIV-SIDA, são, respectivamente:","o":["Atributo, complemento circunstancial de tempo e complemento directo;","Complemento circunstancial de tempo, aposto e complemento indirecto;","Complemento circunstancial de modo, complemento circunstancial de tempo e complemento directo;","Complemento circunstancial de companhia, complemento circunstancial de tempo e complemento directo."],"c":2,"e":"'Incansavelmente' indica o modo; 'permanentemente' indica a duração/frequência (tempo); 'movimentos de lobby' é o objecto directo de 'realizam'."},{"n":26,"tema":"Funções sintácticas","p":"A função sintáctica da palavra sublinhada em muitos seropositivos continuam preconceituosos é:","o":["Complemento directo;","Atributo;","Complemento circunstancial de modo;","Nome predicativo de sujeito."],"c":3,"e":"'Continuar' é aqui verbo copulativo e 'preconceituosos' é o predicativo que caracteriza o sujeito 'muitos seropositivos'."},{"n":27,"tema":"Literatura","p":"O autor do livro “Nós matámos o cão tinhoso” é:","o":["Calane da Silva;","Pepetela;","Luís Bernardo Honwana;","Marcelino dos Santos."],"c":2,"e":"“Nós Matámos o Cão-Tinhoso” (1964) é a colectânea de contos de Luís Bernardo Honwana."},{"n":28,"tema":"Literatura","p":"“O Último Voo do Flamengo” é da autoria de:","o":["Paulina Chiziane;","Mia Couto;","Jorge Amado;","Ungulani Ba Ka Khosa."],"c":1,"e":"“O Último Voo do Flamingo” (2000) é um romance de Mia Couto."},{"n":29,"tema":"Literatura","p":"O escritor Francisco José Tenreiro é de nacionalidade:","o":["Moçambicana;","Brasileira;","Cabo-verdiana;","São-tomense."],"c":3,"e":"Francisco José Tenreiro (1921–1963) nasceu em São Tomé e foi poeta ligado à Negritude lusófona."},{"n":30,"tema":"Literatura","p":"O teatro de Gil Vicente revela:","o":["A revolta contra o cristianismo;","A obra escrita em prosa;","A busca de conceitos universais;","A preocupação do Homem com a religião."],"c":3,"e":"Os autos de Gil Vicente (de índole religiosa e moralizante, como o Auto da Barca do Inferno) reflectem a preocupação com a salvação e a religião; escreveu sobretudo em verso (B falsa). C é defensável (tipos universais), daí a dúvida.","d":1},{"n":31,"tema":"Literatura","p":"O movimento Realista tende para:","o":["A expressão do egocentrismo, hipersensibilidade e melancolia;","A exaltação do sentimento teocentrista e egocentrista;","A reprodução da realidade sem requintes nem retoques;","A apresentação da visão platónica do amor."],"c":2,"e":"O Realismo procura retratar objectivamente a realidade social. A opção A descreve o Romantismo e D o amor platónico/classicismo."},{"n":32,"tema":"Literatura","p":"A Negritude, como movimento literário, teve como protagonistas:","o":["Aimé Césaire, Noémia de Sousa, Rui de Noronha;","Aimé Césaire, Léopold Sédar Senghor e Léon Damas;","Léon Damas, Agostinho Neto, Pepetela;","Léopold Sédar Senghor, Luís Bernardo Honwana e José Craveirinha."],"c":1,"e":"Os fundadores da Negritude (Paris, anos 30) foram Aimé Césaire, Léopold Senghor e Léon-Gontran Damas."},{"n":33,"tema":"Literatura","p":"A Crónica de Fernão Lopes destaca-se na produção de:","o":["Romance;","Novela;","Lírica;","Historiografia."],"c":3,"e":"Fernão Lopes é o cronista-mor do reino e o principal representante da historiografia medieval portuguesa."},{"n":34,"tema":"Literatura","p":"Uma das tensões fundamentais na Lírica Camoniana é:","o":["O ódio;","A vaidade;","O desconcerto do mundo;","O rancor."],"c":2,"e":"O 'desconcerto do mundo' (contraste entre o ideal e a realidade, o bem castigado e o mal premiado) é um tema central da lírica de Camões."},{"n":35,"tema":"Literatura","p":"Um dos precursores da Literatura Moçambicana escrita foi:","o":["Eduardo White;","Rui de Noronha;","Armando Artur;","Nelson Saúte."],"c":1,"e":"Rui de Noronha (1909–1943), autor de 'Sonetos', é considerado um dos precursores da poesia moçambicana escrita. White, Artur e Saúte são posteriores."}]},{"id":"por-up-2014","subj":"por","titulo":"Exame de Admissão de Português","inst":"Universidade Pedagógica (UP)","ano":2014,"tempo":120,"textos":["<p><b>As razões do triunfo do conceito de desenvolvimento humano</b></p>\n<p>O reconhecimento público nem sempre é a forma mais fiável de avaliar a grandeza de um trabalho intelectual. O livro de John Stuart Mill intitulado Subjection of Women é o único trabalho dele no qual a sua editora teve prejuízos; o livro de Bertrand Russell sobre lógica matemática teve, inicialmente, poucos leitores; o livro Philosophical Investigations, de Wittgenstein, conquistou proeminência gradualmente. De igual modo, a apreciação da música de Mozart demorou mais do que o celebre compositor esperava. O aplauso rápido nem sempre premeia contribuições criativas.</p>\n<p>Pelo contrário, Mahbub ul Haq não teria tido oportunidade de se queixar que o mundo demorou muito tempo a apreciar os méritos notáveis da sua obra engenhosa, o Relatório de Desenvolvimento Humano, como veículo de comunicação, nem a aceitar a preeminência da ideia do 'desenvolvimento humano' como um conceito brilhante que integra uma variedade de preocupações sobre as vidas das pessoas, o seu bem estar e liberdades. A criação de Mahbub foi imediatamente notada e aplaudida em menos de uma década. A este respeito, o PNVD teve mais sorte do que a editora de John Stuart Mills.</p>\n<p>A pergunta que quero começar por levantar é esta: porque é que o Relatório de Desenvolvimento Humano foi e continua a ser alvo de tanta atenção e tão rapidamente num mundo em que as ideias novas geralmente levam décadas, mesmo séculos, para receberem o devido reconhecimento? Porque é que a ideia do desenvolvimento humano teve sucesso no mundo contemporâneo? Não se trata aqui de questionar a profundidade das ideias criativas de Mahbub ul Haq, que é obviamente clara e de modo algum é objecto de qualquer disputa ...</p>\n<p>Isto levanta uma questão ainda mais elementar. O que é que a contabilização do desenvolvimento humano faz? Qual é o seu aspecto especial, as suas características identificáveis? Esta é, em certa medida, uma questão fácil de responder. Em vez de se concentrar somente nas tradicionais medidas económicas isoladas (tais como o Produto Nacional Bruto per capita), a contabilização do desenvolvimento humano envolve uma análise sistemática da informação rica sobre como é que os seres humanos em cada sociedade vivem (incluindo o nível da sua educação e saúde, entre outras variáveis). Ela traz para o exercício da avaliação do desenvolvimento uma concepção pluralista do progresso.</p>\n<p>As vidas humanas são prejudicadas e diminuídas de muitas maneiras e a primeira tarefa, nesta perspectiva, é reconhecer que as privações de diferentes formas tem de ser acomodadas dentro de um quadro conceptual mais geral. Este quadro tem de ser congruente e coerente, sem contudo tentar ignorar os pluralismos cruciais que estão envolvidos na natureza diversificada das privações, numa busca cega de uma medida de sucesso ou fracasso, de um único indicador para problemas tão dispares.</p>\n<p>É esta fé na monoconcentração que começou a suscitar bastante cepticismo quando os Relatórios de Desenvolvimento Humano foram lançados. Mahbub assumiu a liderança de vários exércitos de descontentes que se batiam, embora esporadicamente, contra a concentração dogmática no PNB. Existiam activistas que lutavam pelo reconhecimento das 'necessidades básicas'. Existiam forças intervencionistas internacionais que lamentavam a situação das crianças no mundo. Existiam organizações de ajuda que estavam preocupadas com a fome e epidemias. Existiam escritores concentrados e preocupados com as 'disparidades' entre as vidas reais dos ricos e dos pobres. Existiam humanistas que clamavam pela justiça social na qualidade de vida. Existiam advogados de medidas da qualidade física da vida. Havia mesmo críticos com inclinações filosóficas que se interrogavam sobre os indicadores mais abrangentes na ética social que se encontram nas obras célebres de Aristóteles, Adam Smith, Karl Marx e mesmo John Stuart Mill.</p>\n<p>Foi por causa da visão integradora de Mahbub que ele viu a oportunidade de aproveitar estes diferentes descontentes para a elaboração duma visão alternativa que pudesse ser simultaneamente prática e ampla e pudesse acomodar, nem que fosse de uma maneira incipiente, estas preocupações. Se a ideia do desenvolvimento humano teve aceitação rápida foi graças a habilidade (de Mahbub ul Haq, em última análise) em transformar a onda de descontentamento num movimento intelectual crescente e flexível.</p>\n<p>Não surpreende, portanto, que as acusações contra Mahbub tenham sido da mesma índole que as críticas usadas anteriormente para garantir a vitória do utilitarismo, num campo concebido especialmente para o efeito, e que a sua obra tenha gerado um sem-fim de protestos murmurados sobre como as ideias dele não tinham gerado automaticamente uma única equação 'métrica operacional'. É verdade que não produziram, porque não podiam e nem deviam produzir.</p>\n<p>O domínio da avaliação social não pode ser tomado por soluções de uma engenharia desprovida de juízos de valor. É importante que as pessoas avaliem explícita e criticamente o que querem e se envolvam em discussões a favor e contra um conjunto de pesos ponderados. As ponderações que eventualmente emergirem do debate serão, em última análise, uma questão de escolhas sociais, que não podem ser derrotados por uma leitura mecânica de uma 'verdade' aparente. O debate público inteligente e informado ocupa um lugar fulcral neste exercício. Apoiar a base intelectual de um debate público bem informado é uma das glórias do projecto de desenvolvimento humano.</p>\n<p>A ideia do desenvolvimento humano triunfou porque o mundo estava preparado para ela. Mahbub deu-lhe o que ela vinha procurando de diversas formas nas decadas anteriores ...</p>\n<p><i>Amartya Sen, Prémio Nobel da Economia de 1998. Extracto do Discurso de Abertura, A Decade of Human Development, 29/7/1999</i></p>"],"q":[{"n":1,"tema":"Interpretação de texto","p":"O reconhecimento público nem sempre é a forma mais fiável de avaliar o trabalho intelectual porque:","o":["O sucesso vem sempre mais tarde;","O valor é determinado pelo seu contributo social;","O trabalho pode criar prejuízos às editoras;","A qualidade é avaliada depois de décadas."],"c":0,"e":"O texto dá exemplos (Mill, Russell, Wittgenstein, Mozart) de obras de valor que só mais tarde foram reconhecidas, e diz que 'o aplauso rápido nem sempre premeia contribuições criativas'. A opção d é próxima, mas fixa 'décadas' como regra; o texto fala em 'décadas, mesmo séculos'. Questão pouco nítida.","d":1,"tx":0},{"n":2,"tema":"Interpretação de texto","p":"O Livro de John Stuart Mill criou prejuízos à editora porque:","o":["Era desprovido de valor intelectual;","Era de difícil leitura;","Foi rapidamente aplaudido;","O seu conteúdo não foi logo apreendido."],"c":3,"e":"O texto diz que a obra de Mill deu prejuízos à editora e, noutros exemplos, que as obras tiveram 'inicialmente poucos leitores' e conquistaram proeminência 'gradualmente': o conteúdo não foi logo compreendido/valorizado.","tx":0},{"n":3,"tema":"Interpretação de texto","p":"A ideia defendida no segundo parágrafo é que Mahbub:","o":["Viu o seu trabalho reconhecido em menos de dois lustros;","Se queixou da demora do reconhecimento do seu trabalho;","Criou uma obra engenhosa;","Foi rapidamente aceite pela comunidade intelectual."],"c":0,"e":"O parágrafo diz que a criação de Mahbub foi 'imediatamente notada e aplaudida em menos de uma década' (dois lustros = dez anos), em contraste com Mill; o que o parágrafo sublinha é a rapidez do reconhecimento, expressa em 'menos de uma década'.","tx":0},{"n":4,"tema":"Interpretação de texto","p":"A concepção pluralista do desenvolvimento humano, segundo o articulista, assenta em:","o":["Avaliar as características peculiares de cada nação;","Avaliar o desenvolvimento de uma nação em função do PNB;","Avaliar os aspectos socio-económicos e culturais de uma nação;","Avaliar os níveis de Educação e saúde de cada nação."],"c":2,"e":"Em vez de só medidas económicas (PNB), a contabilização analisa informação rica sobre como vivem os seres humanos, incluindo educação, saúde 'entre outras variáveis': uma visão plural, socio-económica e cultural. A opção d reduz a duas variáveis apenas.","tx":0},{"n":5,"tema":"Interpretação de texto","p":"Os Relatórios de Desenvolvimento Humano põem em causa:","o":["A busca de indicador único e comum na determinação do (in)sucesso;","As privações por que passam muitos países do Sul;","As disparidades de qualidade de vida entre os países ricos e pobres;","A existência de advogados que defendem a qualidade física da vida."],"c":0,"e":"O texto critica a 'busca cega de uma medida de sucesso ou fracasso, de um único indicador para problemas tão dispares' e a 'concentração dogmática no PNB'.","tx":0},{"n":6,"tema":"Interpretação de texto","p":"Para o articulista o sucesso de Mahbub assenta em:","o":["Recorrer a obras célebres de Aristóteles, Marx, Smith, e Mill;","Estudar as necessidades básicas das sociedades;","Sintetizar as diversas perspectivas de estudo das sociedades;","Monoconcentrar as pesquisas em torno do PNB."],"c":2,"e":"'Foi por causa da visão integradora de Mahbub' que ele aproveitou os diferentes descontentes numa visão alternativa ampla: sintetizou várias perspectivas.","tx":0},{"n":7,"tema":"Interpretação de texto","p":"Mehbub é criticado por certas correntes em virtude de:","o":["Não ter criado um movimento intelectual, crescente e flexível;","Não ter concebido uma fórmula para a avaliação do desenvolvimento;","Ter falta de uma variável fiável na avaliação do desenvolvimento;","Encorajar soluções de uma engenharia desprovida de juízos de valor."],"c":1,"e":"Os protestos incidiam em que as ideias dele 'não tinham gerado automaticamente uma única equação métrica operacional'. A opção a contradiz o texto (criou, sim, um movimento crescente e flexível).","tx":0},{"n":8,"tema":"Interpretação de texto","p":"O debate público defendido pelo articulista implica:","o":["Adopção de soluções baseadas em engenharia;","Avaliação crítica e explícita de vários factores sócio-económicos;","A aceitação do conceito de desenvolvimento humano;","Discussão a favor e contra um conjunto de pesos ponderados."],"c":3,"e":"O texto diz que as pessoas devem avaliar 'explícita e criticamente o que querem e [envolver-se] em discussões a favor e contra um conjunto de pesos ponderados'. A opção b é parecida, mas fala de factores sócio-económicos que o texto não menciona neste ponto; melhor leitura: d.","d":1,"tx":0},{"n":9,"tema":"Interpretação de texto","p":"Uma das virtudes do projecto do Desenvolvimento Humano é:","o":["Sustentar a base intelectual de um debate público bem informado;","Sustentar uma leitura mecânica e aparente da realidade;","Sustentar um debate público que propicie a transferência de tecnologias;","Sustentar um debate público assente na ética social."],"c":0,"e":"Cita-se: 'Apoiar a base intelectual de um debate público bem informado é uma das glórias do projecto de desenvolvimento humano'.","tx":0},{"n":10,"tema":"Interpretação de texto","p":"O conceito de desenvolvimento humano triunfou devido a:","o":["Aglutinação de diversas correntes de opinião;","Aglutinação de humanistas que reivindicam melhor qualidade de vida;","Existência de vários exércitos de descontentes;","Existência de forças intervencionistas internacionais."],"c":0,"e":"Mahbub, graças à sua visão integradora, transformou os vários descontentamentos 'num movimento intelectual crescente e flexível'; ou seja, aglutinou diversas correntes. A existência dos descontentes (c) era só a matéria-prima.","tx":0},{"n":11,"tema":"Vocabulário","p":"O sinónimo da palavra <i>preeminência</i> empregue no texto é:","o":["Preponderância;","Importância;","Grandeza;","Superioridade."],"c":3,"e":"Preeminência é a qualidade do que está acima dos outros, primazia, superioridade. 'Preponderância' (predomínio de influência) é próxima, mas a primeira acepção de preeminência é superioridade.","d":1},{"n":12,"tema":"Vocabulário","p":"A expressão \"<i>exércitos de descontentes</i>\" empregue no texto, significa:","o":["Indivíduos desfavorecidos;","Grupos de frustrados;","Intelectuais com posições opostas;","Engenheiros desprovidos de bens."],"c":1,"e":"Em sentido figurado, 'exércitos' são grupos numerosos; 'descontentes' são os insatisfeitos com a concentração no PNB (activistas, escritores, humanistas...). A melhor leitura é 'grupos de frustrados/insatisfeitos'; c é defensável, pois os descontentes eram também críticos.","d":1},{"n":13,"tema":"Vocabulário","p":"\"O domínio da avaliação social não pode ser tomado por <i>soluções de uma engenharia desprovida de juízos de valor.</i>\" A expressão em itálico significa:","o":["Soluções sem aplicação prática;","Soluções mecânicas;","Soluções de baixo custo;","Soluções empíricas."],"c":1,"e":"Uma 'engenharia sem juízos de valor' aplica fórmulas de modo automático, ou seja, soluções mecânicas (o texto fala depois em 'leitura mecânica')."},{"n":14,"tema":"Vocabulário","p":"Os termos <i>grandeza, ponderações,</i> empregues no texto, têm significados próximos, respectivamente, de:","o":["Magnificência, reflexão;","Magnificência, flexibilidade;","Ostentação, reflexão;","Ostentação, flexibilidade."],"c":0,"e":"Grandeza ~ magnificência (grandiosidade); ponderações ~ reflexão (ponderar é pesar, reflectir). Ostentação e flexibilidade não correspondem."},{"n":15,"tema":"Vocabulário","p":"Na frase, \"Mehbub assumiu a <i>liderança</i> de vários exércitos de descontentes\", a palavra em itálico pode ser substituída por:","o":["Coordenação;","Organização;","Regimento;","Governação."],"c":0,"e":"Liderança é o acto de dirigir/comandar um grupo, o que corresponde melhor a coordenação. Regimento é unidade militar e governação é administrar um Estado/instituição.","d":1},{"n":16,"tema":"Vocabulário","p":"A partir da palavra <i>epidemia</i>, empregue no texto, identifique o intruso na lista seguinte:","o":["Epidérmico;","Epidémico;","Epidemiologia;","Epidemiológico."],"c":0,"e":"Epidémico, epidemiologia e epidemiológico derivam de epidemia; 'epidérmico' vem de epiderme (pele)."},{"n":17,"tema":"Vocabulário","p":"\"...teve sucesso no mundo <u>contemporâneo</u>\". O antónimo da palavra sublinhada na frase é:","o":["Arcaico;","Anterior;","Ancestral;","Velho."],"c":0,"e":"Contemporâneo (actual, do nosso tempo) opõe-se a arcaico (muito antigo, ultrapassado). Anterior indica apenas posição temporal relativa; ancestral refere-se aos antepassados."},{"n":18,"tema":"Gramática","p":"Na frase, \"<i>Pelo contrário,</i> Mahbub Ul Haq não teria tido oportunidade de se queixar...\", o conector destacado introduz a ideia de:","o":["Causa;","Adição;","Oposição;","Conclusão."],"c":2,"e":"'Pelo contrário' opõe o caso de Mahbub aos exemplos anteriores de reconhecimento tardio."},{"n":19,"tema":"Gramática","p":"\"Mahbub assumiu a liderança de vários exércitos de descontentes que se batiam, <i>embora</i>, esporadicamente, contra a concentração dogmática do PNB\". Nesta frase, o conector em itálico estabelece uma relação de:","o":["Oposição;","Consequência;","Fim;","Concessão."],"c":3,"e":"'Embora' é conjunção subordinativa concessiva; a oposição (a) seria expressa por conjunção coordenativa adversativa (mas, porém)."},{"n":20,"tema":"Gramática","p":"Na frase, \"Não surpreende, <i>portanto,</i> que as acusações contra Mahbub tenham sido da mesma índole que as críticas...\", o conector em itálico introduz ideia de:","o":["Explicação;","Conclusão;","Condição;","Consequência."],"c":1,"e":"'Portanto' é conjunção coordenativa conclusiva. A opção d é tentadora, mas a classificação gramatical é conclusão."},{"n":21,"tema":"Gramática","p":"Qual das seguintes frases expressa o superlativo absoluto?","o":["O nível de educação alcançado é um indicador muito importante;","O nível de educação alcançado é um indicador mais importante;","O nível de educação alcançado é o indicador muito importante;","O nível de educação alcançado é o indicador mais importante."],"c":0,"e":"O superlativo absoluto intensifica sem comparar (muito importante). As opções b e d são comparativo/superlativo relativo."},{"n":22,"tema":"Gramática","p":"Os nomes formados a partir dos verbos <i>conquistar, fazer</i> e <i>receber</i> são, respectivamente:","o":["Conquista, Fazenda, Recebedoria;","Conquista, Fazenda, Recepção;","Conquista, Facto, Recebedoria;","Conquista, Facto, Recepção."],"c":3,"e":"Os nomes deverbais são conquista, facto (de fazer) e recepção (de receber). Fazenda e recebedoria têm outros sentidos."},{"n":23,"tema":"Gramática","p":"Dos nomes <i>concepção, grandeza</i> e <i>base</i> formam-se os seguintes verbos, respectivamente:","o":["Concepcionar, Grandecer, Basear;","Conceber, Engrandecer, Basear;","Concepcionar, Engrandecer, Basear;","Conceber, Grandecer, Basear."],"c":1,"e":"Concepção vem de conceber; grandeza dá engrandecer; base dá basear."},{"n":24,"tema":"Gramática","p":"Selecione a frase pontuada correctamente:","o":["Em África, nem tudo é tristeza; veja-se o crescimento económico de alguns países;","Em África nem tudo é tristeza, veja-se o crescimento económico, de alguns países;","Em África, nem tudo é tristeza: veja-se o crescimento económico de alguns países;","Em África, nem tudo é tristeza. veja-se, o crescimento económico de alguns países."],"c":2,"e":"Os dois pontos introduzem o esclarecimento/exemplificação ('veja-se...'); o vocativo/complemento deslocado 'Em África' leva vírgula. b separa o complemento de modo incorrecto, d tem minúscula após ponto. A opção a é aceitável, mas c é a mais adequada.","d":1},{"n":25,"tema":"Gramática","p":"<i>Reconhecimento</i> e <i>cepticismo</i> são palavras formadas, respectivamente, por:","o":["Derivação por prefixação e derivação por sufixação;","Composição por aglutinação e derivação por prefixação e sufixação;","Derivação por sufixação e derivação por prefixação;","Derivação por prefixação e sufixação e derivação por sufixação."],"c":3,"e":"Reconhecimento = re- + conhec(er) + -mento (prefixo e sufixo); cepticismo = céptico + -ismo (sufixo)."},{"n":26,"tema":"Gramática","p":"Das frases interrogativas que se seguem indique a alternativa correcta.","o":["Por que é que introduziu Mahbub novos indicadores de desenvolvimento humano?","Por que Mahbub introduziu novos indicadores de desenvolvimento humano?","Mahbub introduziu novos indicadores de desenvolvimentos humano porquê?","Porque Mahbub introduziu novos indicadores de desenvolvimento humano?"],"c":1,"e":"Em interrogativas directas escreve-se 'por que' (separado) no início ou 'porquê' no fim. a tem ordem estranha após 'é que'; c tem 'desenvolvimentos humano' (concordância errada); d usa 'porque' junto."},{"n":27,"tema":"Gramática","p":"Identifique a frase relativa correctamente construída.","o":["A avaliação que os RDH estão sujeitos depende do conceito que se tem do desenvolvimento;","A avaliação de que os RDH estão sujeitos depende do conceito que se tem do desenvolvimento;","A avaliação a que os RDH estão sujeitos depende do conceito que se tem do desenvolvimento;","A avaliação em que os RDH estão sujeitos depende do conceito que se tem de desenvolvimento."],"c":2,"e":"'Estar sujeito' rege a preposição 'a'; logo o pronome relativo é 'a que'."},{"n":28,"tema":"Gramática","p":"Indique a frase correcta:","o":["O cepticismo e a desconfiança dos opositores de Mahbub deve merecer a atenção dos economistas;","O cepticismo e a desconfiança dos opositores de Mahbub devem merecerem a atenção dos economistas;","O cepticismo e a desconfiança dos opositores de Mahbub deve merecerem a atenção dos economistas;","O cepticismo e a desconfiança dos opositores de Mahbub devem merecer a atenção dos economistas."],"c":3,"e":"Sujeito composto (cepticismo e desconfiança) pede verbo auxiliar no plural (devem); o infinitivo principal fica invariável (merecer)."},{"n":29,"tema":"Gramática","p":"Escolha a construção comparativa correcta:","o":["A situação das crianças no mundo é mais lamentável que o desemprego nos países do sul;","A situação das crianças no mundo é mais lamentável do que o desemprego nos países do sul;","A situação das crianças no mundo é muito lamentável que o desemprego nos países do sul;","A situação das crianças no mundo é muito lamentável do que o desemprego nos países do sul."],"c":1,"e":"A comparativa de superioridade usa 'mais ... (do) que'. c e d usam 'muito', que não compara. Entre a e b, a norma escolar privilegia 'do que'.","d":1},{"n":30,"tema":"Gramática","p":"Aponte a construção condicional correcta.","o":["A independência económica acontecerá caso as pessoas se envolvem no debate público;","A independência económica acontecerá caso as pessoas envolvem-se no debate público;","A independência económica acontecerá caso as pessoas envolvam-se no debate público;","A independência económica acontecerá caso as pessoas se envolvam no debate público."],"c":3,"e":"'Caso' exige o conjuntivo (envolvam) e a conjunção atrai o pronome (proclítico: 'se envolvam')."}]}];
